module.exports = {"COURSE":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<style>html{color-scheme:light dark}[hidden]{display:none!important}img{max-width:100%}</style>\n<title>Avoidable Moments</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,400..800&family=Source+Sans+3:ital,wght@0,400;0,600;0,700;1,400&family=JetBrains+Mono:wght@400;600&display=swap\">\n<style>\n:root{\n  --ground:#F3F5F2;\n  --surface:#FFFFFF;\n  --surface-2:#E9EDE8;\n  --ink:#1B2530;\n  --muted:#58656E;\n  --line:#D3DAD4;\n  --accent:#0D7458;\n  --accent-ink:#FFFFFF;\n  --accent-soft:#DDEFE7;\n  --warn:#A8521A;\n  --warn-soft:#F7E6D8;\n  --bad:#AE3328;\n  --bad-soft:#F6DEDA;\n  --paper:#FFFEFA;\n  --paper-ink:#23282C;\n  --display:\"Archivo\",\"Arial Narrow\",system-ui,sans-serif;\n  --body:\"Source Sans 3\",\"Segoe UI\",system-ui,sans-serif;\n  --mono:\"JetBrains Mono\",ui-monospace,Menlo,Consolas,monospace;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --ground:#11161B;--surface:#192027;--surface-2:#222B33;--ink:#E4EAED;--muted:#9AA7AF;--line:#2E3942;\n    --accent:#3DBB90;--accent-ink:#0B1A14;--accent-soft:#16342A;--warn:#E39A62;--warn-soft:#3A2618;\n    --bad:#EE7F72;--bad-soft:#3B1D1A;--paper:#EDEBE3;--paper-ink:#1E2226;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --ground:#11161B;--surface:#192027;--surface-2:#222B33;--ink:#E4EAED;--muted:#9AA7AF;--line:#2E3942;\n  --accent:#3DBB90;--accent-ink:#0B1A14;--accent-soft:#16342A;--warn:#E39A62;--warn-soft:#3A2618;\n  --bad:#EE7F72;--bad-soft:#3B1D1A;--paper:#EDEBE3;--paper-ink:#1E2226;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{background:var(--ground);color:var(--ink);font-family:var(--body);font-size:17px;line-height:1.55;margin:0;padding-inline:clamp(16px,4vw,40px);padding-block:0 64px}\na{color:var(--accent)}\nbutton{font:inherit;color:inherit;cursor:pointer}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px;border-radius:4px}\nh1,h2,h3{font-family:var(--display);text-wrap:balance;margin:0;line-height:1.1}\nh1{font-size:clamp(2rem,5vw,3.1rem);font-variation-settings:\"wdth\" 82;font-weight:800;letter-spacing:-.01em}\nh2{font-size:clamp(1.5rem,3.2vw,2.05rem);font-variation-settings:\"wdth\" 86;font-weight:750}\nh3{font-size:1.15rem;font-variation-settings:\"wdth\" 100;font-weight:700}\np{margin:0}\n.eyebrow{font-family:var(--mono);font-size:.74rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.wrap{max-width:1120px;margin-inline:auto}\n.prose{max-width:66ch;display:grid;gap:14px}\n.muted{color:var(--muted)}\n\n/* top bar */\n.bar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-block:18px;border-bottom:1px solid var(--line);margin-bottom:32px;flex-wrap:wrap}\n.brand{display:flex;align-items:baseline;gap:10px;text-decoration:none;color:var(--ink)}\n.brand b{font-family:var(--display);font-variation-settings:\"wdth\" 75;font-weight:800;font-size:1.3rem;letter-spacing:.01em;text-transform:uppercase}\n.brand span{font-family:var(--mono);font-size:.72rem;color:var(--muted);letter-spacing:.08em;text-transform:uppercase}\n.bar nav{display:flex;gap:6px;flex-wrap:wrap}\n.chipbtn{border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:6px 14px;font-size:.9rem}\n.chipbtn:hover{border-color:var(--accent)}\n\n/* home */\n.hero{display:grid;grid-template-columns:1.25fr 1fr;gap:40px;align-items:start;margin-bottom:48px}\n.hero .lede{font-size:1.2rem;max-width:56ch}\n.motto{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}\n.motto span{font-family:var(--display);font-variation-settings:\"wdth\" 70;font-weight:800;text-transform:uppercase;font-size:1.05rem;letter-spacing:.03em;padding:6px 12px;border:2px solid var(--ink);border-radius:3px}\n.motto span:last-child{background:var(--ink);color:var(--ground)}\n.frame{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:22px;display:grid;gap:14px}\n.frame ol{list-style:none;margin:0;padding:0;display:grid;gap:10px;counter-reset:f}\n.frame li{display:grid;grid-template-columns:34px 1fr;gap:10px;align-items:start;counter-increment:f}\n.frame li::before{content:counter(f);font-family:var(--mono);font-weight:600;font-size:.85rem;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent)}\n.frame li b{display:block;font-family:var(--display);font-variation-settings:\"wdth\" 95}\n.frame li small{color:var(--muted);font-size:.9rem}\n\n.cat{margin-top:34px}\n.cat-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;border-bottom:2px solid var(--ink);padding-bottom:8px;margin-bottom:14px;flex-wrap:wrap}\n.cat-head h3{font-variation-settings:\"wdth\" 78;text-transform:uppercase;letter-spacing:.03em;font-size:1.05rem}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:14px}\n.sec{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:18px;display:flex;flex-direction:column;gap:10px;text-align:left}\n.sec.live{border-color:var(--accent);box-shadow:0 1px 0 var(--accent),0 10px 24px -18px var(--accent)}\n.sec h4{margin:0;font-family:var(--display);font-variation-settings:\"wdth\" 92;font-size:1.12rem}\n.sec p{font-size:.95rem;color:var(--muted)}\n.sec .foot{margin-top:auto;display:flex;justify-content:space-between;align-items:center;gap:8px;padding-top:6px}\n.pill{font-family:var(--mono);font-size:.68rem;letter-spacing:.08em;text-transform:uppercase;padding:3px 8px;border-radius:999px;white-space:nowrap}\n.pill.live{background:var(--accent-soft);color:var(--accent)}\n.pill.plan{background:var(--surface-2);color:var(--muted)}\n.pill.done{background:var(--accent);color:var(--accent-ink)}\n.btn{display:inline-flex;align-items:center;gap:8px;border:0;border-radius:8px;padding:10px 18px;background:var(--accent);color:var(--accent-ink);font-weight:700;text-decoration:none}\n.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--line)}\n.btn:disabled{opacity:.4;cursor:not-allowed}\n.sec details{font-size:.9rem}\n.sec summary{cursor:pointer;color:var(--ink);font-weight:600}\n.sec details ul{margin:8px 0 0;padding-left:18px;color:var(--muted)}\n\n/* module */\n.mod{display:grid;grid-template-columns:230px 1fr;gap:36px;align-items:start}\n.rail{position:sticky;top:16px;display:grid;gap:4px}\n.rail .eyebrow{margin-bottom:6px}\n.step{display:grid;grid-template-columns:22px 1fr;gap:10px;align-items:center;text-align:left;background:none;border:0;padding:8px 10px;border-radius:8px;color:var(--muted);font-size:.95rem}\n.step .dot{width:12px;height:12px;border-radius:50%;border:2px solid var(--line);justify-self:center}\n.step.seen .dot{background:var(--accent);border-color:var(--accent)}\n.step.on{background:var(--surface);color:var(--ink);font-weight:700;box-shadow:inset 0 0 0 1px var(--line)}\n.step.on .dot{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}\n.stage{display:grid;gap:26px;min-width:0}\n.stage-head{display:grid;gap:8px}\n.pager{display:flex;justify-content:space-between;gap:12px;border-top:1px solid var(--line);padding-top:20px;flex-wrap:wrap}\n\n.callout{border-left:4px solid var(--accent);background:var(--accent-soft);padding:14px 18px;border-radius:0 8px 8px 0;max-width:66ch}\n.callout.warn{border-color:var(--warn);background:var(--warn-soft)}\n.callout b{display:block;font-family:var(--display);font-variation-settings:\"wdth\" 90;margin-bottom:2px}\n.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;max-width:760px}\n.fact{background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:12px 14px}\n.fact .v{font-family:var(--display);font-variation-settings:\"wdth\" 80;font-weight:800;font-size:1.5rem;font-variant-numeric:tabular-nums}\n.fact .k{font-size:.85rem;color:var(--muted)}\nul.checks{list-style:none;padding:0;margin:0;display:grid;gap:8px;max-width:66ch}\nul.checks li{display:grid;grid-template-columns:22px 1fr;gap:8px}\nul.checks li::before{content:\"\";width:14px;height:8px;border-left:3px solid var(--accent);border-bottom:3px solid var(--accent);transform:rotate(-45deg);margin-top:6px}\n\n/* receipt transcript */\n.issue{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:28px;align-items:start}\n.tape{background:var(--paper);color:var(--paper-ink);font-family:var(--mono);font-size:.86rem;padding:22px 20px 26px;position:relative;box-shadow:0 14px 30px -20px rgba(0,0,0,.45);border-top:6px dotted var(--ground);border-bottom:6px dotted var(--ground);transform:rotate(.6deg)}\n.tape h5{margin:0 0 4px;text-align:center;font-size:.8rem;letter-spacing:.2em}\n.tape .rule{border-top:1px dashed currentColor;opacity:.5;margin:10px 0}\n.tape .row{display:flex;justify-content:space-between;gap:10px}\n.tape .paid{display:inline-block;border:2px solid #0D7458;color:#0D7458;padding:2px 8px;transform:rotate(-6deg);font-weight:600;letter-spacing:.12em;margin-top:10px}\n.log{list-style:none;margin:0;padding:0;display:grid;gap:0;border-left:2px solid var(--line);margin-left:6px}\n.log li{position:relative;padding:0 0 18px 22px}\n.log li::before{content:\"\";position:absolute;left:-7px;top:6px;width:12px;height:12px;border-radius:50%;background:var(--ground);border:2px solid var(--muted)}\n.log li.flag::before{border-color:var(--bad);background:var(--bad)}\n.log .who{font-family:var(--mono);font-size:.72rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}\n.log q{font-family:var(--display);font-variation-settings:\"wdth\" 90;font-weight:700;font-size:1.1rem;quotes:\"\\201C\" \"\\201D\"}\n.log details{margin-top:6px}\n.log summary{cursor:pointer;color:var(--bad);font-weight:600;font-size:.92rem;list-style:none}\n.log summary::-webkit-details-marker{display:none}\n.log summary::before{content:\"+ \";font-family:var(--mono)}\n.log details[open] summary::before{content:\"– \"}\n.log details p{background:var(--bad-soft);padding:10px 12px;border-radius:6px;margin-top:6px;font-size:.95rem}\n\n/* policy */\n.promise{background:var(--ink);color:var(--ground);border-radius:10px;padding:24px;display:grid;gap:8px;max-width:760px}\n.promise .eyebrow{color:inherit;opacity:.7}\n.promise p{font-family:var(--display);font-variation-settings:\"wdth\" 88;font-size:1.35rem;font-weight:700;line-height:1.25}\n.remedy{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;counter-reset:r}\n.remedy li{counter-increment:r;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:14px 12px;display:grid;gap:4px}\n.remedy li::before{content:counter(r);font-family:var(--mono);font-size:.78rem;color:var(--accent);font-weight:600}\n.remedy b{font-family:var(--display);font-variation-settings:\"wdth\" 88;font-size:1.05rem}\n.remedy small{color:var(--muted);font-size:.86rem;line-height:1.35}\n\n/* procedure */\n.proc{list-style:none;margin:0;padding:0;display:grid;gap:0;counter-reset:p;max-width:760px}\n.proc>li{counter-increment:p;display:grid;grid-template-columns:48px 1fr;gap:14px;padding:16px 0;border-top:1px solid var(--line)}\n.proc>li::before{content:counter(p);font-family:var(--display);font-variation-settings:\"wdth\" 70;font-weight:800;font-size:2rem;line-height:1;color:var(--accent)}\n.proc h3{margin-bottom:4px}\n.say{display:grid;gap:6px;margin-top:8px}\n.line{font-family:var(--display);font-variation-settings:\"wdth\" 92;font-weight:600;padding:10px 14px;border-radius:8px;background:var(--accent-soft);border:1px solid color-mix(in srgb,var(--accent) 30%,transparent)}\n.line.no{background:var(--bad-soft);border-color:color-mix(in srgb,var(--bad) 30%,transparent);text-decoration:line-through;text-decoration-color:var(--bad);text-decoration-thickness:2px}\n.branch{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px;margin-top:10px}\n.branch>div{background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:12px 14px;display:grid;gap:6px}\n.branch .eyebrow{font-size:.68rem}\n.tbl{overflow-x:auto;max-width:760px}\ntable{border-collapse:collapse;width:100%;min-width:520px;font-size:.95rem}\nth,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:top}\nth{font-family:var(--mono);font-size:.72rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:600}\ntd:first-child{color:var(--bad)}\ntd:last-child{color:var(--accent);font-weight:600}\n\n/* practice + quiz */\n.scene{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:22px;display:grid;gap:14px;max-width:760px}\n.scene .setup{font-size:1.02rem}\n.opts{display:grid;gap:8px}\n.opt{text-align:left;background:var(--ground);border:1px solid var(--line);border-radius:8px;padding:12px 14px;display:grid;grid-template-columns:26px 1fr;gap:10px;align-items:start}\n.opt:hover:not(:disabled){border-color:var(--accent)}\n.opt .k{font-family:var(--mono);font-weight:600;font-size:.85rem;color:var(--muted)}\n.opt.right{border-color:var(--accent);background:var(--accent-soft)}\n.opt.wrong{border-color:var(--bad);background:var(--bad-soft)}\n.opt:disabled{cursor:default}\n.fb{padding:12px 14px;border-radius:8px;font-size:.96rem}\n.fb.right{background:var(--accent-soft)}\n.fb.wrong{background:var(--bad-soft)}\n.fb b{font-family:var(--display);font-variation-settings:\"wdth\" 90}\n.meter{display:flex;gap:6px}\n.meter i{flex:1;height:6px;border-radius:3px;background:var(--line)}\n.meter i.ok{background:var(--accent)}\n.meter i.x{background:var(--bad)}\n.score{font-family:var(--display);font-variation-settings:\"wdth\" 75;font-weight:800;font-size:2.4rem;font-variant-numeric:tabular-nums}\n.sign{display:grid;gap:10px;max-width:640px}\n.sign label{display:grid;grid-template-columns:22px 1fr;gap:10px;align-items:start;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:12px 14px;cursor:pointer}\n.sign input{width:18px;height:18px;accent-color:var(--accent);margin-top:3px}\n.row2{display:flex;gap:10px;flex-wrap:wrap}\n\n/* quick checks + mini games */\n.qq{border:1.5px dashed var(--line);border-radius:10px;padding:16px 18px;display:grid;gap:10px;max-width:760px;background:var(--surface)}\n.qq .tag,.game .tag{display:inline-flex;align-items:center;gap:8px;font-family:var(--mono);font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;color:var(--accent);font-weight:600}\n.qq .tag::before{content:\"?\";width:18px;height:18px;border-radius:50%;background:var(--accent);color:var(--accent-ink);display:grid;place-items:center;font-size:.72rem}\n.game .tag::before{content:\"\";width:10px;height:10px;background:var(--accent);transform:rotate(45deg)}\n.qq h4{margin:0;font-family:var(--display);font-variation-settings:\"wdth\" 94;font-size:1.08rem}\n.game{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:22px;display:grid;gap:14px;max-width:760px;box-shadow:0 12px 28px -24px var(--ink)}\n.game-top{display:flex;justify-content:space-between;align-items:baseline;gap:10px;flex-wrap:wrap}\n.game-top h3{font-variation-settings:\"wdth\" 80;text-transform:uppercase;letter-spacing:.02em}\n.hud{font-family:var(--mono);font-size:.82rem;color:var(--muted);font-variant-numeric:tabular-nums;display:flex;gap:14px}\n.hud b{color:var(--ink)}\n.log .pick{all:unset;display:block;cursor:pointer;border-radius:6px;padding:4px 8px;margin-left:-8px;width:100%;box-sizing:border-box}\n.log .pick:hover{background:var(--surface-2)}\n.log .pick:focus-visible{outline:3px solid var(--accent)}\n.log li.picked .pick{background:var(--bad-soft)}\n.log li.picked::before{border-color:var(--bad);background:var(--bad)}\n.log li.hit::before{border-color:var(--accent);background:var(--accent)}\n.log li.miss::before{border-color:var(--warn);background:var(--warn)}\n.log li.false::before{border-color:var(--bad);background:var(--ground)}\n.log li.hit .pick,.log li.miss .pick,.log li.false .pick{background:none;cursor:default}\n.log .note{margin-top:6px;padding:10px 12px;border-radius:6px;font-size:.95rem;background:var(--bad-soft)}\n.log .note b{font-family:var(--display);font-variation-settings:\"wdth\" 90}\n.log li.hit .note{background:var(--accent-soft)}\n.log li.miss .note{background:var(--warn-soft)}\n.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:.85rem;color:var(--muted)}\n.legend i{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px;vertical-align:middle}\n.slots{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}\n.slot{min-height:64px;border:1.5px dashed var(--line);border-radius:8px;padding:8px;display:grid;gap:2px;align-content:start;font-size:.9rem}\n.slot small{font-family:var(--mono);color:var(--muted);font-size:.72rem}\n.slot.filled{border-style:solid;border-color:var(--accent);background:var(--accent-soft);font-weight:700;font-family:var(--display);font-variation-settings:\"wdth\" 88}\n.chips{display:flex;flex-wrap:wrap;gap:8px}\n.chip{border:1px solid var(--line);background:var(--ground);border-radius:999px;padding:8px 14px;text-align:left;font-size:.95rem}\n.chip:hover:not(:disabled){border-color:var(--accent)}\n.chip:disabled{opacity:.35;cursor:default}\n.chip.shake{border-color:var(--bad);background:var(--bad-soft)}\n.built{min-height:56px;border-radius:8px;padding:12px 14px;background:var(--paper);color:var(--paper-ink);font-family:var(--display);font-variation-settings:\"wdth\" 92;font-weight:600;display:flex;flex-wrap:wrap;gap:6px;align-items:center}\n.built .chip{background:#fff;color:var(--paper-ink);border-color:#cfd6d0}\n.built:empty::before{content:\"Tap phrases below to build the apology…\";color:#7b858b;font-weight:400;font-family:var(--body)}\n.card-flip{border-radius:10px;padding:20px;background:var(--paper);color:var(--paper-ink);font-family:var(--display);font-variation-settings:\"wdth\" 90;font-weight:700;font-size:1.25rem;text-align:center;min-height:96px;display:grid;place-items:center}\n.duo{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.duo .btn{justify-content:center;padding-block:14px;font-size:1.05rem}\n.btn.scrap{background:var(--bad);color:#fff}\n.timer{height:8px;border-radius:4px;background:var(--surface-2);overflow:hidden}\n.timer i{display:block;height:100%;background:var(--accent);width:100%;transform-origin:left}\n.timer.low i{background:var(--bad)}\n.badges{display:flex;flex-wrap:wrap;gap:8px}\n.badge{font-family:var(--mono);font-size:.74rem;letter-spacing:.06em;text-transform:uppercase;padding:6px 10px;border-radius:6px;border:1px solid var(--line);color:var(--muted)}\n.badge.got{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}\n.railscore{margin-top:12px;padding:10px;border-top:1px solid var(--line);font-size:.85rem;color:var(--muted)}\n.railscore b{font-family:var(--display);font-variation-settings:\"wdth\" 80;font-size:1.3rem;color:var(--ink);display:block}\n@media (prefers-reduced-motion:no-preference){ .chip.shake{animation:shake .3s} @keyframes shake{25%{transform:translateX(-4px)}75%{transform:translateX(4px)}} }\n\n\n\ntable.plain td:first-child{color:var(--ink);font-weight:700;white-space:nowrap}\ntable.plain td:last-child{color:var(--ink);font-weight:400}\n.journey{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:0;counter-reset:j;max-width:900px}\n.journey li{counter-increment:j;position:relative;padding:14px 14px 14px 16px;background:var(--surface);border:1px solid var(--line);margin-left:-1px;display:grid;gap:2px}\n.journey li:first-child{border-radius:8px 0 0 8px;margin-left:0}\n.journey li:last-child{border-radius:0 8px 8px 0}\n.journey li::before{content:counter(j);font-family:var(--mono);font-size:.72rem;color:var(--accent);font-weight:600}\n.journey b{font-family:var(--display);font-variation-settings:\"wdth\" 80;text-transform:uppercase;font-size:1.05rem;letter-spacing:.02em}\n.journey small{color:var(--muted);font-size:.84rem;line-height:1.3}\n.cases{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px}\n.case{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:18px;display:flex;flex-direction:column;gap:8px}\n.case-top{display:flex;justify-content:space-between;align-items:center;gap:8px}\n.case p{font-size:.95rem}\n.stopper{margin-top:auto;border-top:1px dashed var(--line);padding-top:10px;display:grid;gap:2px}\n.stopper p{font-weight:600;color:var(--accent)}\n.cpbtns{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}\n.cpbtn{border:1px solid var(--line);background:var(--ground);border-radius:8px;padding:10px 8px;display:grid;gap:2px;text-align:left}\n.cpbtn b{font-family:var(--display);font-variation-settings:\"wdth\" 80;text-transform:uppercase}\n.cpbtn small{color:var(--muted);font-size:.78rem;line-height:1.25}\n.cpbtn:hover:not(:disabled){border-color:var(--accent)}\n.cpbtn.right{border-color:var(--accent);background:var(--accent-soft)}\n.cpbtn.wrong{border-color:var(--bad);background:var(--bad-soft)}\n.cpbtn:disabled{cursor:default}\n.boxes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}\n.pbox{position:relative;display:grid;gap:8px;justify-items:center;padding:12px 10px 10px;border-radius:6px;background:#D9C3A0;border:2px solid #C4A97F;color:#3A2E20}\n.pbox .sticker{font-family:var(--mono);font-size:.7rem;font-weight:600;letter-spacing:.06em;background:#FFFEFA;padding:3px 8px;border-radius:3px;box-shadow:0 1px 0 rgba(0,0,0,.15);max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pbox .bx-state{font-family:var(--mono);font-size:.7rem;letter-spacing:.08em;text-transform:uppercase;min-height:1em;font-weight:600}\n.pbox.flag{outline:3px solid var(--bad);outline-offset:2px}\n.pbox.hit{outline:3px solid var(--accent);outline-offset:2px}\n.pbox.miss{outline:3px solid var(--warn);outline-offset:2px}\n.pbox.false{outline:3px dashed var(--bad);outline-offset:2px}\n.pbox.done{cursor:default}\n.pz{width:min(110px,100%);aspect-ratio:1;border-radius:50%;display:block;max-width:100%;\n  background:radial-gradient(circle,#F2C75C 0 60%,#D6953F 61% 100%)}\n.pz.pep{background:radial-gradient(circle at 32% 34%,#B8322A 0 8%,#0000 8.5%),radial-gradient(circle at 64% 30%,#B8322A 0 8%,#0000 8.5%),radial-gradient(circle at 50% 55%,#B8322A 0 8%,#0000 8.5%),radial-gradient(circle at 30% 66%,#B8322A 0 8%,#0000 8.5%),radial-gradient(circle at 68% 66%,#B8322A 0 8%,#0000 8.5%),radial-gradient(circle,#F2C75C 0 60%,#D6953F 61% 100%)}\n.pz.saus{background:radial-gradient(circle at 30% 36%,#6B3F24 0 4.5%,#0000 5%),radial-gradient(circle at 44% 28%,#6B3F24 0 4.5%,#0000 5%),radial-gradient(circle at 62% 38%,#6B3F24 0 4.5%,#0000 5%),radial-gradient(circle at 70% 56%,#6B3F24 0 4.5%,#0000 5%),radial-gradient(circle at 52% 52%,#6B3F24 0 4.5%,#0000 5%),radial-gradient(circle at 36% 58%,#6B3F24 0 4.5%,#0000 5%),radial-gradient(circle at 46% 72%,#6B3F24 0 4.5%,#0000 5%),radial-gradient(circle at 62% 70%,#6B3F24 0 4.5%,#0000 5%),radial-gradient(circle,#F2C75C 0 60%,#D6953F 61% 100%)}\n.pz.veg{background:radial-gradient(ellipse 9% 4% at 34% 34%,#3F8A3A 0 90%,#0000),radial-gradient(ellipse 4% 9% at 62% 32%,#3F8A3A 0 90%,#0000),radial-gradient(ellipse 9% 4% at 66% 62%,#3F8A3A 0 90%,#0000),radial-gradient(ellipse 4% 9% at 38% 64%,#3F8A3A 0 90%,#0000),radial-gradient(circle at 50% 48%,#8E5A9E 0 5%,#0000 5.5%),radial-gradient(circle at 52% 74%,#8E5A9E 0 5%,#0000 5.5%),radial-gradient(circle at 26% 50%,#8E5A9E 0 5%,#0000 5.5%),radial-gradient(circle,#F2C75C 0 60%,#D6953F 61% 100%)}\n.pz-key{display:inline-block;width:12px;height:12px;border-radius:50%;margin-right:6px;vertical-align:middle}\n.pz-key.pep{background:#B8322A}.pz-key.saus{background:#6B3F24}.pz-key.veg{background:#3F8A3A}.pz-key.cheese{background:#F2C75C;border:1px solid #D6953F}\n.bagwrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;align-items:start}\n.tape.mini{transform:none;padding:16px}\n.rline{all:unset;box-sizing:border-box;display:flex;justify-content:space-between;gap:8px;width:100%;padding:6px 6px;border-radius:4px;cursor:pointer;font-family:var(--mono);font-size:.84rem}\n.rline:hover:not(:disabled){background:#EEE9DC}\n.rline:focus-visible{outline:3px solid var(--accent)}\n.rline .mk{font-weight:600;color:#AE3328;font-size:.7rem;letter-spacing:.08em}\n.rline.on{background:#F6DEDA}\n.rline.hit{background:#DDEFE7}.rline.hit .mk{color:#0D7458}\n.rline.miss{background:#F7E6D8}.rline.miss .mk::after{content:\"MISSED\"}\n.rline.false{text-decoration:line-through}\n.rline:disabled{cursor:default}\n.bag{background:var(--surface-2);border-radius:10px 10px 18px 18px;padding:16px;display:grid;gap:8px;border-top:6px solid var(--line)}\n.bag ul{margin:0;padding-left:18px;display:grid;gap:4px}\n\n\n.ladder{list-style:none;margin:0;padding:0;display:grid;gap:6px;max-width:860px}\n.ladder li{display:grid;grid-template-columns:120px 1fr 1.2fr;gap:14px;align-items:start;background:var(--surface);border:1px solid var(--line);border-left:10px solid var(--lv);border-radius:6px;padding:12px 14px}\n.ladder b{font-family:var(--display);font-variation-settings:\"wdth\" 78;text-transform:uppercase;letter-spacing:.02em}\n.ladder span{color:var(--muted);font-size:.93rem}\n.ladder em{font-style:normal;font-weight:600;font-size:.93rem}\n.lvbtns{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}\n.lvbtn{border:1px solid var(--line);border-bottom:6px solid var(--lv);background:var(--ground);border-radius:8px;padding:12px 6px;font-family:var(--display);font-variation-settings:\"wdth\" 78;font-weight:700;text-transform:uppercase;font-size:.9rem}\n.lvbtn:hover:not(:disabled){border-color:var(--lv)}\n.lvbtn.right{background:var(--accent-soft);border-color:var(--accent);border-bottom-color:var(--lv)}\n.lvbtn.wrong{background:var(--bad-soft)}\n.lvbtn:disabled{cursor:default}\n.thermo{display:grid;gap:6px}\n.thermo-bar{position:relative;height:16px;border-radius:8px;background:linear-gradient(90deg,#2E9E77 0%,#D6AE3C 30%,#D9852F 50%,#C65A2A 70%,#A8322A 88%,#6E1C2A 100%)}\n.thermo-bar i{position:absolute;top:-5px;width:6px;height:26px;margin-left:-3px;border-radius:3px;background:var(--ink);box-shadow:0 0 0 2px var(--surface);transition:left .45s ease}\n.thermo-bar .goal{position:absolute;top:-4px;bottom:-4px;border-left:2px dashed var(--ink);opacity:.55}\n.thermo-lab{display:flex;justify-content:space-between;font-family:var(--mono);font-size:.74rem;color:var(--muted);font-variant-numeric:tabular-nums}\n@media (prefers-reduced-motion:reduce){.thermo-bar i{transition:none}}\n\n\n.lobby{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.lb{display:grid;gap:8px;text-align:left;background:var(--ground);border:1px solid var(--line);border-radius:10px;padding:14px;min-height:112px}\n.lb:hover:not(:disabled){border-color:var(--accent)}\n.lb-top{display:flex;justify-content:space-between;align-items:baseline;gap:8px}\n.lb-top b{font-family:var(--display);font-variation-settings:\"wdth\" 88}\n.lb-meter{height:10px;border-radius:5px;background:var(--surface-2);overflow:hidden;display:block}\n.lb-meter i{display:block;height:100%;transition:width .2s linear}\n.lb-st{font-family:var(--mono);font-size:.72rem;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}\n.lb.ready{border:2px solid var(--accent);background:var(--accent-soft)}\n.lb.ready .lb-st{color:var(--accent);font-weight:600}\n.lb.gone{opacity:.45}\n.qc{display:grid;grid-template-columns:auto 1fr;gap:18px;align-items:center;background:#D9C3A0;border-radius:10px;padding:16px;color:#3A2E20}\n.qc .pz{width:130px}\n.qc-info{display:grid;gap:2px}\n.qc-info .eyebrow{color:#6B5A43}\n.qc-info b{font-family:var(--display);font-variation-settings:\"wdth\" 85;font-size:1.3rem;margin-bottom:6px}\n.qc-info b.cold{color:#9E2A20}\n.pz.burnt{filter:brightness(.62) contrast(1.25) sepia(.35)}\n.pz.pale{filter:saturate(.35) brightness(1.18)}\n.pz.pepsparse{background:radial-gradient(circle at 34% 36%,#B8322A 0 8%,#0000 8.5%),radial-gradient(circle at 44% 58%,#B8322A 0 8%,#0000 8.5%),radial-gradient(circle,#F2C75C 0 60%,#D6953F 61% 100%)}\n.till{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n.till>div{background:var(--paper);color:var(--paper-ink);border-radius:8px;padding:12px;display:grid;gap:2px}\n.till .eyebrow{color:#6B737A}\n.till b{font-family:var(--mono);font-size:1.25rem;font-variant-numeric:tabular-nums}\n.till small{font-family:var(--mono);font-size:.75rem;color:#6B737A}\n.tray{min-height:58px;border:1.5px dashed var(--line);border-radius:10px;padding:8px;display:flex;flex-wrap:wrap;gap:6px;align-items:center}\n.tray:empty::before{content:\"Tap bills and coins below to build the change\";color:var(--muted);font-size:.9rem;padding-left:6px}\n.denoms{display:flex;flex-wrap:wrap;gap:8px}\n.dn{font-family:var(--mono);font-weight:600;border:1px solid #9FB8A5;font-size:.9rem}\n.dn.bill{background:#DCEBDD;color:#1E4A2C;border-radius:4px;padding:10px 12px;min-width:54px}\n.dn.coin{background:#E6E3DA;color:#3E3B33;border-radius:50%;width:48px;height:48px;border-color:#B7B1A1;padding:0}\n.dn:disabled{opacity:.5;cursor:default}\n\n@media (max-width:860px){\n  .till{grid-template-columns:1fr}\n  .qc{grid-template-columns:1fr;justify-items:center;text-align:center}\n  .ladder li{grid-template-columns:1fr;gap:4px}\n  .lvbtns{grid-template-columns:repeat(auto-fit,minmax(96px,1fr))}\n  .journey{grid-template-columns:1fr}.journey li,.journey li:first-child,.journey li:last-child{margin-left:0;margin-top:-1px;border-radius:0}\n  .journey li:first-child{border-radius:8px 8px 0 0}.journey li:last-child{border-radius:0 0 8px 8px}\n  .cpbtns{grid-template-columns:repeat(auto-fit,minmax(110px,1fr))}\n  .bagwrap{grid-template-columns:1fr}\n  .boxes{grid-template-columns:repeat(2,minmax(0,1fr))}\n  .slots{grid-template-columns:repeat(auto-fit,minmax(110px,1fr))}\n  .railscore{display:none}\n  .hero,.issue{grid-template-columns:1fr}\n  .mod{grid-template-columns:1fr;gap:20px}\n  .rail{position:static;display:flex;overflow-x:auto;gap:4px;padding-bottom:6px}\n  .rail .eyebrow{display:none}\n  .step{white-space:nowrap;grid-template-columns:14px auto;padding:8px 12px}\n  .remedy{grid-template-columns:1fr 1fr}\n}\n@media (max-width:480px){ .lobby{grid-template-columns:1fr}  .remedy{grid-template-columns:1fr} body{font-size:16px} }\n@media (prefers-reduced-motion:no-preference){ .stage{animation:rise .35s ease both} @keyframes rise{from{transform:translateY(6px)}to{transform:none}} }\n@media print{ .bar nav,.rail,.pager,.row2{display:none} .mod{display:block} body{background:#fff;color:#000} }\n</style>\n\n</head>\n<body>\n<div class=\"wrap\">\n  <header class=\"bar\">\n    <a class=\"brand\" href=\"#/\"><b>Avoidable Moments</b><span>AGM Customer Service Course</span></a>\n    <nav><a class=\"chipbtn\" href=\"/nibblenation\" style=\"text-decoration:none;color:inherit\">&larr; Hub</a><button class=\"chipbtn\" id=\"navHome\" type=\"button\">All sections</button><button class=\"chipbtn\" id=\"navReset\" type=\"button\">Reset my progress</button></nav>\n  </header>\n  <main id=\"app\"></main>\n</div>\n\n<script>\nconst PLAYBOOK_URL = \"/nibblenation/role-play-playbook\";\nconst STAGES = [\n  {id:\"welcome\",  label:\"Welcome\"},\n  {id:\"reason\",   label:\"The Reason\"},\n  {id:\"issue\",    label:\"The Issue\"},\n  {id:\"policy\",   label:\"Policy & Guidelines\"},\n  {id:\"procedure\",label:\"Procedure\"},\n  {id:\"practice\", label:\"Practice\"},\n  {id:\"check\",    label:\"Knowledge Check\"},\n  {id:\"complete\", label:\"Sign-off\"}\n];\n\nconst CATALOG = [\n  {cat:\"Payment & Transactions\", items:[\n    {id:\"unpaid-item\", live:true, title:\"The Unpaid-Item Assumption\", blurb:\"A customer is challenged over an item they already paid for — in front of other customers.\"},\n    {id:\"change-dispute\", live:true, title:\"Charge or Change Disputes\", blurb:\"Short change, overcharges, double card charges, and missed deals, settled without calling anyone a liar.\"}\n  ]},\n  {cat:\"Order Accuracy\", items:[\n    {id:\"wrong-order\", live:true, title:\"The Wrong Order\", blurb:\"Wrong item rung up, wrong item made, right pizza in the wrong box, a missing item, or an order handed to the wrong customer.\"},\n  ]},\n  {cat:\"Wait & Readiness\", items:[\n    {id:\"long-wait\", live:true, title:\"Order Not Ready on Time\", blurb:\"The promised time passes and the customer is still waiting, often with no idea why.\"}\n  ]},\n  {cat:\"Product Quality\", items:[\n    {id:\"quality\", live:true, title:\"Product Quality Complaint\", blurb:\"Cold, underbaked, burnt, or short on toppings, plus what changes when it's a food-safety issue.\"}\n  ]},\n  {cat:\"Escalation & Conduct\", items:[\n    {id:\"upset\", live:true, title:\"The Upset Customer\", blurb:\"A customer is angry and raising their voice. The whole line is watching how you respond.\"}\n  ]}\n];\n\nconst QUIZ1 = [\n  {q:\"A customer sets a drink from the cooler on the counter. You don't remember ringing it up. What comes first?\",\n   o:[\"Tell them the price so they can pay\",\"Ask them to show their receipt\",\"Check the POS transaction before saying anything about payment\",\"Ask a crew member if they saw the customer pay\"], a:2,\n   why:\"Verify first. The register can answer the question before the customer is ever put on the spot.\"},\n  {q:\"Which opening line meets the standard?\",\n   o:[\"“That's $3.90.”\",\"“Excuse me, let me make sure we included that drink with your order.”\",\"“Did you pay for that?”\",\"“That's how much it costs.”\"], a:1,\n   why:\"It puts the responsibility on the store's order, not on the customer's honesty.\"},\n  {q:\"The transaction shows the drink was paid for. Which apology is complete?\",\n   o:[\"“Sorry about that.”\",\"“Oh, okay, you're good.”\",\"“I apologize. I verified the transaction and you did pay for the drink. I should have checked the transaction before questioning you.”\",\"“Sorry, we get a lot of people who don't pay.”\"], a:2,\n   why:\"A full apology names what happened and owns the mistake — it doesn't just close the conversation.\"},\n  {q:\"Three other customers are standing at the counter. What changes?\",\n   o:[\"Nothing — handle it the same way\",\"Lower your voice, verify quietly, and avoid anything that looks like an accusation in front of others\",\"Ask the customer to step outside\",\"Wait until everyone leaves, then call the customer back\"], a:1,\n   why:\"Every reasonable effort should be made to avoid embarrassing the customer or creating the appearance of an accusation.\"},\n  {q:\"What is the correct order of the Remedy Process?\",\n   o:[\"Apologize, Listen, Take action, Remedy, Follow up\",\"Listen, Apologize sincerely, Determine a remedy, Take action, Follow up\",\"Listen, Determine a remedy, Apologize, Follow up, Take action\",\"Take action, Apologize, Listen, Follow up, Remedy\"], a:1,\n   why:\"Listen → Apologize sincerely → Determine an appropriate remedy → Take action → Follow up.\"}\n];\n\nconst SCENES1 = [\n  {title:\"Role-play 1 · The drink on the counter\", note:\"Prepares you for required role-play: a suspected unpaid beverage or merchandise item.\",\n   steps:[\n    {setup:\"It's a busy lunch rush. A customer who picked up an order a few minutes ago walks to the cooler, takes out a drink, and sets it on the counter. You don't remember ringing it up. Two other customers are waiting behind them.\",\n     o:[{t:\"“That's $3.90.”\",ok:false,f:\"This is exactly how the original incident began. A bare price implies the item hasn't been paid for — and everyone in line heard it.\"},\n        {t:\"Glance at the POS and pull up their transaction before saying anything about payment.\",ok:true,f:\"Verify first. You haven't said a word yet, so there's nothing to take back if it was paid.\"},\n        {t:\"“Did you pay for that?”\",ok:false,f:\"A direct payment challenge in front of others. Even if it's asked politely, it lands as an accusation.\"}]},\n    {setup:\"The screen is slow to load and the customer is looking at you. You need to say something while you check.\",\n     o:[{t:\"“Excuse me, let me make sure we included that drink with your order.”\",ok:true,f:\"Neutral and store-focused. It explains the pause without questioning the customer.\"},\n        {t:\"“Do you have your receipt?”\",ok:false,f:\"Asking for proof shifts the burden to the customer. Check your own records first.\"},\n        {t:\"Say nothing and stare at the screen.\",ok:false,f:\"Silence while holding their drink reads as suspicion. A short, neutral line keeps the moment calm.\"}]},\n    {setup:\"The transaction loads. The drink is on it — it was paid for.\",\n     o:[{t:\"“Oh — you're good.”\",ok:false,f:\"That closes the moment but doesn't repair it. The customer still feels questioned.\"},\n        {t:\"“I apologize. I verified the transaction and you did pay for the drink. I should have checked before questioning you.”\",ok:true,f:\"Complete recovery: apology, the facts, and ownership of the mistake.\"},\n        {t:\"“Sorry, we've had people walk out with drinks.”\",ok:false,f:\"Explaining why you suspected them makes it worse. Never justify the assumption to the customer.\"}]}\n   ]},\n  {title:\"Role-play 2 · The customer who's already upset\", note:\"Prepares you for required role-play: a customer who becomes upset after being questioned about an order or transaction.\",\n   steps:[\n    {setup:\"A crew member asked a customer about payment before checking. The customer is now upset: “You really think I'd steal a drink? In front of everybody?” You step in.\",\n     o:[{t:\"“Calm down, it was just a question.”\",ok:false,f:\"Telling someone to calm down dismisses the feeling. Step 1 of the Remedy Process is Listen.\"},\n        {t:\"Face them, keep your voice low, and let them finish without interrupting.\",ok:true,f:\"Listen. Let them say it fully. A customer who feels heard de-escalates faster than one who's corrected.\"},\n        {t:\"Explain that the crew member was only following procedure.\",ok:false,f:\"Defending the team before listening tells the customer their experience doesn't count.\"}]},\n    {setup:\"They've finished. You've checked the POS and the drink was paid for.\",\n     o:[{t:\"“I'm sorry. You did pay for it, and we should have checked our register before asking you. That's on us.”\",ok:true,f:\"Apologize sincerely — with the facts and ownership, not a general “sorry for the inconvenience.”\"},\n        {t:\"“Sorry for any confusion.”\",ok:false,f:\"“Confusion” suggests the misunderstanding was shared. It wasn't — the store made the error.\"},\n        {t:\"Hand the drink back and move to the next customer.\",ok:false,f:\"No apology, no remedy. The customer leaves with the embarrassment and no repair.\"}]},\n    {setup:\"The customer accepts the apology but is still clearly bothered. The crew member is standing nearby.\",\n     o:[{t:\"Offer a remedy that fits what they went through, thank them, and later retrain the crew member privately on verify-first.\",ok:true,f:\"Determine a remedy, take action, and follow up. The retraining is how you prevent the next one.\"},\n        {t:\"Correct the crew member at the counter so the customer sees it handled.\",ok:false,f:\"Public correction of a team member creates a second scene. Coaching happens privately.\"},\n        {t:\"Consider it resolved once they stop talking.\",ok:false,f:\"Skips remedy and follow-up. Managers are expected to retrain after a customer complaint.\"}]}\n   ]}\n];\n\n/* ---------- state ---------- */\nconst KEY=\"am-progress-v2\";\nlet ALL={sec:{}};\ntry{const raw=localStorage.getItem(KEY); if(raw) ALL=JSON.parse(raw)||ALL; else {const old=localStorage.getItem(\"am-progress-v1\"); if(old) ALL.sec[\"unpaid-item\"]=JSON.parse(old);}}catch(e){}\nALL.sec=ALL.sec||{};\nfunction st(id){const d=ALL.sec[id]=ALL.sec[id]||{}; d.seen=d.seen||{}; d.signed=d.signed||{}; d.games=d.games||{}; d.qq=d.qq||{}; if(d.quiz===undefined)d.quiz=null; return d;}\nlet S=st(\"unpaid-item\"), SEC=null;\nfunction save(){try{localStorage.setItem(KEY,JSON.stringify(ALL))}catch(e){}}\n\nconst app=document.getElementById(\"app\");\nconst esc=s=>s.replace(/[&<>\"]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));\nfunction go(h){location.hash=h}\ndocument.getElementById(\"navHome\").onclick=()=>go(\"#/\");\ndocument.getElementById(\"navReset\").onclick=()=>{if(confirm(\"Clear your progress in this course?\")){ALL={sec:{}};save();route();}};\n\n/* ---------- home ---------- */\nfunction home(){\n  const started=Object.keys(st(\"unpaid-item\").seen).length;\n  app.innerHTML=`\n  <section class=\"hero\">\n    <div class=\"prose\">\n      <span class=\"eyebrow\">Assistant General Manager track</span>\n      <h1>The serious service failures that never had to happen.</h1>\n      <p class=\"lede\">Each section in this course takes one real kind of customer-service breakdown, shows how it went wrong, and trains the procedure that would have prevented it. You protect the store's product. You also protect the customer's dignity. This course is about doing both at once.</p>\n      <div class=\"motto\" aria-label=\"Course standard\"><span>Verify first</span><span>Clarify second</span><span>Never accuse</span></div>\n      <div class=\"row2\" style=\"margin-top:10px\"><a class=\"btn\" href=\"#/m/unpaid-item/welcome\">${started?\"Continue\":\"Start\"} Section 1</a><a class=\"btn ghost\" href=\"${PLAYBOOK_URL}\" target=\"_blank\" rel=\"noopener\">Manager role-play playbook ↗</a></div>\n    </div>\n    <aside class=\"frame\" aria-label=\"How every section works\">\n      <span class=\"eyebrow\">How every section is built</span>\n      <ol>\n        <li><div><b>Welcome</b><small>What this section covers and what you'll be able to do.</small></div></li>\n        <li><div><b>The Reason</b><small>Why this moment matters to the customer, the room, and your role.</small></div></li>\n        <li><div><b>The Issue</b><small>Real cases, step by step, with the breakdowns marked.</small></div></li>\n        <li><div><b>Policy & Guidelines</b><small>The standards that apply, in plain language.</small></div></li>\n        <li><div><b>Procedure & Implementation</b><small>The exact steps and words to use — then practice, a check, and a manager sign-off.</small></div></li>\n      </ol>\n      <p class=\"muted\" style=\"font-size:.9rem\">Quick checks and mini games are built into every stage, so you practice the moment while you learn it.</p>\n    </aside>\n  </section>\n  ${CATALOG.map(c=>`\n    <section class=\"cat\">\n      <div class=\"cat-head\"><h3>${c.cat}</h3><span class=\"eyebrow\">${c.items.length} section${c.items.length>1?\"s\":\"\"}</span></div>\n      <div class=\"grid\">${c.items.map(it=>{ if(!it.live) return `\n        <div class=\"sec\">\n          <h4>${it.title}</h4><p>${it.blurb}</p>\n          <details><summary>Planned focus</summary><ul>${it.plan.map(p=>`<li>${p}</li>`).join(\"\")}</ul></details>\n          <div class=\"foot\"><span class=\"pill plan\">In development</span></div>\n        </div>`;\n        const d=st(it.id), sc=SECTIONS[it.id], done=d.quiz&&d.quiz.score>=4, gc=sc.games.filter(g=>d.games[g.id]).length;\n        return `\n        <a class=\"sec live\" href=\"#/m/${it.id}/welcome\" style=\"text-decoration:none;color:inherit\">\n          <h4>${it.title}</h4><p>${it.blurb}</p>\n          <div class=\"foot\"><span class=\"pill ${done?\"done\":\"live\"}\">Section ${sc.num} · ${done?\"Completed\":\"Available\"}</span><span class=\"muted\" style=\"font-size:.85rem\">~20 min · ${gc}/${sc.games.length} games · ${Object.keys(d.seen).length}/${STAGES.length} stages</span></div>\n        </a>`;}).join(\"\")}</div>\n    </section>`).join(\"\")}\n  <p class=\"muted\" style=\"margin-top:36px;font-size:.9rem;max-width:66ch\">Section 1 is drawn from a verified incident and has been anonymized. Sections 2–6 use typical cases from everyday store experience. Online completion prepares you for the live role-plays; it does not replace them.</p>`;\n}\n\n/* ---------- module ---------- */\nfunction sec1HTML(id){\n  switch(id){\n  case \"welcome\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Section 1 · Payment & Transactions</span><h2>The Unpaid-Item Assumption</h2></div>\n    <div class=\"prose\">\n      <p>This section covers a moment at the front counter that takes ten seconds to get right — and about the same to get wrong. A customer has an item in hand. You aren't sure it was paid for. What you do next decides whether the customer leaves served or leaves embarrassed.</p>\n      <p>By the end of this section you will be able to:</p>\n    </div>\n    <ul class=\"checks\">\n      <li>Verify a transaction before raising payment with a customer.</li>\n      <li>Open the conversation with neutral, store-focused language.</li>\n      <li>Handle a payment question without creating a scene in front of other customers.</li>\n      <li>Recover with a complete apology when the store got it wrong.</li>\n      <li>Apply the five-step Remedy Process to an upset customer.</li>\n    </ul>\n    <div class=\"facts\">\n      <div class=\"fact\"><div class=\"v\">~20</div><div class=\"k\">minutes online</div></div>\n      <div class=\"fact\"><div class=\"v\">2</div><div class=\"k\">practice role-plays</div></div>\n      <div class=\"fact\"><div class=\"v\">5</div><div class=\"k\">question knowledge check</div></div>\n      <div class=\"fact\"><div class=\"v\">5</div><div class=\"k\">mini games along the way</div></div>\n      <div class=\"fact\"><div class=\"v\">2</div><div class=\"k\">live role-plays with your manager</div></div>\n    </div>\n    <div class=\"qq\" data-qq=\"warmup\"></div>`;\n  case \"reason\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Why this matters</span><h2>Protect the product. Protect the person.</h2></div>\n    <div class=\"prose\">\n      <p>Safeguarding company assets is part of every manager's job. Nobody is asking you to stop noticing an item that might not be paid for. The problem is never <em>that</em> you checked — it's <em>how</em>.</p>\n      <p>When a payment question is raised before the facts are checked, the customer hears one thing: <strong>you think I took this.</strong> No one has to say the word \"theft.\" The tone and the timing say it for you.</p>\n      <p>And it isn't one customer who hears it. Everyone standing at the counter watches how the store treats people. A wrongful challenge in front of three or four customers damages trust with all of them.</p>\n    </div>\n    <div class=\"callout\"><b>Why AGMs are held to a higher standard</b>As an Assistant General Manager, you're expected to show more judgment, professionalism, and communication than an entry-level crew member. Crew members copy what you do at the counter. The way you handle this moment becomes the way your store handles it.</div>\n    <div class=\"qq\" data-qq=\"reason\"></div>`;\n  case \"issue\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">A real case · verified on video</span><h2>What happened at the counter</h2><p class=\"muted\" style=\"max-width:66ch\">The complaint was reviewed against store video and found to be substantiated. Details are anonymized.</p></div>\n    <div class=\"game\" style=\"max-width:none\">\n      <div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Spot the breakdown</h3></div><div class=\"hud\" id=\"spotHud\"><span>Picked <b id=\"spotN\">0</b></span><span>Breakdowns <b id=\"spotTotal\">4</b></span></div></div>\n      <p>Read the interaction top to bottom. Tap every line where it broke down, then check your picks.</p>\n      <div class=\"issue\">\n      <ol class=\"log\" id=\"spotLog\"></ol>\n      <div class=\"tape\" aria-label=\"Receipt illustration\">\n        <h5>ORDER RECEIPT</h5>\n        <div class=\"rule\"></div>\n        <div class=\"row\"><span>1 Pizza order</span><span>—</span></div>\n        <div class=\"row\"><span>1 Beverage</span><span>3.90</span></div>\n        <div class=\"rule\"></div>\n        <div class=\"row\"><strong>STATUS</strong><strong>PAID</strong></div>\n        <div style=\"text-align:center\"><span class=\"paid\">VERIFIED</span></div>\n        <div class=\"rule\"></div>\n        <p style=\"font-size:.78rem\">The answer was on the register the whole time. Checking it first would have taken seconds and ended the moment before it began.</p>\n      </div>\n      </div>\n      <div class=\"legend\" id=\"spotLegend\" hidden><span><i style=\"background:var(--accent)\"></i>Found</span><span><i style=\"background:var(--warn)\"></i>Missed</span><span><i style=\"border:2px solid var(--bad)\"></i>Not a breakdown</span></div>\n      <div class=\"fbwrap\" id=\"spotFb\"></div>\n      <div class=\"row2\" id=\"spotCtl\"></div>\n    </div>\n    <div class=\"callout warn\"><b>The finding</b>No one explicitly accused the customer. But the way the interaction started reasonably created the impression that the customer was being challenged for an unpaid item. That impression is the service failure.</div>`;\n  case \"policy\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Standards that apply</span><h2>Policy & Guidelines</h2></div>\n    <div class=\"promise\"><span class=\"eyebrow\">The Customer Promise</span><p>Friendly, professional service — because the customer is the most important person in the business.</p></div>\n    <div style=\"display:grid;gap:12px\">\n      <h3>The Remedy Process</h3>\n      <p class=\"muted\" style=\"max-width:66ch\">Use these five steps, in this order, whenever a service failure happens.</p>\n      <ol class=\"remedy\">\n        <li><b>Listen</b><small>Let the customer finish. Don't interrupt or defend.</small></li>\n        <li><b>Apologize sincerely</b><small>Name what went wrong and own it.</small></li>\n        <li><b>Determine a remedy</b><small>Decide what fairly makes it right.</small></li>\n        <li><b>Take action</b><small>Deliver the remedy right away.</small></li>\n        <li><b>Follow up</b><small>Confirm it's resolved and retrain to prevent a repeat.</small></li>\n      </ol>\n    </div>\n    <div style=\"display:grid;gap:12px;max-width:760px\">\n      <h3>Transaction verification rule</h3>\n      <p>Before questioning whether a customer has paid for merchandise, review the available transaction information whenever reasonably possible.</p>\n      <div class=\"motto\"><span>Verify first</span><span>Clarify second</span><span>Never accuse</span></div>\n    </div>\n    <div class=\"callout\"><b>Manager responsibility after a complaint</b>Managers are expected to retrain team members after a customer complaint so the same failure doesn't happen again.</div>\n    <div class=\"game\" id=\"remedyGame\"></div>\n    <div class=\"qq\" data-qq=\"policy\"></div>`;\n  case \"procedure\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Procedure & Implementation</span><h2>The verify-first procedure</h2><p class=\"muted\" style=\"max-width:66ch\">Follow these steps any time you're unsure whether an item in a customer's hands was paid for.</p></div>\n    <ol class=\"proc\">\n      <li><div><h3>Pause</h3><p>An item appears that you can't account for. Don't mention price or payment yet.</p></div></li>\n      <li><div><h3>Verify</h3><p>Check the POS transaction or order screen first. Your records answer the question — the customer shouldn't have to.</p></div></li>\n      <li><div><h3>Clarify — quietly</h3><p>If you need a moment to check, use a neutral line that points at the store's order, not the customer. Keep your voice low and speak to the customer, not the room.</p>\n        <div class=\"say\"><div class=\"line\">\"Excuse me, let me make sure we included that drink with your order.\"</div></div></div></li>\n      <li><div><h3>Resolve</h3><p>What you say next depends on what the register shows.</p>\n        <div class=\"branch\">\n          <div><span class=\"eyebrow\">It was paid</span><p>Thank them, return the item, and give a complete apology (step 5).</p></div>\n          <div><span class=\"eyebrow\">It isn't on the order</span><p>Treat it as the store's miss: <em>\"It looks like the drink didn't get added — I can ring that up for you now.\"</em></p></div>\n          <div><span class=\"eyebrow\">The customer is upset</span><p>Move to the Remedy Process. Escalate to the store manager following company policy.</p></div>\n        </div></div></li>\n      <li><div><h3>Recover</h3><p>If the store got it wrong, say so fully. Name the facts and own the mistake.</p>\n        <div class=\"say\"><div class=\"line\">\"I apologize. I verified the transaction and you did pay for the drink. I should have checked the transaction before questioning you.\"</div></div></div></li>\n      <li><div><h3>Follow up</h3><p>After the customer leaves, retrain any team member involved — privately. Share what happened so the whole shift uses verify-first.</p></div></li>\n    </ol>\n    <div style=\"display:grid;gap:12px\">\n      <h3>Say this, not that</h3>\n      <div class=\"tbl\"><table>\n        <thead><tr><th>Don't say</th><th>Why it fails</th><th>Say instead</th></tr></thead>\n        <tbody>\n          <tr><td>\"That's $3.90.\"</td><td>Implies the item wasn't paid for.</td><td>\"Let me make sure we included that drink with your order.\"</td></tr>\n          <tr><td>\"That's how much it costs.\"</td><td>Repeats the challenge instead of explaining.</td><td>\"Give me one second to check the order.\"</td></tr>\n          <tr><td>\"Do you have your receipt?\"</td><td>Makes the customer prove innocence.</td><td>Check the register yourself first.</td></tr>\n          <tr><td>\"Sorry about that.\"</td><td>Closes the moment without repairing it.</td><td>\"I should have checked the transaction before questioning you.\"</td></tr>\n        </tbody></table></div>\n    </div>\n    <div class=\"game\" id=\"sortGame\"></div>\n    <div class=\"game\" id=\"apologyGame\"></div>\n    <div class=\"qq\" data-qq=\"procedure\"></div>\n    <div style=\"display:grid;gap:12px\">\n      <h3>What's expected of you as an AGM</h3>\n      <ul class=\"checks\">\n        <li>Communicate professionally and respectfully with customers at all times.</li>\n        <li>Model proper customer service for crew members.</li>\n        <li>Resolve customer concerns without escalating avoidable conflict.</li>\n        <li>Verify facts before making assumptions about customer transactions.</li>\n        <li>Protect both company assets and the customer's dignity.</li>\n        <li>Use the Remedy Process when a service failure occurs.</li>\n        <li>Show sound management judgment in public-facing situations.</li>\n      </ul>\n    </div>`;\n  }\n}\n\nfunction stageHTML(id){\n  if(id===\"practice\") return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Practice</span><h2>Make the call</h2><p class=\"muted\" style=\"max-width:66ch\">Choose what you'd do at each point. You'll see why each option works or doesn't. These mirror the role-plays you'll demonstrate live.</p></div>\n    ${SEC.scenes.map((s,i)=>`<div class=\"scene\" id=\"scene${i}\"></div>`).join(\"\")}\n    <div class=\"game\" id=\"rushGame\"></div>`;\n  if(id===\"check\") return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Knowledge check</span><h2>Five questions</h2><p class=\"muted\">Score 4 or better to complete the online portion.</p></div>\n    <div class=\"scene\" id=\"quiz\"></div>`;\n  if(id===\"complete\"){\n    const q=S.quiz; const passed=q&&q.score>=4;\n    return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Sign-off · Section ${SEC.num}</span><h2>${passed?\"Online portion complete\":\"Almost there\"}</h2></div>\n    <div class=\"facts\">\n      <div class=\"fact\"><div class=\"v\">${Object.keys(S.seen).length}/${STAGES.length}</div><div class=\"k\">stages viewed</div></div>\n      <div class=\"fact\"><div class=\"v\">${q?q.score+\"/5\":\"—\"}</div><div class=\"k\">knowledge check</div></div>\n      <div class=\"fact\"><div class=\"v\">${gamesCleared()}/${SEC.games.length}</div><div class=\"k\">mini games cleared</div></div>\n    </div>\n    <div style=\"display:grid;gap:10px\"><h3>Badges</h3><div class=\"badges\">${SEC.games.map(g=>`<span class=\"badge ${S.games[g.id]?\"got\":\"\"}\">${g.badge}</span>`).join(\"\")}</div></div>\n    ${passed?\"\":`<div class=\"callout warn\"><b>Knowledge check not passed yet</b>Complete the knowledge check with 4 or more correct before your manager signs off.</div>`}\n    <div class=\"prose\"><p>The online section prepares you. The standard is met when you demonstrate it live. Work through this list with your manager.</p></div>\n    <div class=\"callout\"><b>Managers: run the live role-plays from the playbook</b>Scripts, curveball lines, scorecards, and the sign-off block for role-plays ${SEC.num}A and ${SEC.num}B. <a href=\"${PLAYBOOK_URL}#s${SEC.num}\" target=\"_blank\" rel=\"noopener\">Open the Section ${SEC.num} role-plays ↗</a></div>\n    <div class=\"sign\">\n      ${SEC.sign.map(([k,t])=>`\n        <label for=\"sg-${SEC.id}-${k}\"><input type=\"checkbox\" id=\"sg-${SEC.id}-${k}\" data-k=\"${k}\" ${S.signed[k]?\"checked\":\"\"}><span>${t}</span></label>`).join(\"\")}\n    </div>\n    <div class=\"row2\"><button class=\"btn ghost\" type=\"button\" id=\"printBtn\">Print this page</button>${SEC.next?`<a class=\"btn\" href=\"#/m/${SEC.next}/welcome\">Next section →</a>`:\"\"}<a class=\"btn ghost\" href=\"#/\">All sections</a></div>`;}\n  return SEC.html(id);\n}\n\nfunction module(stage){\n  clearInterval(rushTimer);\n  const idx=Math.max(0,STAGES.findIndex(s=>s.id===stage));\n  const st=STAGES[idx];\n  S.seen[st.id]=1; save();\n  app.innerHTML=`\n  <div class=\"mod\">\n    <nav class=\"rail\" aria-label=\"Section stages\">\n      <span class=\"eyebrow\">Section ${SEC.num} stages</span>\n      ${STAGES.map((s,i)=>`<button type=\"button\" class=\"step ${i===idx?\"on\":\"\"} ${S.seen[s.id]?\"seen\":\"\"}\" data-s=\"${s.id}\" ${i===idx?'aria-current=\"step\"':\"\"}><span class=\"dot\"></span><span>${s.label}</span></button>`).join(\"\")}\n      <div class=\"railscore\"><b>${gamesCleared()}/${SEC.games.length}</b>mini games cleared</div>\n    </nav>\n    <article class=\"stage\">\n      ${stageHTML(st.id)}\n      <div class=\"pager\">\n        ${idx>0?`<a class=\"btn ghost\" href=\"#/m/${SEC.id}/${STAGES[idx-1].id}\">← ${STAGES[idx-1].label}</a>`:`<a class=\"btn ghost\" href=\"#/\">← All sections</a>`}\n        ${idx<STAGES.length-1?`<a class=\"btn\" href=\"#/m/${SEC.id}/${STAGES[idx+1].id}\">${STAGES[idx+1].label} →</a>`:\"\"}\n      </div>\n    </article>\n  </div>`;\n  app.querySelectorAll(\".step\").forEach(b=>b.onclick=()=>go(`#/m/${SEC.id}/${b.dataset.s}`));\n  app.querySelectorAll(\"[data-qq]\").forEach(el=>quick(el,el.dataset.qq));\n  SEC.mount(st.id);\n  if(st.id===\"practice\"){ SEC.scenes.forEach((s,i)=>runScene(i,0,[])); rushIntro(); }\n  if(st.id===\"check\") runQuiz(0,[]);\n  if(st.id===\"complete\"){\n    app.querySelectorAll(\".sign input\").forEach(c=>c.onchange=()=>{S.signed[c.dataset.k]=c.checked;save();});\n    document.getElementById(\"printBtn\").onclick=()=>window.print();\n  }\n  window.scrollTo({top:0});\n}\n\nfunction runScene(i,step,hist){\n  const s=SEC.scenes[i], el=document.getElementById(\"scene\"+i);\n  if(step>=s.steps.length){\n    const right=hist.filter(Boolean).length;\n    el.innerHTML=`<span class=\"eyebrow\">${esc(s.title)}</span>\n      <div class=\"meter\">${hist.map(h=>`<i class=\"${h?\"ok\":\"x\"}\"></i>`).join(\"\")}</div>\n      <h3>${right===s.steps.length?\"Handled to standard.\":`${right} of ${s.steps.length} to standard.`}</h3>\n      <p class=\"muted\">${esc(s.note)}</p>\n      <div class=\"row2\"><button class=\"btn ghost\" type=\"button\" data-r>Run it again</button></div>`;\n    el.querySelector(\"[data-r]\").onclick=()=>runScene(i,0,[]);\n    return;\n  }\n  const p=s.steps[step];\n  el.innerHTML=`<span class=\"eyebrow\">${esc(s.title)} · decision ${step+1} of ${s.steps.length}</span>\n    <div class=\"meter\">${s.steps.map((_,k)=>`<i class=\"${k<hist.length?(hist[k]?\"ok\":\"x\"):\"\"}\"></i>`).join(\"\")}</div>\n    <p class=\"setup\">${esc(p.setup)}</p>\n    <div class=\"opts\">${p.o.map((o,k)=>`<button type=\"button\" class=\"opt\" data-k=\"${k}\"><span class=\"k\">${\"ABC\"[k]}</span><span>${esc(o.t)}</span></button>`).join(\"\")}</div>\n    <div class=\"fbwrap\"></div>`;\n  el.querySelectorAll(\".opt\").forEach(b=>b.onclick=()=>{\n    const o=p.o[+b.dataset.k];\n    el.querySelectorAll(\".opt\").forEach((x,k)=>{x.disabled=true; if(p.o[k].ok) x.classList.add(\"right\");});\n    if(!o.ok) b.classList.add(\"wrong\");\n    el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${o.ok?\"right\":\"wrong\"}\"><b>${o.ok?\"Meets the standard. \":\"Falls short. \"}</b>${esc(o.f)}</div>\n      <div class=\"row2\" style=\"margin-top:10px\"><button class=\"btn\" type=\"button\" data-n>${step+1<s.steps.length?\"Next decision\":\"See result\"}</button></div>`;\n    el.querySelector(\"[data-n]\").onclick=()=>runScene(i,step+1,[...hist,o.ok]);\n  });\n}\n\nfunction runQuiz(n,ans){\n  const el=document.getElementById(\"quiz\");\n  if(n>=SEC.quiz.length){\n    const score=ans.filter((a,k)=>a===SEC.quiz[k].a).length;\n    S.quiz={score}; save();\n    el.innerHTML=`<span class=\"eyebrow\">Result</span><div class=\"score\">${score}/5</div>\n      <div class=\"meter\">${ans.map((a,k)=>`<i class=\"${a===SEC.quiz[k].a?\"ok\":\"x\"}\"></i>`).join(\"\")}</div>\n      <p>${score>=4?\"Passed. Continue to sign-off with your manager.\":\"Not yet. Review The Issue and Procedure stages, then try again.\"}</p>\n      <div class=\"row2\"><button class=\"btn ghost\" type=\"button\" data-r>Retake</button>${score>=4?`<a class=\"btn\" href=\"#/m/${SEC.id}/complete\">Go to sign-off →</a>`:`<a class=\"btn\" href=\"#/m/${SEC.id}/procedure\">Review procedure</a>`}</div>`;\n    el.querySelector(\"[data-r]\").onclick=()=>runQuiz(0,[]);\n    return;\n  }\n  const q=SEC.quiz[n];\n  el.innerHTML=`<span class=\"eyebrow\">Question ${n+1} of ${SEC.quiz.length}</span>\n    <div class=\"meter\">${SEC.quiz.map((_,k)=>`<i class=\"${k<ans.length?(ans[k]===SEC.quiz[k].a?\"ok\":\"x\"):\"\"}\"></i>`).join(\"\")}</div>\n    <h3 style=\"font-size:1.25rem\">${esc(q.q)}</h3>\n    <div class=\"opts\">${q.o.map((o,k)=>`<button type=\"button\" class=\"opt\" data-k=\"${k}\"><span class=\"k\">${\"ABCD\"[k]}</span><span>${esc(o)}</span></button>`).join(\"\")}</div>\n    <div class=\"fbwrap\"></div>`;\n  el.querySelectorAll(\".opt\").forEach(b=>b.onclick=()=>{\n    const k=+b.dataset.k, ok=k===q.a;\n    el.querySelectorAll(\".opt\").forEach((x,j)=>{x.disabled=true; if(j===q.a) x.classList.add(\"right\");});\n    if(!ok) b.classList.add(\"wrong\");\n    el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${ok?\"Correct. \":\"Not quite. \"}</b>${esc(q.why)}</div>\n      <div class=\"row2\" style=\"margin-top:10px\"><button class=\"btn\" type=\"button\" data-n>${n+1<SEC.quiz.length?\"Next question\":\"See score\"}</button></div>`;\n    el.querySelector(\"[data-n]\").onclick=()=>runQuiz(n+1,[...ans,k]);\n  });\n}\n\n/* ---------- quick checks + mini games ---------- */\nconst GAMES1=[\n  {id:\"spot\",badge:\"Breakdown Spotter\"},\n  {id:\"remedy\",badge:\"Remedy in Order\"},\n  {id:\"sort\",badge:\"Right Words\"},\n  {id:\"apology\",badge:\"Full Recovery\"},\n  {id:\"rush\",badge:\"Counter Ready\"}\n];\nfunction gamesCleared(){return SEC.games.filter(g=>S.games[g.id]).length}\nfunction clearGame(id){if(!S.games[id]){S.games[id]=1;save();const r=document.querySelector(\".railscore b\");if(r)r.textContent=gamesCleared()+\"/\"+SEC.games.length;}}\nconst shuffle=a=>{const b=a.slice();for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};\n\nconst QQ1={\n  warmup:{q:\"Warm-up · True or false: if nobody says the word “theft,” it can't feel like an accusation.\",o:[\"True\",\"False\"],a:1,\n    why:\"False. Tone, timing, and who's watching can accuse someone without one accusing word. That's what this section is about.\"},\n  reason:{q:\"In this case, what was the real problem?\",o:[\"The AGM noticed the drink\",\"The AGM tried to protect store inventory\",\"The method — payment was raised before the transaction was checked\",\"The customer didn't keep the receipt out\"],a:2,\n    why:\"Protecting assets is part of the job. The failure was the method: challenge first, verify later.\"},\n  policy:{q:\"Before questioning whether a customer paid, you should…\",o:[\"Ask for the receipt\",\"Review the available transaction information whenever reasonably possible\",\"Ask a crew member what they saw\",\"Say the price and watch how they react\"],a:1,\n    why:\"That's the transaction verification rule, word for word. Verify first.\"},\n  procedure:{q:\"The register shows the drink really isn't on the order. What do you say?\",o:[\"“You didn't pay for this.”\",\"“That's $3.90.”\",\"“It looks like the drink didn't get added — I can ring that up for you now.”\",\"“I need to see your receipt.”\"],a:2,\n    why:\"Even when it wasn't paid, treat it as the store's miss. Never accuse.\"}\n};\nfunction quick(el,key){\n  const d=SEC.qq[key]; if(!d) return;\n  el.innerHTML=`<span class=\"tag\">Quick check</span><h4>${esc(d.q)}</h4>\n    <div class=\"opts\">${d.o.map((o,k)=>`<button type=\"button\" class=\"opt\" data-k=\"${k}\"><span class=\"k\">${\"ABCD\"[k]}</span><span>${esc(o)}</span></button>`).join(\"\")}</div><div class=\"fbwrap\"></div>`;\n  el.querySelectorAll(\".opt\").forEach(b=>b.onclick=()=>{\n    const k=+b.dataset.k,ok=k===d.a;\n    el.querySelectorAll(\".opt\").forEach((x,j)=>{x.disabled=true;if(j===d.a)x.classList.add(\"right\")});\n    if(!ok)b.classList.add(\"wrong\");\n    S.qq[key]=ok?1:0;save();\n    el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${ok?\"Right. \":\"Not quite. \"}</b>${esc(d.why)}</div>\n      <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn ghost\" data-r>Try again</button></div>`;\n    el.querySelector(\"[data-r]\").onclick=()=>quick(el,key);\n  });\n}\n\n/* Spot the breakdown */\nconst LOG=[\n  {who:\"Earlier\",t:\"The customer buys an order that includes a beverage.\",no:\"Normal purchase — nothing went wrong yet.\"},\n  {who:\"Later\",t:\"The customer takes the beverage from the cooler and sets it on the counter. Three or four other customers are nearby.\",no:\"The customer is doing nothing wrong here. This is the moment to verify, not to react.\"},\n  {who:\"AGM\",q:\"That's $3.90.\",flag:\"No verification\",note:\"Payment was raised before the transaction was checked. Said flatly, with no explanation, the price implied the drink hadn't been paid for.\"},\n  {who:\"Customer\",q:\"Excuse me?\",no:\"This is the customer reacting to the breakdown just before it.\"},\n  {who:\"AGM\",t:\"Repeats that this is what the drink costs — \",q:\"That's how much it costs.\",flag:\"Tone\",note:\"Restating the price instead of explaining turned a question into a confrontation. The customer was now defending themselves.\"},\n  {who:\"Customer\",t:\"Asks whether the AGM thinks the drink wasn't paid for.\",no:\"The customer is naming what the interaction implied. Their question is fair.\"},\n  {who:\"AGM\",t:\"Asks for the receipt. Reviews it and doesn't spot the drink right away.\",flag:\"Public handling\",note:\"The customer was made to prove payment in front of others. The store's own records should have been checked, quietly.\"},\n  {who:\"AGM\",t:\"Checks the register transaction. The drink was paid for.\",no:\"This is the right action — it just came too late. It should have been the first step.\"},\n  {who:\"AGM\",t:\"Apologizes.\",flag:\"Incomplete recovery\",note:\"The apology didn't name what happened or own the mistake. The customer was left without real acknowledgment of being wrongly questioned.\"}\n];\nfunction spotGame(){\n  const ol=document.getElementById(\"spotLog\"),ctl=document.getElementById(\"spotCtl\"),fb=document.getElementById(\"spotFb\"),leg=document.getElementById(\"spotLegend\"),n=document.getElementById(\"spotN\");\n  const picked=new Set();\n  const LG=SEC.log||LOG, FL=LG.filter(l=>l.flag).length; const tot=document.getElementById(\"spotTotal\"); if(tot)tot.textContent=FL;\n  ol.innerHTML=LG.map((l,i)=>`<li data-i=\"${i}\"><button type=\"button\" class=\"pick\" aria-pressed=\"false\"><span class=\"who\">${l.who}</span><p>${l.t?esc(l.t):\"\"}${l.q?`<q>${esc(l.q)}</q>`:\"\"}</p></button><div class=\"note\" hidden></div></li>`).join(\"\");\n  fb.innerHTML=\"\";leg.hidden=true;n.textContent=\"0\";\n  const draw=()=>{ctl.innerHTML=`<button type=\"button\" class=\"btn\" id=\"spotCheck\" ${picked.size?\"\":\"disabled\"}>Check my picks</button>`;\n    document.getElementById(\"spotCheck\").onclick=check;};\n  ol.querySelectorAll(\"li\").forEach(li=>li.querySelector(\".pick\").onclick=()=>{\n    const i=+li.dataset.i; if(li.classList.contains(\"done\"))return;\n    picked.has(i)?picked.delete(i):picked.add(i);\n    li.classList.toggle(\"picked\",picked.has(i)); li.querySelector(\".pick\").setAttribute(\"aria-pressed\",picked.has(i));\n    n.textContent=picked.size; draw();\n  });\n  function check(){\n    let hits=0,falses=0;\n    ol.querySelectorAll(\"li\").forEach(li=>{\n      const i=+li.dataset.i,l=LG[i],p=picked.has(i),note=li.querySelector(\".note\");\n      li.classList.remove(\"picked\");li.classList.add(\"done\");\n      if(l.flag){ li.classList.add(p?\"hit\":\"miss\"); if(p)hits++; note.hidden=false; note.innerHTML=`<b>${p?\"Found\":\"Missed\"} — ${l.flag}. </b>${esc(l.note)}`; }\n      else if(p){ falses++; li.classList.add(\"false\"); note.hidden=false; note.innerHTML=`<b>Not a breakdown. </b>${esc(l.no)}`; }\n    });\n    leg.hidden=false;\n    const perfect=hits===FL&&falses===0; if(perfect)clearGame(\"spot\");\n    fb.innerHTML=`<div class=\"fb ${perfect?\"right\":\"wrong\"}\"><b>${hits} of ${FL} found${falses?`, ${falses} extra`:\"\"}. </b>${perfect?\"Every breakdown spotted. Badge earned: Breakdown Spotter.\":\"Read the notes on each line, then play again to clear it.\"}</div>`;\n    ctl.innerHTML=`<button type=\"button\" class=\"btn ghost\" id=\"spotAgain\">Play again</button>`;\n    document.getElementById(\"spotAgain\").onclick=spotGame;\n  }\n  draw();\n}\n\n/* Remedy in order */\nconst REMEDY=[\"Listen\",\"Apologize sincerely\",\"Determine a remedy\",\"Take action\",\"Follow up\"];\nfunction remedyGame(){\n  const el=document.getElementById(\"remedyGame\");\n  let order; do{order=shuffle(REMEDY)}while(order.join()===REMEDY.join());\n  let pos=0,miss=0; const t0=Date.now();\n  el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Remedy in order</h3></div><div class=\"hud\"><span>Mistakes <b id=\"rmMiss\">0</b></span><span>Time <b id=\"rmTime\">0s</b></span></div></div>\n    <p>Tap the five Remedy Process steps in the right order. Clear it with no mistakes.</p>\n    <div class=\"slots\">${REMEDY.map((_,i)=>`<div class=\"slot\" data-s=\"${i}\"><small>Step ${i+1}</small></div>`).join(\"\")}</div>\n    <div class=\"chips\">${order.map(o=>`<button type=\"button\" class=\"chip\" data-v=\"${esc(o)}\">${esc(o)}</button>`).join(\"\")}</div>\n    <div class=\"fbwrap\"></div>`;\n  const tick=setInterval(()=>{const t=document.getElementById(\"rmTime\"); if(!t){clearInterval(tick);return} t.textContent=Math.round((Date.now()-t0)/1000)+\"s\"},500);\n  el.querySelectorAll(\".chip\").forEach(c=>c.onclick=()=>{\n    if(c.dataset.v===REMEDY[pos]){\n      const s=el.querySelector(`.slot[data-s=\"${pos}\"]`); s.classList.add(\"filled\"); s.innerHTML=`<small>Step ${pos+1}</small>${esc(REMEDY[pos])}`;\n      c.disabled=true; pos++;\n      if(pos===REMEDY.length){ clearInterval(tick); const secs=Math.round((Date.now()-t0)/1000);\n        if(!miss)clearGame(\"remedy\");\n        el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${miss?\"wrong\":\"right\"}\"><b>${miss?`Done with ${miss} mistake${miss>1?\"s\":\"\"}. `:`Perfect in ${secs}s. `}</b>${miss?\"Run it again and clear it clean.\":\"Badge earned: Remedy in Order.\"}</div>\n          <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n        el.querySelector(\"[data-r]\").onclick=remedyGame; }\n    } else { miss++; document.getElementById(\"rmMiss\").textContent=miss; c.classList.remove(\"shake\"); void c.offsetWidth; c.classList.add(\"shake\"); }\n  });\n}\n\n/* Say it or scrap it */\nconst SORT1=[\n  {t:\"Excuse me, let me make sure we included that drink with your order.\",say:true,why:\"Neutral and points at the store's order, not the customer.\"},\n  {t:\"That's $3.90.\",say:false,why:\"A bare price implies the item wasn't paid for.\"},\n  {t:\"Give me one second to check the order.\",say:true,why:\"Explains the pause without questioning anyone.\"},\n  {t:\"Did you pay for that?\",say:false,why:\"A direct payment challenge — it lands as an accusation.\"},\n  {t:\"It looks like the drink didn't get added — I can ring that up for you now.\",say:true,why:\"Even when it wasn't paid, the store owns the miss.\"},\n  {t:\"That's how much it costs.\",say:false,why:\"Repeats the challenge instead of explaining.\"},\n  {t:\"I apologize. I verified the transaction and you did pay for the drink.\",say:true,why:\"Apology plus the facts — the start of a full recovery.\"},\n  {t:\"Sorry for any confusion.\",say:false,why:\"Suggests the misunderstanding was shared. It wasn't.\"},\n  {t:\"We've had people walk out with drinks.\",say:false,why:\"Justifying the suspicion makes it worse.\"}\n];\nfunction sortGame(){\n  const el=document.getElementById(\"sortGame\"); const deck=shuffle(SEC.sort); let i=0,score=0,streak=0,best=0;\n  const head=()=>`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Say it or scrap it</h3></div><div class=\"hud\"><span>Card <b>${Math.min(i+1,deck.length)}/${deck.length}</b></span><span>Score <b>${score}</b></span><span>Streak <b>${streak}</b></span></div></div>`;\n  function card(){\n    if(i>=deck.length){ const ok=score>=deck.length-1; if(ok)clearGame(\"sort\");\n      el.innerHTML=head()+`<div class=\"score\">${score}/${deck.length}</div><p>Best streak: ${best}. ${ok?\"Badge earned: Right Words.\":`Score ${deck.length-1} or better to clear it.`}</p>\n        <div class=\"row2\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n      el.querySelector(\"[data-r]\").onclick=sortGame; return; }\n    const c=deck[i];\n    el.innerHTML=head()+`<p>Would you say this at the counter?</p><div class=\"card-flip\">“${esc(c.t)}”</div>\n      <div class=\"duo\"><button type=\"button\" class=\"btn\" data-a=\"1\">Say it</button><button type=\"button\" class=\"btn scrap\" data-a=\"0\">Scrap it</button></div><div class=\"fbwrap\"></div>`;\n    el.querySelectorAll(\"[data-a]\").forEach(b=>b.onclick=()=>{\n      const ok=(b.dataset.a===\"1\")===c.say; if(ok){score++;streak++;best=Math.max(best,streak)}else streak=0;\n      el.querySelectorAll(\"[data-a]\").forEach(x=>x.disabled=true);\n      el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${c.say?\"Say it. \":\"Scrap it. \"}</b>${esc(c.why)}</div>\n        <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn\" data-n>${i+1<deck.length?\"Next card\":\"See score\"}</button></div>`;\n      el.querySelector(\"[data-n]\").onclick=()=>{i++;card()};\n    });\n  }\n  card();\n}\n\n/* Apology builder */\nconst PIECES=[\n  {t:\"I apologize.\",k:\"apology\",ord:0},\n  {t:\"I verified the transaction\",k:\"fact\",ord:1},\n  {t:\"and you did pay for the drink.\",k:\"fact2\",ord:2},\n  {t:\"I should have checked the transaction before questioning you.\",k:\"own\",ord:3},\n  {t:\"Sorry for any confusion.\",d:\"“Confusion” suggests the mistake was shared.\"},\n  {t:\"We've had people walk out with drinks.\",d:\"Never explain why you suspected them.\"},\n  {t:\"You're good.\",d:\"Closes the moment without repairing it.\"},\n  {t:\"Next time, keep your receipt out.\",d:\"Puts the burden back on the customer.\"}\n];\nfunction apologyGame(){\n  const el=document.getElementById(\"apologyGame\"); const pool=shuffle(PIECES.map((p,i)=>i)); let built=[];\n  el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Build the apology</h3></div><div class=\"hud\"><span>Pieces <b id=\"apN\">0</b></span></div></div>\n    <p>The drink was paid for. Build the complete recovery. Tap a phrase to add it, and tap it again in the apology to remove it.</p>\n    <div class=\"built\" id=\"apBuilt\"></div><div class=\"chips\" id=\"apPool\"></div><div class=\"fbwrap\"></div>\n    <div class=\"row2\"><button type=\"button\" class=\"btn\" id=\"apCheck\">Check my apology</button><button type=\"button\" class=\"btn ghost\" id=\"apReset\">Start over</button></div>`;\n  const draw=()=>{\n    document.getElementById(\"apBuilt\").innerHTML=built.map(i=>`<button type=\"button\" class=\"chip\" data-i=\"${i}\">${esc(PIECES[i].t)}</button>`).join(\"\");\n    document.getElementById(\"apPool\").innerHTML=pool.map(i=>`<button type=\"button\" class=\"chip\" data-i=\"${i}\" ${built.includes(i)?\"disabled\":\"\"}>${esc(PIECES[i].t)}</button>`).join(\"\");\n    document.getElementById(\"apN\").textContent=built.length;\n    el.querySelectorAll(\"#apBuilt .chip\").forEach(c=>c.onclick=()=>{built=built.filter(x=>x!==+c.dataset.i);draw()});\n    el.querySelectorAll(\"#apPool .chip\").forEach(c=>c.onclick=()=>{built.push(+c.dataset.i);draw()});\n  };\n  document.getElementById(\"apReset\").onclick=apologyGame;\n  document.getElementById(\"apCheck\").onclick=()=>{\n    const bad=built.filter(i=>PIECES[i].d), need=PIECES.filter(p=>p.k).map((p,i)=>i).filter(i=>!built.includes(i));\n    const ords=built.filter(i=>PIECES[i].k).map(i=>PIECES[i].ord), inOrder=ords.every((v,k)=>!k||v>ords[k-1]);\n    let msg=[];\n    if(need.length)msg.push(`Missing: ${need.map(i=>\"“\"+PIECES[i].t+\"”\").join(\", \")}.`);\n    bad.forEach(i=>msg.push(`Remove “${PIECES[i].t}” — ${PIECES[i].d}`));\n    if(!need.length&&!bad.length&&!inOrder)msg.push(\"Right pieces, wrong order. Lead with the apology, then the facts, then own the mistake.\");\n    const ok=!msg.length; if(ok)clearGame(\"apology\");\n    el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${ok?\"Full recovery. \":\"Not complete yet. \"}</b>${ok?\"Apology, facts, ownership. Badge earned: Full Recovery.\":msg.map(esc).join(\" \")}</div>`;\n  };\n  draw();\n}\n\n/* Counter rush */\nconst RUSH1=[\n  {s:\"A customer sets a cooler drink on the counter. You don't remember ringing it up.\",o:[\"Check the POS transaction first\",\"Tell them the price\",\"Ask for their receipt\"],why:\"Verify first — before a word about payment.\"},\n  {s:\"The POS is slow to load and the customer is waiting on you.\",o:[\"“Let me make sure we included that drink with your order.”\",\"Say nothing until it loads\",\"“Did you pay for this?”\"],why:\"A neutral line explains the pause without questioning them.\"},\n  {s:\"The transaction shows the drink was paid for.\",o:[\"Apologize, state the facts, own the mistake\",\"“You're good.”\",\"Explain why you were suspicious\"],why:\"A full recovery names what happened and owns it.\"},\n  {s:\"The drink really isn't on the order.\",o:[\"“Looks like it didn't get added — I can ring it up now.”\",\"“You didn't pay for this.”\",\"“That's $3.90.”\"],why:\"Treat it as the store's miss. Never accuse.\"},\n  {s:\"Four customers in line are watching.\",o:[\"Lower your voice and verify quietly\",\"Handle it loudly so the line knows the rule\",\"Tell the customer to wait until the line clears\"],why:\"Avoid anything that looks like an accusation in front of others.\"},\n  {s:\"An upset customer is mid-sentence, voice raised.\",o:[\"Let them finish without interrupting\",\"“Calm down.”\",\"Explain store procedure\"],why:\"Remedy step 1 is Listen.\"},\n  {s:\"A crew member caused the complaint and is standing next to you.\",o:[\"Retrain them privately after the customer leaves\",\"Correct them in front of the customer\",\"Let it go — it's handled\"],why:\"Managers retrain after a complaint — privately.\"},\n  {s:\"The customer refuses to pay for an item confirmed not on the order.\",o:[\"Stay calm, don't argue publicly, escalate to the store manager per company policy\",\"Take the item back out of their hands\",\"Keep arguing until they pay\"],why:\"Escalate. Don't turn the counter into a standoff.\"}\n];\nlet rushTimer=null;\nfunction rushIntro(){\n  const el=document.getElementById(\"rushGame\"); const best=S.games.rushBest||0;\n  el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Counter rush</h3></div><div class=\"hud\"><span>Best <b>${best}</b></span></div></div>\n    <p>${SEC.rush.length} counter situations, 10 seconds each. Pick the move that meets the standard. Faster right answers score more. Get ${SEC.rush.length-1} or more right to clear it.</p>\n    <div class=\"row2\"><button type=\"button\" class=\"btn\" data-go>Start the rush</button></div>`;\n  el.querySelector(\"[data-go]\").onclick=()=>rushRound(el,shuffle(SEC.rush),0,0,0);\n}\nfunction rushRound(el,deck,i,pts,right){\n  clearInterval(rushTimer);\n  if(i>=deck.length){\n    if(right>=deck.length-1)clearGame(\"rush\");\n    if(pts>(S.games.rushBest||0)){S.games.rushBest=pts;save();}\n    el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Counter rush</h3></div><div class=\"hud\"><span>Best <b>${S.games.rushBest}</b></span></div></div>\n      <div class=\"score\">${pts} pts</div><p>${right} of ${deck.length} to standard. ${right>=deck.length-1?\"Badge earned: Counter Ready.\":`Get ${deck.length-1} or more right to clear it.`}</p>\n      <div class=\"row2\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n    el.querySelector(\"[data-r]\").onclick=()=>rushRound(el,shuffle(SEC.rush),0,0,0); return;\n  }\n  const r=deck[i], opts=shuffle(r.o.map((t,k)=>({t,ok:k===0}))), LIMIT=10000, t0=Date.now();\n  el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Counter rush</h3></div><div class=\"hud\"><span>Round <b>${i+1}/${deck.length}</b></span><span>Points <b>${pts}</b></span><span><b id=\"rsT\">10.0</b>s</span></div></div>\n    <div class=\"timer\" id=\"rsBar\"><i></i></div>\n    <p class=\"setup\" style=\"font-size:1.08rem;font-weight:600\">${esc(r.s)}</p>\n    <div class=\"opts\">${opts.map((o,k)=>`<button type=\"button\" class=\"opt\" data-k=\"${k}\"><span class=\"k\">${\"ABC\"[k]}</span><span>${esc(o.t)}</span></button>`).join(\"\")}</div><div class=\"fbwrap\"></div>`;\n  const bar=el.querySelector(\"#rsBar\"),fill=bar.querySelector(\"i\"),tl=el.querySelector(\"#rsT\");\n  const finish=(k)=>{\n    clearInterval(rushTimer);\n    const left=Math.max(0,LIMIT-(Date.now()-t0)), ok=k!=null&&opts[k].ok, gain=ok?100+Math.round(left/100):0;\n    el.querySelectorAll(\".opt\").forEach((x,j)=>{x.disabled=true;if(opts[j].ok)x.classList.add(\"right\")});\n    if(k!=null&&!ok)el.querySelectorAll(\".opt\")[k].classList.add(\"wrong\");\n    el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${k==null?\"Time's up. \":ok?`+${gain}. `:\"Missed. \"}</b>${esc(r.why)}</div>\n      <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn\" data-n>${i+1<deck.length?\"Next customer\":\"See score\"}</button></div>`;\n    el.querySelector(\"[data-n]\").onclick=()=>rushRound(el,deck,i+1,pts+gain,right+(ok?1:0));\n  };\n  el.querySelectorAll(\".opt\").forEach(b=>b.onclick=()=>finish(+b.dataset.k));\n  rushTimer=setInterval(()=>{\n    if(!document.body.contains(bar)){clearInterval(rushTimer);return}\n    const left=Math.max(0,LIMIT-(Date.now()-t0)); fill.style.transform=`scaleX(${left/LIMIT})`; tl.textContent=(left/1000).toFixed(1);\n    bar.classList.toggle(\"low\",left<3000); if(!left)finish(null);\n  },100);\n}\n\n/* ================= SECTION 2 · WRONG ORDER ================= */\nconst CHECKPOINTS=[\n  {id:\"ring\",label:\"Ring\",d:\"Order entered at the register\"},\n  {id:\"make\",label:\"Make\",d:\"Built or pulled on the line\"},\n  {id:\"box\",label:\"Box\",d:\"Cut and boxed\"},\n  {id:\"bag\",label:\"Bag\",d:\"Sides, sauces and drinks packed\"},\n  {id:\"hand\",label:\"Hand-off\",d:\"Given to the customer\"}\n];\nconst CASES2=[\n  {cp:\"ring\",title:\"Rung up wrong\",what:\"A customer asks for a large sausage. The cashier keys in pepperoni. The kitchen makes exactly what the ticket says. Everyone after the cashier did their job, and the customer still gets the wrong pizza.\",stop:\"Read the order back. Have the customer confirm the screen before payment.\"},\n  {cp:\"make\",title:\"Made or pulled wrong\",what:\"The ticket says “no onions,” and the line tops it out of habit. Or, during a rush, the wrong ready pizza is pulled from the warmer.\",stop:\"Match the product to the ticket before it leaves the line.\"},\n  {cp:\"box\",title:\"Right pizza, wrong box\",what:\"Both pizzas for the order are correct, but at the cut table the pepperoni goes into the box labeled cheese. Or two orders' boxes get swapped.\",stop:\"Match the box label to what's inside before the lid closes.\"},\n  {cp:\"bag\",title:\"Missing item\",what:\"The pizzas are right, but the breadsticks, sauce, or drink on the receipt never make it into the bag. The customer finds out at home.\",stop:\"Check the bag against the receipt, item by item.\"},\n  {cp:\"hand\",title:\"Handed to the wrong customer\",what:\"Two orders are ready under similar names. Nobody confirms the name, and one customer leaves with the other's order. Now two customers are affected.\",stop:\"Confirm the name and read the items back at hand-off.\"}\n];\nfunction sec2HTML(id){\n  switch(id){\n  case \"welcome\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Section 2 · Order Accuracy</span><h2>The Wrong Order</h2></div>\n    <div class=\"prose\">\n      <p>A wrong order is almost never one mistake. It's one mistake that got past every checkpoint between the register and the customer's hands. By the time the customer finds it, often at home with the family waiting, the store has already missed several chances to catch it.</p>\n      <p>This section covers the most common ways it happens: wrong item rung up, wrong item made or pulled, the right pizza in the wrong box, a missing item, and an order handed to the wrong customer. It also covers the part that turns a mistake into a serious complaint: how the store responds.</p>\n      <p>By the end of this section you will be able to:</p>\n    </div>\n    <ul class=\"checks\">\n      <li>Pinpoint where in the order's path a wrong order started.</li>\n      <li>Run the five checkpoints that stop a wrong order before it leaves the store.</li>\n      <li>Own the mistake right away when a customer reports it, without arguing with the ticket.</li>\n      <li>Use the Remedy Process and your full remedy authority to make it right.</li>\n      <li>Find the checkpoint that failed and retrain the right person, privately.</li>\n    </ul>\n    <div class=\"facts\">\n      <div class=\"fact\"><div class=\"v\">5</div><div class=\"k\">wrong-order case types</div></div>\n      <div class=\"fact\"><div class=\"v\">~20</div><div class=\"k\">minutes online</div></div>\n      <div class=\"fact\"><div class=\"v\">5</div><div class=\"k\">mini games along the way</div></div>\n      <div class=\"fact\"><div class=\"v\">2</div><div class=\"k\">live role-plays with your manager</div></div>\n    </div>\n    <div class=\"qq\" data-qq=\"warmup\"></div>`;\n  case \"reason\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Why this matters</span><h2>They planned a meal around this order.</h2></div>\n    <div class=\"prose\">\n      <p>A customer who gets the wrong order doesn't just get the wrong food. They lose a trip, their time, and often a meal someone was waiting on. The drive back is when they decide whether they trust your store.</p>\n      <p>Almost every wrong order passes at least one point where someone could have checked and didn't. That's what makes it avoidable, and it's why \"we were busy\" doesn't hold up as a reason.</p>\n      <p>The mistake starts the problem. <strong>The response decides how serious it gets.</strong> Customers forgive a wrong topping. They don't forgive being argued with about it, being asked to prove it, or watching a manager blame the crew.</p>\n    </div>\n    <div class=\"callout\"><b>The AGM standard</b>You own the store's mistakes out loud, in front of the customer, and you fix the process behind them in private. The customer never needs to know whose station it came from.</div>\n    <div class=\"qq\" data-qq=\"reason\"></div>`;\n  case \"issue\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Where wrong orders start</span><h2>Five checkpoints, five ways it goes wrong</h2><p class=\"muted\" style=\"max-width:66ch\">Every order moves through the same five checkpoints. A wrong order means at least one of them was skipped. The cases below are typical examples drawn from everyday store experience.</p></div>\n    <ol class=\"journey\">${CHECKPOINTS.map(c=>`<li><b>${c.label}</b><small>${c.d}</small></li>`).join(\"\")}</ol>\n    <div class=\"cases\">${CASES2.map(c=>`\n      <article class=\"case\"><div class=\"case-top\"><span class=\"pill live\">${CHECKPOINTS.find(x=>x.id===c.cp).label}</span><span class=\"eyebrow\">Typical case</span></div>\n        <h3>${c.title}</h3><p>${esc(c.what)}</p>\n        <div class=\"stopper\"><span class=\"eyebrow\">Stopped by</span><p>${esc(c.stop)}</p></div></article>`).join(\"\")}</div>\n    <div class=\"game\" id=\"traceGame\"></div>\n    <div class=\"callout warn\"><b>The response that makes it serious</b>Wrong orders turn into serious complaints when the store: argues with the ticket (\"that's what you ordered\"), asks for proof before checking its own records, blames a crew member in front of the customer, leaves the customer waiting with no real time, or hands the correction over without checking it again.</div>`;\n  case \"policy\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Standards that apply</span><h2>Policy & Guidelines</h2></div>\n    <div class=\"promise\"><span class=\"eyebrow\">The Customer Promise</span><p>Friendly, professional service — because the customer is the most important person in the business.</p></div>\n    <div style=\"display:grid;gap:12px\">\n      <h3>The Remedy Process, applied to a wrong order</h3>\n      <div class=\"tbl\"><table class=\"plain\">\n        <thead><tr><th>Step</th><th>What it looks like for a wrong order</th></tr></thead>\n        <tbody>\n          <tr><td>1 · Listen</td><td>Let them explain what's wrong without interrupting or asking \"are you sure?\"</td></tr>\n          <tr><td>2 · Apologize sincerely</td><td>\"I'm sorry — that's our mistake.\" Own it before you look anything up.</td></tr>\n          <tr><td>3 · Determine a remedy</td><td>Choose the fix that makes it right: remake it, add the missing item, refund it, let them keep the wrong item, or add something extra. It's your call.</td></tr>\n          <tr><td>4 · Take action</td><td>Put the correction first in line and give the customer a real ready time.</td></tr>\n          <tr><td>5 · Follow up</td><td>Check the corrected order with them before they leave. Then retrain whoever missed the checkpoint.</td></tr>\n        </tbody></table></div>\n    </div>\n    <div style=\"display:grid;gap:12px;max-width:760px\">\n      <h3>Front counter standards</h3>\n      <p>Front counter service includes order verification and transaction completion. Verifying the order at each checkpoint is part of the job, not something extra for a rush.</p>\n      <div class=\"motto\"><span>Own it</span><span>Fix it</span><span>Find it</span></div>\n      <p class=\"muted\">Own the mistake with the customer. Fix the order. Find the checkpoint that failed.</p>\n    </div>\n    <div class=\"callout\"><b>You have full authority to make it right</b>There's no cap on the remedy you can offer. A remake, a refund, letting the customer keep the wrong item, or adding something extra are all yours to use without asking permission. The skill is picking the remedy that fits what the customer went through, and never making them negotiate for it.</div>\n    <div class=\"callout\"><b>Manager responsibility after a complaint</b>Managers are expected to retrain team members after a customer complaint so the same failure doesn't happen again.</div>\n    <div class=\"qq\" data-qq=\"policy\"></div>`;\n  case \"procedure\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Procedure & Implementation</span><h2>Part A · Stop it before it leaves</h2><p class=\"muted\" style=\"max-width:66ch\">Run all five checkpoints on every order. On a rush, they matter more, not less.</p></div>\n    <ol class=\"proc\">\n      <li><div><h3>Ring — read it back</h3><p>Repeat the order to the customer, including size, toppings, and special instructions. Have them confirm the screen before payment.</p></div></li>\n      <li><div><h3>Make — match the ticket</h3><p>Check the product against the ticket before it leaves the line. When pulling a ready pizza, read the ticket, not your memory.</p></div></li>\n      <li><div><h3>Box — label matches lid</h3><p>Before the lid closes, confirm the pizza inside matches the box label and the order. Keep each order's boxes together.</p></div></li>\n      <li><div><h3>Bag — receipt against bag</h3><p>Check every line on the receipt against what's in the bag: sides, sauces, and drinks included.</p></div></li>\n      <li><div><h3>Hand-off — confirm name and items</h3><p>Confirm the customer's name and read the items back before handing the order over, especially when two orders look alike.</p></div></li>\n    </ol>\n    <div class=\"game\" id=\"lidGame\"></div>\n    <div class=\"game\" id=\"bagGame\"></div>\n    <div class=\"stage-head\" style=\"margin-top:12px\"><h2>Part B · When a customer reports it</h2></div>\n    <ol class=\"proc\">\n      <li><div><h3>Listen</h3><p>Let them tell you what's wrong. Don't interrupt, and don't ask \"are you sure?\"</p></div></li>\n      <li><div><h3>Own it</h3><p>Apologize before you investigate. The apology is for their experience, and it doesn't depend on whose station it came from.</p>\n        <div class=\"say\"><div class=\"line\">\"I'm sorry — that's our mistake. Let's make it right.\"</div></div></div></li>\n      <li><div><h3>Check the order to fix it, not to judge them</h3><p>Pull up the ticket so you correct it exactly. If the ticket shows what they received, it was still the store's miss at the read-back.</p>\n        <div class=\"say\"><div class=\"line\">\"It looks like it was entered as pepperoni. I'm sorry we didn't catch that when we read it back.\"</div></div></div></li>\n      <li><div><h3>Fix it first</h3><p>Put the correction at the front of the line. Give a real ready time and check back before it's up.</p></div></li>\n      <li><div><h3>Confirm before they leave</h3><p>Show or read the corrected order with them. Don't let the correction become a second wrong order.</p></div></li>\n      <li><div><h3>Find it</h3><p>After the customer leaves, name the checkpoint that failed and retrain that team member privately.</p></div></li>\n    </ol>\n    <div style=\"display:grid;gap:12px\">\n      <h3>Say this, not that</h3>\n      <div class=\"tbl\"><table>\n        <thead><tr><th>Don't say</th><th>Why it fails</th><th>Say instead</th></tr></thead>\n        <tbody>\n          <tr><td>\"That's what's on the ticket.\"</td><td>Argues with the customer using your own error.</td><td>\"It looks like it was entered wrong — that's on us.\"</td></tr>\n          <tr><td>\"Did you check it before you left?\"</td><td>Makes the customer responsible for your checkpoints.</td><td>\"I'm sorry you had to come back. Let's get it right.\"</td></tr>\n          <tr><td>\"The kitchen messed it up.\"</td><td>Blames the team in front of the customer.</td><td>\"We made a mistake, and I'm fixing it now.\"</td></tr>\n          <tr><td>\"It'll be a minute.\"</td><td>No real time, so the wait feels endless.</td><td>Give an honest ready time, then check back.</td></tr>\n        </tbody></table></div>\n    </div>\n    <div style=\"display:grid;gap:12px\">\n      <h3>Fit the remedy to the miss</h3>\n      <p class=\"muted\" style=\"max-width:66ch\">You can offer any remedy. These are starting points: the more the mistake cost the customer, the more the remedy should give back.</p>\n      <div class=\"tbl\"><table class=\"plain\">\n        <thead><tr><th>What happened</th><th>Make it right</th></tr></thead>\n        <tbody>\n          <tr><td>Missing item, caught at the counter</td><td>Add it right away and apologize.</td></tr>\n          <tr><td>Missing item, found at home</td><td>Have it ready the moment they walk in, and add something for the extra trip.</td></tr>\n          <tr><td>Wrong pizza, customer drove back</td><td>Remake it first in line, let them keep the wrong pizza, and consider a refund or an extra item for the trip.</td></tr>\n          <tr><td>Order handed to the wrong customer</td><td>Make it right for both customers, not just the one at the counter.</td></tr>\n          <tr><td>Long wait on top of the mistake</td><td>Add a make-good such as a refund or an extra item. Two failures deserve more than one fix.</td></tr>\n        </tbody></table></div>\n    </div>\n    <div class=\"game\" id=\"sortGame\"></div>\n    <div class=\"qq\" data-qq=\"procedure\"></div>`;\n  }\n}\nconst QQ2={\n  warmup:{q:\"Warm-up · A wrong order reaches the customer. Who owns it?\",o:[\"The crew member who made it\",\"The customer, for not checking the bag\",\"The store — and the manager on shift owns the recovery\",\"Whoever rang it up\"],a:2,\n    why:\"The customer never needs to know whose station it came from. The store owns it, and the manager on shift leads the recovery.\"},\n  reason:{q:\"A customer drives back with the wrong pizza. What makes this a serious complaint?\",o:[\"The wrong topping itself\",\"Arguing with the ticket or asking for proof before fixing it\",\"Taking a few minutes to remake it\",\"Apologizing too much\"],a:1,\n    why:\"The mistake starts the problem. The response decides how serious it gets.\"},\n  policy:{q:\"In “Own it. Fix it. Find it.” what does “Find it” mean?\",o:[\"Find the customer's receipt\",\"Find who to blame in front of the customer\",\"Find the checkpoint that failed and retrain that person privately\",\"Find a way to avoid a remake\"],a:2,\n    why:\"Find it is the follow-up: the root cause and the retraining, done privately.\"},\n  procedure:{q:\"The ticket shows the customer got exactly what was rung up. They say they asked for sausage. You say…\",o:[\"“The ticket says pepperoni, so that's what you ordered.”\",\"“I'm sorry we didn't catch that when we read it back. Let's get you your sausage.”\",\"“The cashier must have misheard you.”\",\"“Next time, check the screen.”\"],a:1,\n    why:\"Read-back is the store's checkpoint. If it missed, the store owns it.\"}\n};\nconst QUIZ2=[\n  {q:\"A pepperoni pizza went out in a box labeled cheese. Which checkpoint should have caught it?\",o:[\"Ring\",\"Make\",\"Box\",\"Hand-off\"],a:2,why:\"At cut and box, the label is matched to what's inside before the lid closes.\"},\n  {q:\"A customer says their order is wrong. What comes first?\",o:[\"Ask for the receipt\",\"Listen, then apologize before you investigate\",\"Check the ticket to see if they're right\",\"Call over the crew member who made it\"],a:1,why:\"Listen, then apologize sincerely. You check the ticket to fix the order, not to judge the customer.\"},\n  {q:\"The order was rung up wrong, and the kitchen made exactly what the ticket said. Who owns it?\",o:[\"The customer\",\"The kitchen\",\"The store — the read-back should have caught it\",\"Nobody; the ticket was followed\"],a:2,why:\"Following a wrong ticket perfectly still produces a wrong order. The read-back is the checkpoint.\"},\n  {q:\"Which line meets the standard?\",o:[\"“That's what's on the ticket.”\",\"“The kitchen messed it up.”\",\"“I'm sorry — that's our mistake. Let's make it right.”\",\"“Did you check it before you left?”\"],a:2,why:\"It owns the mistake and moves straight to the fix.\"},\n  {q:\"The corrected order is ready. What's left?\",o:[\"Nothing — hand it over\",\"Confirm it with the customer, then find the failed checkpoint and retrain privately\",\"Tell the customer who made the mistake\",\"Post a sign asking customers to check orders\"],a:1,why:\"Follow up twice: with the customer before they leave, and with the team after.\"}\n];\nconst SCENES2=[\n  {title:\"Role-play 1 · The pizza at home\",note:\"Prepares you for the live role-play: a customer returns with the wrong order.\",steps:[\n    {setup:\"A customer walks in holding a pizza box: “I ordered a large sausage. This is pepperoni. I drove all the way back.” Two customers are in line.\",\n     o:[{t:\"“Let me see your receipt.”\",ok:false,f:\"Asking for proof first puts the burden on the customer. Pull up the order yourself.\"},\n        {t:\"“I'm sorry — you shouldn't have had to come back. Let me pull up your order so I get it exactly right.”\",ok:true,f:\"Apology first, then the check, framed as getting it right rather than doubting them.\"},\n        {t:\"“Are you sure you didn't order pepperoni?”\",ok:false,f:\"Questioning the customer before checking your own records turns a mistake into an argument.\"}]},\n    {setup:\"The ticket shows the order was rung up as pepperoni.\",\n     o:[{t:\"“The ticket says pepperoni, so that's what you ordered.”\",ok:false,f:\"The ticket is the store's record, and the read-back should have caught it. Never argue with the customer using your own error.\"},\n        {t:\"“It looks like it was entered as pepperoni. I'm sorry we didn't catch that when we read it back. Let's get you your sausage.”\",ok:true,f:\"Owns the checkpoint that failed and moves straight to the fix.\"},\n        {t:\"“The cashier must have misheard you.”\",ok:false,f:\"Blaming a team member in front of the customer. Coaching happens privately.\"}]},\n    {setup:\"The correct pizza is going into the oven.\",\n     o:[{t:\"Give a real ready time, offer a remedy that fits the extra trip, confirm the pizza with them before they leave, then retrain the cashier privately on read-backs.\",ok:true,f:\"Take action, follow up, and find it. That's the full recovery.\"},\n        {t:\"Hand it over when it's ready and move on to the line.\",ok:false,f:\"Skips the confirmation and the root cause. The same miss will happen again.\"},\n        {t:\"Tell the cashier, in front of the customer, to be more careful.\",ok:false,f:\"Public correction creates a second scene and doesn't fix the process.\"}]}\n  ]},\n  {title:\"Role-play 2 · Two orders, one mix-up\",note:\"Prepares you for the live role-play: a hand-off mix-up that affects two customers.\",steps:[\n    {setup:\"Two orders were ready under similar names. A customer at the counter is waiting for an order that's already gone. It was handed to another customer a few minutes ago.\",\n     o:[{t:\"“Someone else took your order. You'll have to wait.”\",ok:false,f:\"Blames another customer and offers no apology. The hand-off was the store's checkpoint.\"},\n        {t:\"Apologize, own it (“that's our mistake”), start their order right away, and give a real ready time.\",ok:true,f:\"Own it, fix it, and set a clear expectation.\"},\n        {t:\"“Can you come back later?”\",ok:false,f:\"Pushes the cost of the store's mistake onto the customer.\"}]},\n    {setup:\"The other customer calls from home: “This isn't my order.”\",\n     o:[{t:\"Listen, apologize, and offer a fix that makes it right, without making them feel at fault.\",ok:true,f:\"Both customers were affected by one missed checkpoint. Both get a full recovery.\"},\n        {t:\"“You should have checked before you left.”\",ok:false,f:\"The customer isn't a checkpoint. Confirming name and items at hand-off is the store's job.\"},\n        {t:\"“It's not our fault. You picked it up.”\",ok:false,f:\"Arguing over fault ends the relationship, whatever the facts are.\"}]},\n    {setup:\"Both customers have been taken care of.\",\n     o:[{t:\"Privately retrain the team on confirming name and items at hand-off, and watch for it on the next rush.\",ok:true,f:\"Find it, then follow up to make sure the fix holds.\"},\n        {t:\"Put up a sign asking customers to check their orders.\",ok:false,f:\"Shifts the checkpoint to the customer.\"},\n        {t:\"Nothing — it was a one-time thing.\",ok:false,f:\"Managers retrain after a complaint. One-time mix-ups repeat when nothing changes.\"}]}\n  ]}\n];\nconst SORT2=[\n  {t:\"I'm sorry — that's our mistake. Let's make it right.\",say:true,why:\"Owns it and moves to the fix.\"},\n  {t:\"That's what's on the ticket.\",say:false,why:\"Argues with the customer using the store's own record.\"},\n  {t:\"Let me pull up your order so I get it exactly right.\",say:true,why:\"Checking to fix it, not to judge them.\"},\n  {t:\"Did you check it before you left?\",say:false,why:\"Makes the customer responsible for your checkpoints.\"},\n  {t:\"The kitchen messed it up, not me.\",say:false,why:\"Blames the team in front of the customer.\"},\n  {t:\"I'll check on it and come right back to you.\",say:true,why:\"Keeps the customer informed while they wait.\"},\n  {t:\"You must have ordered it wrong.\",say:false,why:\"Even if they misspoke, the read-back was the store's checkpoint.\"},\n  {t:\"Before you go, let's make sure everything's right this time.\",say:true,why:\"Follow-up: confirm the correction before they leave.\"},\n  {t:\"It'll be a minute.\",say:false,why:\"No real time. Give an honest estimate instead.\"},\n  {t:\"I'm sorry we didn't catch that when we read it back.\",say:true,why:\"Names the checkpoint that failed and owns it.\"}\n];\nconst RUSH2=[\n  {s:\"A customer says: “This isn't what I ordered.”\",o:[\"Let them explain without interrupting\",\"“That's what's on the ticket.”\",\"“Are you sure?”\"],why:\"Remedy step 1 is Listen.\"},\n  {s:\"The ticket shows it was rung up wrong.\",o:[\"“It was entered wrong — that's on us.”\",\"“You must have said pepperoni.”\",\"“The ticket's right.”\"],why:\"The read-back was the store's checkpoint.\"},\n  {s:\"Two orders are ready under similar names.\",o:[\"Confirm name and items at hand-off\",\"Hand it to whoever reaches the counter first\",\"Call the name once and hand it over\"],why:\"Hand-off checkpoint: name and items, every time.\"},\n  {s:\"The receipt lists a drink. It's not in the bag.\",o:[\"Add it before the bag leaves\",\"Hand the bag over and mention the drink later\",\"Let the customer notice\"],why:\"Bag checkpoint: receipt against bag, item by item.\"},\n  {s:\"The box says pepperoni. You see cheese under the lid.\",o:[\"Stop and fix it before it leaves\",\"Send it — it's close enough\",\"Change the label to match\"],why:\"Box checkpoint: the pizza inside must match the order, not just the label.\"},\n  {s:\"The crew member who made the mistake is standing next to you.\",o:[\"Fix the order now, retrain them privately later\",\"Point them out to the customer\",\"Correct them at the counter\"],why:\"Own it in public, coach in private.\"},\n  {s:\"The corrected pizza needs time in the oven.\",o:[\"Give a real ready time and check back\",\"“It'll be a minute.”\",\"Say nothing until it's ready\"],why:\"Take action includes telling them when.\"},\n  {s:\"The corrected order is ready.\",o:[\"Confirm it with the customer before they leave\",\"Hand it off fast to clear the line\",\"Set it on the counter and walk away\"],why:\"Follow up so the fix doesn't become a second wrong order.\"},\n  {s:\"The customer drove back for a missing side and waited ten minutes.\",o:[\"Hand them the side, apologize, and add something for the trip\",\"Hand them the side and move on\",\"Ask them to call ahead next time\"],why:\"You have full remedy authority. Two costs to the customer deserve more than the bare fix.\"}\n];\n\n/* Trace the miss */\nconst TRACE=[\n  {s:\"The customer asked for extra cheese. The ticket doesn't show it.\",a:\"ring\",why:\"It was never entered. The read-back should have caught it.\"},\n  {s:\"The ticket says “no onions.” The pizza has onions.\",a:\"make\",why:\"The line didn't match the product to the ticket.\"},\n  {s:\"Both pizzas were made correctly, but the pepperoni is in the box labeled cheese.\",a:\"box\",why:\"The label wasn't matched to what's inside before the lid closed.\"},\n  {s:\"The receipt lists dipping sauce and a drink. The bag has neither.\",a:\"bag\",why:\"The bag wasn't checked against the receipt.\"},\n  {s:\"Two customers with similar names left with each other's orders.\",a:\"hand\",why:\"Name and items weren't confirmed at hand-off.\"},\n  {s:\"During the rush, the wrong ready pizza was pulled from the warmer.\",a:\"make\",why:\"Pulling a ready pizza means reading the ticket, not relying on memory.\"},\n  {s:\"The customer ordered three pizzas. The receipt shows two.\",a:\"ring\",why:\"The order was entered short. Confirming the screen stops it.\"},\n  {s:\"The order is right, but the breadsticks went to the next customer's bag.\",a:\"bag\",why:\"Each bag is checked against its own receipt.\"}\n];\nfunction traceGame(){\n  const el=document.getElementById(\"traceGame\"); const deck=shuffle(TRACE); let i=0,score=0;\n  const head=()=>`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Trace the miss</h3></div><div class=\"hud\"><span>Case <b>${Math.min(i+1,deck.length)}/${deck.length}</b></span><span>Score <b>${score}</b></span></div></div>`;\n  function round(){\n    if(i>=deck.length){const need=deck.length-1,ok=score>=need; if(ok)clearGame(\"trace\");\n      el.innerHTML=head()+`<div class=\"score\">${score}/${deck.length}</div><p>${ok?\"Badge earned: Checkpoint Tracer.\":`Get ${need} or more right to clear it.`}</p>\n        <div class=\"row2\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n      el.querySelector(\"[data-r]\").onclick=traceGame;return;}\n    const c=deck[i];\n    el.innerHTML=head()+`<p>Where did this wrong order start? Tap the checkpoint that missed it.</p>\n      <div class=\"card-flip\" style=\"font-size:1.1rem\">${esc(c.s)}</div>\n      <div class=\"cpbtns\">${CHECKPOINTS.map(p=>`<button type=\"button\" class=\"cpbtn\" data-c=\"${p.id}\"><b>${p.label}</b><small>${p.d}</small></button>`).join(\"\")}</div><div class=\"fbwrap\"></div>`;\n    el.querySelectorAll(\".cpbtn\").forEach(b=>b.onclick=()=>{\n      const ok=b.dataset.c===c.a; if(ok)score++;\n      el.querySelectorAll(\".cpbtn\").forEach(x=>{x.disabled=true;if(x.dataset.c===c.a)x.classList.add(\"right\")});\n      if(!ok)b.classList.add(\"wrong\");\n      el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${CHECKPOINTS.find(p=>p.id===c.a).label}. </b>${esc(c.why)}</div>\n        <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn\" data-n>${i+1<deck.length?\"Next case\":\"See score\"}</button></div>`;\n      el.querySelector(\"[data-n]\").onclick=()=>{i++;round()};\n    });\n  }\n  round();\n}\n\n/* Label vs lid */\nconst PIZZA={cheese:\"Cheese\",pep:\"Pepperoni\",saus:\"Sausage\",veg:\"Veggie\"};\nfunction lidGame(){\n  const el=document.getElementById(\"lidGame\"); const kinds=Object.keys(PIZZA);\n  const n=6, bad=new Set(shuffle([...Array(n).keys()]).slice(0,2+Math.floor(Math.random()*2)));\n  const boxes=[...Array(n)].map((_,i)=>{const label=kinds[Math.floor(Math.random()*kinds.length)];let inside=label;\n    if(bad.has(i)){const others=kinds.filter(k=>k!==label);inside=others[Math.floor(Math.random()*others.length)];}\n    return {label,inside,order:\"#\"+(412+i)};});\n  const flagged=new Set();\n  el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Label vs. lid</h3></div><div class=\"hud\"><span>Flagged <b id=\"lvN\">0</b></span></div></div>\n    <p>You're at the cut table. Six boxes are about to close. Tap every box where the pizza doesn't match its label, then release the rest.</p>\n    <div class=\"boxes\">${boxes.map((b,i)=>`<button type=\"button\" class=\"pbox\" data-i=\"${i}\" aria-pressed=\"false\"><span class=\"sticker\">${b.order} · ${PIZZA[b.label].toUpperCase()}</span><span class=\"pz ${b.inside}\" role=\"img\" aria-label=\"${PIZZA[b.inside]} pizza\"></span><span class=\"bx-state\"></span></button>`).join(\"\")}</div>\n    <div class=\"legend\"><span><i class=\"pz-key pep\"></i>Pepperoni</span><span><i class=\"pz-key saus\"></i>Sausage</span><span><i class=\"pz-key veg\"></i>Veggie</span><span><i class=\"pz-key cheese\"></i>Cheese</span></div>\n    <div class=\"fbwrap\"></div>\n    <div class=\"row2\"><button type=\"button\" class=\"btn\" id=\"lvGo\">Release to the counter</button></div>`;\n  el.querySelectorAll(\".pbox\").forEach(b=>b.onclick=()=>{if(b.classList.contains(\"done\"))return;const i=+b.dataset.i;\n    flagged.has(i)?flagged.delete(i):flagged.add(i);b.classList.toggle(\"flag\",flagged.has(i));b.setAttribute(\"aria-pressed\",flagged.has(i));\n    b.querySelector(\".bx-state\").textContent=flagged.has(i)?\"Held\":\"\";document.getElementById(\"lvN\").textContent=flagged.size;});\n  document.getElementById(\"lvGo\").onclick=()=>{\n    let caught=0,missed=0,wrongHold=0;\n    el.querySelectorAll(\".pbox\").forEach(b=>{const i=+b.dataset.i,f=flagged.has(i),x=bad.has(i),st=b.querySelector(\".bx-state\");b.classList.add(\"done\");b.classList.remove(\"flag\");\n      if(x&&f){caught++;b.classList.add(\"hit\");st.textContent=\"Caught\";}\n      else if(x){missed++;b.classList.add(\"miss\");st.textContent=`Went out as ${PIZZA[boxes[i].label]}`;}\n      else if(f){wrongHold++;b.classList.add(\"false\");st.textContent=\"Was correct\";}\n      else st.textContent=\"Released\";});\n    const ok=!missed&&!wrongHold; if(ok)clearGame(\"lid\");\n    el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${caught} of ${bad.size} caught${wrongHold?`, ${wrongHold} held by mistake`:\"\"}. </b>${ok?\"No wrong box left the table. Badge earned: Label Checker.\":missed?`${missed} wrong order${missed>1?\"s\":\"\"} just went to the counter. Every one you miss here, a customer finds at home.`:\"Held boxes that were right slow the line. Look at the toppings and the label together.\"}</div>`;\n    el.querySelector(\".row2\").innerHTML=`<button type=\"button\" class=\"btn ghost\" id=\"lvAgain\">New table</button>`;\n    document.getElementById(\"lvAgain\").onclick=lidGame;\n  };\n}\n\n/* Bag check */\nconst MENU=[\"Large pepperoni\",\"Large cheese\",\"Large sausage\",\"Deep dish pepperoni\",\"Breadsticks\",\"Cheese bread\",\"Wings (8 pc)\",\"Dipping sauce\",\"Extra dipping sauce\",\"2-liter drink\",\"20 oz drink\",\"Cookie dough brownie\"];\nfunction bagGame(r=0,wins=0){\n  const el=document.getElementById(\"bagGame\"); const ROUNDS=3;\n  if(r>=ROUNDS){const ok=wins===ROUNDS; if(ok)clearGame(\"bag\");\n    el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Bag check</h3></div></div>\n      <div class=\"score\">${wins}/${ROUNDS}</div><p>${ok?\"Every bag went out complete. Badge earned: Bag Checker.\":\"Clear all three bags to earn the badge.\"}</p>\n      <div class=\"row2\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n    el.querySelector(\"[data-r]\").onclick=()=>bagGame();return;}\n  const receipt=shuffle(MENU).slice(0,5), missing=new Set(shuffle(receipt).slice(0,1+Math.floor(Math.random()*2)));\n  const inBag=shuffle(receipt.filter(x=>!missing.has(x))); const picked=new Set();\n  el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Bag check</h3></div><div class=\"hud\"><span>Bag <b>${r+1}/${ROUNDS}</b></span><span>Cleared <b>${wins}</b></span></div></div>\n    <p>Tap every receipt line that's <strong>not</strong> in the bag, then hand it off.</p>\n    <div class=\"bagwrap\">\n      <div class=\"tape mini\"><h5>RECEIPT</h5><div class=\"rule\"></div>${receipt.map(x=>`<button type=\"button\" class=\"rline\" data-x=\"${esc(x)}\"><span>1 ${esc(x)}</span><span class=\"mk\"></span></button>`).join(\"\")}<div class=\"rule\"></div></div>\n      <div class=\"bag\"><span class=\"eyebrow\">In the bag</span><ul>${inBag.map(x=>`<li>${esc(x)}</li>`).join(\"\")}</ul></div>\n    </div>\n    <div class=\"fbwrap\"></div><div class=\"row2\"><button type=\"button\" class=\"btn\" id=\"bgGo\">Hand off the bag</button></div>`;\n  el.querySelectorAll(\".rline\").forEach(b=>b.onclick=()=>{if(b.disabled)return;const x=b.dataset.x;picked.has(x)?picked.delete(x):picked.add(x);b.classList.toggle(\"on\",picked.has(x));b.querySelector(\".mk\").textContent=picked.has(x)?\"MISSING\":\"\";});\n  document.getElementById(\"bgGo\").onclick=()=>{\n    const ok=[...missing].every(x=>picked.has(x))&&[...picked].every(x=>missing.has(x));\n    el.querySelectorAll(\".rline\").forEach(b=>{b.disabled=true;const x=b.dataset.x;if(missing.has(x))b.classList.add(picked.has(x)?\"hit\":\"miss\");else if(picked.has(x))b.classList.add(\"false\");});\n    el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${ok?\"Complete. \":\"Not complete. \"}</b>${ok?\"You caught what was missing before it left.\":`Missing: ${[...missing].map(esc).join(\", \")}.`}</div>`;\n    el.querySelector(\".row2\").innerHTML=`<button type=\"button\" class=\"btn\" id=\"bgNext\">${r+1<ROUNDS?\"Next bag\":\"See result\"}</button>`;\n    document.getElementById(\"bgNext\").onclick=()=>bagGame(r+1,wins+(ok?1:0));\n  };\n}\n\n/* ================= SECTION 3 · THE UPSET CUSTOMER ================= */\nconst LEVELS=[\n  {id:\"frus\",label:\"Frustrated\",c:\"#D6AE3C\",signs:\"Sighs, checks the time, short answers.\",move:\"Get ahead of it: acknowledge the wait and give a real update.\"},\n  {id:\"upset\",label:\"Upset\",c:\"#D9852F\",signs:\"Raised voice, repeats the complaint, asks for a manager.\",move:\"Step in, lower your voice, and let them say all of it.\"},\n  {id:\"angry\",label:\"Angry\",c:\"#C65A2A\",signs:\"Loud, sharp words, talks to the line, hits the counter.\",move:\"Hear it all, move it out of the line, then own it and fix it.\"},\n  {id:\"hostile\",label:\"Hostile\",c:\"#A8322A\",signs:\"Personal insults, cursing at staff, refuses to let anyone talk.\",move:\"Set a respectful boundary, move your crew away, and fix it if you can.\"},\n  {id:\"unsafe\",label:\"Unsafe\",c:\"#6E1C2A\",signs:\"Threats, throwing things, blocking, any move toward violence.\",move:\"Stop serving. Keep distance, protect the team, and call 911 when there's a threat.\"}\n];\nconst LOG3=[\n  {who:\"6:20 PM\",t:\"The order was promised for 6:00. It still isn't ready.\",no:\"A delay isn't the breakdown yet. What the store does next decides it.\"},\n  {who:\"Crew\",q:\"It'll be a minute.\",t:\"Said twice, ten minutes apart — \",flag:\"No real update\",note:\"Twenty minutes with no real time and no explanation. The customer's frustration was built by the store, one “minute” at a time.\"},\n  {who:\"Customer\",q:\"Nobody has told me anything!\",no:\"This is the customer reacting to twenty minutes of silence. The feeling is fair.\"},\n  {who:\"AGM\",q:\"You need to calm down.\",flag:\"Dismissing the feeling\",note:\"Telling someone to calm down tells them their complaint doesn't count. It almost always raises the volume.\"},\n  {who:\"Customer\",q:\"Don't tell me to calm down!\",no:\"A predictable reaction to being dismissed.\"},\n  {who:\"AGM\",q:\"I'm not going to be yelled at in my store.\",flag:\"Matching the energy\",note:\"The customer was loud but not abusive. This made the moment about the manager's feelings instead of the late order.\"},\n  {who:\"AGM\",t:\"Keeps the whole conversation at the register with six customers in line.\",flag:\"Public handling\",note:\"Nobody offered to step aside. The line became an audience, and the customer had a reason to play to it.\"},\n  {who:\"Customer\",q:\"Then I want my money back.\",no:\"A reasonable request after a long wait. It was an easy way to end it.\"},\n  {who:\"AGM\",q:\"I can't do refunds.\",flag:\"Refused a remedy\",note:\"The AGM had full authority to refund. Saying no to an easy fix turned a late order into a lost customer.\"},\n  {who:\"6:26 PM\",t:\"The customer leaves without the pizza and tells the line never to come back.\",no:\"This is the result, not the breakdown.\"}\n];\nfunction sec3HTML(id){\n  switch(id){\n  case \"welcome\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Section 3 · Escalation & Conduct</span><h2>The Upset Customer</h2></div>\n    <div class=\"prose\">\n      <p>Customers rarely walk in angry. They get there after something else goes wrong: a long wait, a wrong order, being questioned at the counter. By the time a manager steps in, the customer's anger is the signal. It isn't the problem.</p>\n      <p>This section covers what happens next. The serious, avoidable failures are almost always on the store's side: matching the customer's volume, getting defensive, telling them to calm down, arguing in front of the line, or refusing a fix you had the authority to give.</p>\n      <p>By the end of this section you will be able to:</p>\n    </div>\n    <ul class=\"checks\">\n      <li>Read how upset a customer is and match your move to that level.</li>\n      <li>Lower the temperature with your voice, your posture, and your words.</li>\n      <li>Move the conversation out of the line without making the customer feel dismissed.</li>\n      <li>Resolve it on the spot using the Remedy Process and your full remedy authority.</li>\n      <li>Recognize when a situation stops being a service issue and becomes a safety issue, and what to do then.</li>\n    </ul>\n    <div class=\"facts\">\n      <div class=\"fact\"><div class=\"v\">5</div><div class=\"k\">temperature levels</div></div>\n      <div class=\"fact\"><div class=\"v\">~20</div><div class=\"k\">minutes online</div></div>\n      <div class=\"fact\"><div class=\"v\">5</div><div class=\"k\">mini games along the way</div></div>\n      <div class=\"fact\"><div class=\"v\">2</div><div class=\"k\">live role-plays with your manager</div></div>\n    </div>\n    <div class=\"qq\" data-qq=\"warmup\"></div>`;\n  case \"reason\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Why this matters</span><h2>The whole line is watching you.</h2></div>\n    <div class=\"prose\">\n      <p>An upset customer at the counter is the most public moment in the store. Everyone in line is watching how you handle it, and they're deciding whether they'd trust your store if it happened to them.</p>\n      <p>Most upset customers aren't angry at you. They're angry about what happened. When you respond to what happened, the anger has nowhere to go. When you respond to the tone, getting defensive or correcting them, one complaint becomes two.</p>\n      <p>Your crew is watching too. The way you handle an angry customer is the way they'll handle one when you're not there.</p>\n    </div>\n    <div class=\"callout\"><b>The AGM standard</b>The first manager on the scene owns the situation until it's resolved or handed to a higher manager. You step in so your crew doesn't have to absorb it, and you stay until it's fixed.</div>\n    <div class=\"qq\" data-qq=\"reason\"></div>`;\n  case \"issue\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">A typical case</span><h2>Twenty-six minutes, one lost customer</h2><p class=\"muted\" style=\"max-width:66ch\">A typical case drawn from everyday store experience. A late order didn't lose this customer. The response did.</p></div>\n    <div class=\"game\" style=\"max-width:none\">\n      <div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Spot the breakdown</h3></div><div class=\"hud\"><span>Picked <b id=\"spotN\">0</b></span><span>Breakdowns <b id=\"spotTotal\">5</b></span></div></div>\n      <p>Read the interaction top to bottom. Tap every line where the store made it worse, then check your picks.</p>\n      <div class=\"issue\">\n        <ol class=\"log\" id=\"spotLog\"></ol>\n        <div class=\"tape\" aria-label=\"Incident tally\">\n          <h5>INCIDENT TALLY</h5>\n          <div class=\"rule\"></div>\n          <div class=\"row\"><span>Promised</span><span>6:00 PM</span></div>\n          <div class=\"row\"><span>Customer left</span><span>6:26 PM</span></div>\n          <div class=\"row\"><span>Real updates given</span><span>0</span></div>\n          <div class=\"row\"><span>Customers watching</span><span>6</span></div>\n          <div class=\"row\"><span>Refund offered</span><span>NO</span></div>\n          <div class=\"rule\"></div>\n          <div class=\"row\"><strong>RESULT</strong><strong>LOST</strong></div>\n          <div class=\"rule\"></div>\n          <p style=\"font-size:.78rem\">One late pizza. Five choices made it worse. Any one of them done right could have ended this at the counter.</p>\n        </div>\n      </div>\n      <div class=\"legend\" id=\"spotLegend\" hidden><span><i style=\"background:var(--accent)\"></i>Found</span><span><i style=\"background:var(--warn)\"></i>Missed</span><span><i style=\"border:2px solid var(--bad)\"></i>Not a breakdown</span></div>\n      <div class=\"fbwrap\" id=\"spotFb\"></div>\n      <div class=\"row2\" id=\"spotCtl\"></div>\n    </div>\n    <div class=\"callout warn\"><b>The pattern</b>Every breakdown in this case was a choice made after the delay: no real update, dismissing the feeling, matching the energy, handling it in front of the line, and refusing a remedy that was available. None of them needed extra time or staff.</div>`;\n  case \"policy\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Standards that apply</span><h2>Policy & Guidelines</h2></div>\n    <div class=\"promise\"><span class=\"eyebrow\">The Customer Promise</span><p>Friendly, professional service — because the customer is the most important person in the business.</p></div>\n    <div style=\"display:grid;gap:12px\">\n      <h3>The Remedy Process, applied to an upset customer</h3>\n      <div class=\"tbl\"><table class=\"plain\">\n        <thead><tr><th>Step</th><th>What it looks like when the customer is upset</th></tr></thead>\n        <tbody>\n          <tr><td>1 · Listen</td><td>Let them say all of it. Don't interrupt, correct, or explain until they're done. Then repeat back what you heard.</td></tr>\n          <tr><td>2 · Apologize sincerely</td><td>Apologize for what happened, not \"if you were upset.\" Name it: \"You waited twenty minutes and nobody told you why.\"</td></tr>\n          <tr><td>3 · Determine a remedy</td><td>Pick the fix that fits what they went through. A long wait plus poor treatment deserves more than the order itself.</td></tr>\n          <tr><td>4 · Take action</td><td>Do it now, and tell them what you're doing while you do it.</td></tr>\n          <tr><td>5 · Follow up</td><td>Check they're satisfied before they leave. Then debrief your crew and fix whatever caused the delay.</td></tr>\n        </tbody></table></div>\n    </div>\n    <div style=\"display:grid;gap:12px;max-width:760px\">\n      <h3>The standard for this section</h3>\n      <div class=\"motto\"><span>Lower it</span><span>Hear it</span><span>Fix it</span></div>\n      <p class=\"muted\">Lower your voice and the temperature. Hear the whole complaint. Fix it with the authority you have.</p>\n    </div>\n    <div class=\"callout\"><b>You have full authority to make it right</b>A refund, a free item, letting them keep a wrong order, or anything else that fits is yours to give without asking permission. \"I can't do that\" is almost never true, and it's the fastest way to lose the customer.</div>\n    <div style=\"display:grid;gap:12px\">\n      <h3>The temperature ladder</h3>\n      <p class=\"muted\" style=\"max-width:66ch\">Upset customers move up and down this ladder. Your job is to read where they are and bring them down one rung at a time.</p>\n      <ol class=\"ladder\">${LEVELS.slice().reverse().map(l=>`<li style=\"--lv:${l.c}\"><b>${l.label}</b><span>${l.signs}</span><em>${l.move}</em></li>`).join(\"\")}</ol>\n    </div>\n    <div class=\"callout warn\"><b>Where service ends and safety begins</b>You're never required to keep serving someone who threatens violence, throws things, or makes you or your crew feel unsafe. At that point, stop the service conversation. Keep distance and the counter between you. Don't argue, and don't physically engage. Get your crew away from the customer, and call 911 when there's a threat. Then notify your supervisor, follow your company's safety procedures, and write down what happened.</div>\n    <div class=\"callout\"><b>Manager responsibility after a complaint</b>Managers are expected to retrain team members after a customer complaint so the same failure doesn't happen again.</div>\n    <div class=\"qq\" data-qq=\"policy\"></div>`;\n  case \"procedure\": return `\n    <div class=\"stage-head\"><span class=\"eyebrow\">Procedure & Implementation</span><h2>Bringing it down</h2><p class=\"muted\" style=\"max-width:66ch\">Follow these steps any time a customer is upset, whether it's at the counter, on the phone, or in the lobby.</p></div>\n    <ol class=\"proc\">\n      <li><div><h3>Step in</h3><p>The first manager to notice takes over. Relieve your crew member so they don't have to absorb it.</p>\n        <div class=\"say\"><div class=\"line\">\"I'm the manager. I'll take care of you.\"</div></div></div></li>\n      <li><div><h3>Lower it</h3><p>Speak lower and slower than they are. Keep your hands visible and your posture open. Don't cross your arms or point, and don't lean over the counter.</p></div></li>\n      <li><div><h3>Hear it all</h3><p>Let them finish completely, even if it takes a minute. Then summarize it back so they know you heard it.</p>\n        <div class=\"say\"><div class=\"line\">\"So you waited twenty minutes past your time, and nobody told you why. That's not okay.\"</div></div></div></li>\n      <li><div><h3>Move it</h3><p>Invite them out of the line to give them your full attention. Offer it as respect, never as punishment.</p>\n        <div class=\"say\"><div class=\"line\">\"Let's step over here so I can give you my full attention.\"</div></div></div></li>\n      <li><div><h3>Own it and fix it</h3><p>Apologize for what happened, then tell them what you're doing. Use your full remedy authority, and don't make them ask twice.</p>\n        <div class=\"say\"><div class=\"line\">\"I'm sorry. Here's what I'm doing right now: your order is out in three minutes, and tonight is on us.\"</div></div></div></li>\n      <li><div><h3>Close and follow up</h3><p>Confirm they're satisfied and thank them. After they leave, check on your crew member, debrief privately, and fix what caused it.</p></div></li>\n    </ol>\n    <div class=\"callout warn\" style=\"max-width:760px\"><b>If it crosses into unsafe</b>Threats, throwing things, or any move toward violence ends the service conversation. Keep distance and the counter between you, move your crew away, don't argue or physically engage, and call 911 when there's a threat. Notify your supervisor and document it.</div>\n    <div class=\"game\" id=\"gaugeGame\"></div>\n    <div style=\"display:grid;gap:12px\">\n      <h3>Say this, not that</h3>\n      <div class=\"tbl\"><table>\n        <thead><tr><th>Don't say</th><th>Why it fails</th><th>Say instead</th></tr></thead>\n        <tbody>\n          <tr><td>\"Calm down.\"</td><td>Dismisses the feeling and raises the volume.</td><td>\"I can see you're upset, and you have every right to be.\"</td></tr>\n          <tr><td>\"That's not my fault.\"</td><td>Makes it about you instead of the problem.</td><td>\"I'm sorry this happened. Let's fix it.\"</td></tr>\n          <tr><td>\"There's nothing I can do.\"</td><td>Almost never true, and it ends the conversation.</td><td>\"Here's what I can do for you right now.\"</td></tr>\n          <tr><td>\"You're making a scene.\"</td><td>Shames them in front of the line.</td><td>\"Let's step over here so I can give you my full attention.\"</td></tr>\n          <tr><td>\"Don't talk to my employee like that!\"</td><td>Matches their energy.</td><td>\"I want to help you, and I need us to keep this respectful.\"</td></tr>\n        </tbody></table></div>\n    </div>\n    <div class=\"game\" id=\"coolGame\"></div>\n    <div class=\"game\" id=\"sortGame\"></div>\n    <div class=\"qq\" data-qq=\"procedure\"></div>`;\n  }\n}\nconst QQ3={\n  warmup:{q:\"Warm-up · When a customer is yelling about a late order, who are they usually angry at?\",o:[\"You, personally\",\"The crew member at the register\",\"What happened: the wait and not being told why\",\"Other customers\"],a:2,\n    why:\"Most upset customers are angry about what happened. Respond to that, not to the tone.\"},\n  reason:{q:\"Who owns an upset customer situation?\",o:[\"The crew member who took the order\",\"The first manager on the scene, until it's resolved or handed up\",\"Whoever the customer is yelling at\",\"The store manager, even if they're not there\"],a:1,\n    why:\"The first manager on the scene steps in so the crew doesn't have to absorb it, and stays until it's fixed.\"},\n  policy:{q:\"A customer threatens to wait outside for a crew member. What changes?\",o:[\"Nothing — keep trying to fix the order\",\"Offer a bigger refund\",\"Service stops and safety takes over: distance, protect the crew, call 911\",\"Ask them politely to leave and go back to work\"],a:2,\n    why:\"A threat ends the service conversation. Safety comes first.\"},\n  procedure:{q:\"The customer has been talking for a full minute. You…\",o:[\"Interrupt to explain what went wrong in the kitchen\",\"Let them finish, then summarize back what you heard\",\"Tell them you get the point\",\"Start the remedy while they're still talking\"],a:1,\n    why:\"Hear it all. A summary proves you listened, and that's usually when the temperature drops.\"}\n};\nconst QUIZ3=[\n  {q:\"A customer is yelling at your cashier. What's your first move?\",o:[\"Wait to see if the cashier can handle it\",\"Step in: “I'm the manager. I'll take care of you.”\",\"Tell the customer to stop yelling\",\"Call the store manager\"],a:1,why:\"The first manager on the scene takes over and relieves the crew.\"},\n  {q:\"Which line lowers the temperature?\",o:[\"“Calm down.”\",\"“That's not my fault.”\",\"“I can see you're upset, and you have every right to be.”\",\"“It's policy.”\"],a:2,why:\"It acknowledges the feeling instead of fighting it.\"},\n  {q:\"Why move the conversation out of the line?\",o:[\"To get the customer out of sight\",\"To give them your full attention and take away the audience\",\"To punish them for making a scene\",\"So the line keeps moving\"],a:1,why:\"Offered as respect, it helps the customer and ends the performance for the line.\"},\n  {q:\"After a 25-minute wait, the customer asks for a refund. You…\",o:[\"Say you can't do refunds\",\"Offer a coupon for next time\",\"Give it, or another remedy that fits. You have full authority.\",\"Tell them you'll ask your manager\"],a:2,why:\"Refusing a fix you're allowed to give turns a late order into a lost customer.\"},\n  {q:\"When does service stop and safety take over?\",o:[\"When the customer raises their voice\",\"When the customer curses about the wait\",\"When there's a threat, something is thrown, or anyone could get hurt\",\"When the line gets long\"],a:2,why:\"Loud isn't unsafe. Threats and violence are.\"}\n];\nconst SCENES3=[\n  {title:\"Role-play 1 · The long wait\",note:\"Prepares you for the live role-play: an upset customer at the counter after a long wait.\",steps:[\n    {setup:\"A customer is shouting at your cashier: “Thirty minutes! This is the worst store in town!” The cashier looks rattled. Five people are in line.\",\n     o:[{t:\"Step up beside the cashier: “I'm the manager. I'll take care of you.” Send the cashier to help the line.\",ok:true,f:\"Step in and relieve your crew. The customer now has one person to talk to, and it's the one who can fix it.\"},\n        {t:\"“Sir, you can't talk to my employee like that.”\",ok:false,f:\"The customer was loud about a real problem, not abusive. This matches their energy and starts a second argument.\"},\n        {t:\"Let the cashier handle it. They took the order.\",ok:false,f:\"The first manager on the scene owns it. Your crew shouldn't have to absorb it.\"}]},\n    {setup:\"The customer keeps going for almost a minute: the wait, the kids at home, the last time this happened.\",\n     o:[{t:\"Interrupt to explain the oven went down.\",ok:false,f:\"Explaining before they're done sounds like an excuse. Hear it all first.\"},\n        {t:\"Let them finish, nodding. Then: “So you've waited thirty minutes, and nobody told you why. That's not okay.”\",ok:true,f:\"Hear it all, then summarize back. This is usually when the temperature drops.\"},\n        {t:\"“Ma'am, you need to calm down so I can help you.”\",ok:false,f:\"Telling someone to calm down dismisses the complaint and raises the volume.\"}]},\n    {setup:\"They finish: “So what are you going to do about it?”\",\n     o:[{t:\"“The pizza will be out when it's out.”\",ok:false,f:\"No apology, no time, no remedy.\"},\n        {t:\"“I can give you a coupon for next time.”\",ok:false,f:\"A next-time offer doesn't fix tonight. Use your authority now.\"},\n        {t:\"“I'm sorry. Let's step over here. Your order is out in three minutes, and tonight is on us.”\",ok:true,f:\"Own it, move it out of the line, and fix it with the authority you have.\"}]}\n  ]},\n  {title:\"Role-play 2 · When it crosses the line\",note:\"Prepares you for the live role-play: a customer whose behavior moves from upset to unsafe.\",steps:[\n    {setup:\"An upset customer starts cursing at a crew member by name.\",\n     o:[{t:\"Step in calmly: “I want to help you, and I need us to keep this respectful.” Move the crew member to the back.\",ok:true,f:\"A respectful boundary protects your crew without matching the customer's energy.\"},\n        {t:\"Tell the customer off so the crew knows you've got their back.\",ok:false,f:\"Matching the anger escalates it and puts your crew in more danger.\"},\n        {t:\"Ignore it and keep working on the order.\",ok:false,f:\"Personal abuse toward your crew needs a boundary. Silence tells the crew they're on their own.\"}]},\n    {setup:\"The customer says: “I'll be waiting outside when she gets off.”\",\n     o:[{t:\"“Get out, or I'll make you leave.”\",ok:false,f:\"Threatening back or getting physical can turn a threat into violence.\"},\n        {t:\"Stop the service conversation. Keep the counter between you, keep the crew member inside, and call 911.\",ok:true,f:\"A threat ends service. Distance, protect the team, and get help.\"},\n        {t:\"Laugh it off to lower the tension.\",ok:false,f:\"A threat is never a joke to wave away. Treat it seriously every time.\"}]},\n    {setup:\"The customer has left.\",\n     o:[{t:\"Get back to the line. It's over.\",ok:false,f:\"It's not over for your crew member, and it isn't documented.\"},\n        {t:\"Make sure the crew member gets to their car safely, notify your supervisor, and write down what happened while it's fresh.\",ok:true,f:\"Follow up on safety first, then report and document.\"},\n        {t:\"Tell the crew member not to take it personally.\",ok:false,f:\"Brushing it off leaves them unsafe and unsupported.\"}]}\n  ]}\n];\nconst SORT3=[\n  {t:\"I can see you're upset, and you have every right to be.\",say:true,why:\"Acknowledges the feeling instead of fighting it.\"},\n  {t:\"Calm down.\",say:false,why:\"Dismisses the complaint and raises the volume.\"},\n  {t:\"Tell me what happened. I'm listening.\",say:true,why:\"Opens the door to hearing all of it.\"},\n  {t:\"That's not my fault.\",say:false,why:\"Makes it about you instead of the problem.\"},\n  {t:\"Let's step over here so I can give you my full attention.\",say:true,why:\"Moves it out of the line as respect, not punishment.\"},\n  {t:\"There's nothing I can do.\",say:false,why:\"You have full remedy authority, so it's almost never true.\"},\n  {t:\"Here's what I can do for you right now.\",say:true,why:\"Moves straight to action.\"},\n  {t:\"You're making a scene.\",say:false,why:\"Shames the customer in front of the line.\"},\n  {t:\"I want to help you, and I need us to keep this respectful.\",say:true,why:\"A boundary that protects your crew without matching the anger.\"},\n  {t:\"It's policy.\",say:false,why:\"Hides behind a rule instead of solving the problem.\"}\n];\nconst RUSH3=[\n  {s:\"A customer is yelling at your cashier about a long wait.\",o:[\"Step in: “I'm the manager. I'll take care of you.”\",\"Let the cashier finish\",\"Tell them to stop yelling\"],why:\"The first manager on the scene takes over.\"},\n  {s:\"The customer is mid-rant, and you know the oven went down.\",o:[\"Let them finish first\",\"Explain the oven right away\",\"“I get it, I get it.”\"],why:\"Hear it all before you explain anything.\"},\n  {s:\"The customer asks: “Are you even listening to me?”\",o:[\"Summarize back what they told you\",\"“Yes, I'm listening.”\",\"Keep explaining the delay\"],why:\"A summary proves you heard them.\"},\n  {s:\"Six customers in line are watching the argument.\",o:[\"“Let's step over here so I can give you my full attention.”\",\"“You're making a scene.”\",\"Keep talking at the register\"],why:\"Move it, and offer it as respect.\"},\n  {s:\"After a 30-minute wait, the customer demands a refund.\",o:[\"Give it. You have full authority.\",\"“I can't do refunds.”\",\"“Let me ask my manager.”\"],why:\"Don't refuse or pass up a fix you're allowed to give.\"},\n  {s:\"The customer curses at a crew member by name.\",o:[\"“I want to help you, and I need us to keep this respectful.”\",\"Curse back\",\"Ignore it\"],why:\"A respectful boundary protects your crew.\"},\n  {s:\"The customer threatens to wait outside for a crew member.\",o:[\"Stop service, keep distance, protect the crew, call 911\",\"Tell them to leave or else\",\"Laugh it off\"],why:\"A threat ends service. Safety first.\"},\n  {s:\"The customer leaves satisfied. Your cashier is shaken.\",o:[\"Check on them, debrief privately, fix the cause\",\"Tell them to toughen up\",\"Move on to the next order\"],why:\"Follow up with your crew, not just the customer.\"}\n];\n\n/* Read the temperature */\nconst GAUGE=[\n  {s:\"Sighs loudly, checks the time again, and says, “This is taking forever.”\",a:\"frus\"},\n  {s:\"Raises their voice: “I've been here twenty minutes and nobody's told me anything!”\",a:\"upset\"},\n  {s:\"Asks for a manager and repeats the complaint for the third time.\",a:\"upset\"},\n  {s:\"Slams a hand on the counter and tells the line how terrible this store is.\",a:\"angry\"},\n  {s:\"Calls a crew member stupid and won't let anyone else speak.\",a:\"hostile\"},\n  {s:\"Says, “I'll be waiting for you outside when you get off.”\",a:\"unsafe\"},\n  {s:\"Throws the pizza box across the counter.\",a:\"unsafe\"},\n  {s:\"Gives short, clipped answers and won't make eye contact.\",a:\"frus\"}\n];\nfunction gaugeGame(){\n  const el=document.getElementById(\"gaugeGame\"); const deck=shuffle(GAUGE); let i=0,score=0;\n  const head=()=>`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Read the temperature</h3></div><div class=\"hud\"><span>Customer <b>${Math.min(i+1,deck.length)}/${deck.length}</b></span><span>Score <b>${score}</b></span></div></div>`;\n  function round(){\n    if(i>=deck.length){const need=deck.length-1,ok=score>=need; if(ok)clearGame(\"gauge\");\n      el.innerHTML=head()+`<div class=\"score\">${score}/${deck.length}</div><p>${ok?\"Badge earned: Room Reader.\":`Get ${need} or more right to clear it.`}</p>\n        <div class=\"row2\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n      el.querySelector(\"[data-r]\").onclick=gaugeGame;return;}\n    const c=deck[i];\n    el.innerHTML=head()+`<p>How upset is this customer? Tap the level on the ladder.</p>\n      <div class=\"card-flip\" style=\"font-size:1.1rem\">${esc(c.s)}</div>\n      <div class=\"lvbtns\">${LEVELS.map(l=>`<button type=\"button\" class=\"lvbtn\" data-l=\"${l.id}\" style=\"--lv:${l.c}\">${l.label}</button>`).join(\"\")}</div><div class=\"fbwrap\"></div>`;\n    el.querySelectorAll(\".lvbtn\").forEach(b=>b.onclick=()=>{\n      const ok=b.dataset.l===c.a, L=LEVELS.find(l=>l.id===c.a); if(ok)score++;\n      el.querySelectorAll(\".lvbtn\").forEach(x=>{x.disabled=true;if(x.dataset.l===c.a)x.classList.add(\"right\")});\n      if(!ok)b.classList.add(\"wrong\");\n      el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${L.label}. </b>Your move: ${esc(L.move)}</div>\n        <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn\" data-n>${i+1<deck.length?\"Next customer\":\"See score\"}</button></div>`;\n      el.querySelector(\"[data-n]\").onclick=()=>{i++;round()};\n    });\n  }\n  round();\n}\n\n/* Bring it down */\nconst COOL=[\n  {c:\"“Twenty-five minutes! I ordered at 5:30. Where is my pizza?!”\",o:[\n    {t:\"“Calm down, it's coming.”\",d:15,r:\"“Don't tell me to calm down!”\"},\n    {t:\"“I'm sorry, that's way too long. Let me find out exactly where it is.”\",d:-20,r:\"They stop mid-sentence and watch you check.\"},\n    {t:\"Say nothing and walk to the back to check.\",d:10,r:\"“Hello?! Are you just going to walk away?”\"}]},\n  {c:\"The oven got backed up. “Nobody told me anything. I've just been standing here.”\",o:[\n    {t:\"“We're really busy tonight.”\",d:10,r:\"“That's not my problem.”\"},\n    {t:\"“You're right. Someone should have told you. That's on us.”\",d:-15,r:\"Their shoulders drop a little.\"},\n    {t:\"“Other people have been waiting too.”\",d:15,r:\"“So that makes it okay?”\"}]},\n  {c:\"“I have kids at home waiting to eat.”\",o:[\n    {t:\"“Everyone's got somewhere to be.”\",d:20,r:\"Their voice goes up again, and the line turns to look.\"},\n    {t:\"“Okay.”\",d:5,r:\"They wait for more. Nothing comes.\"},\n    {t:\"“I understand. Let's step over here so I can take care of you.”\",d:-15,r:\"They follow you away from the register.\"}]},\n  {c:\"Their pizza will be ready in four minutes. “This is ridiculous. I should get something for this.”\",o:[\n    {t:\"“There's nothing I can do about the oven.”\",d:15,r:\"“Then what are you even here for?”\"},\n    {t:\"“You're right. Tonight's order is on us, and I'm adding breadsticks for the kids.”\",d:-25,r:\"“...Okay. Thank you. I appreciate that.”\"},\n    {t:\"“I'll see what my manager says.”\",d:5,r:\"“So now I have to wait for that too?”\"}]},\n  {c:\"The pizza is ready.\",o:[\n    {t:\"Hand it over and call the next customer.\",d:5,r:\"They leave without a word.\"},\n    {t:\"Check the order with them, hand it over, and thank them for their patience.\",d:-15,r:\"“Thanks for taking care of it.”\"},\n    {t:\"“Sorry again, we're just short-staffed.”\",d:5,r:\"“Not my problem,” they mutter on the way out.\"}]}\n];\nfunction coolGame(){\n  const el=document.getElementById(\"coolGame\"); let i=0,temp=85; const GOAL=25; const turns=COOL.map(t=>({...t,o:shuffle(t.o)}));\n  const lv=v=>v>=80?LEVELS[3]:v>=60?LEVELS[2]:v>=40?LEVELS[1]:v>=20?LEVELS[0]:{label:\"Calm\",c:\"var(--accent)\"};\n  const meter=()=>{const L=lv(temp);return `<div class=\"thermo\"><div class=\"thermo-bar\"><i style=\"left:${temp}%\"></i><span class=\"goal\" style=\"left:${GOAL}%\"></span></div>\n    <div class=\"thermo-lab\"><span>Calm</span><span><b style=\"color:${L.c}\">${temp}° · ${L.label}</b></span><span>Hostile</span></div></div>`;};\n  const head=()=>`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Bring it down</h3></div><div class=\"hud\"><span>Turn <b>${Math.min(i+1,turns.length)}/${turns.length}</b></span><span>Goal <b>≤${GOAL}°</b></span></div></div>`;\n  function turn(){\n    if(i>=turns.length){const ok=temp<=GOAL; if(ok)clearGame(\"cool\");\n      el.innerHTML=head()+meter()+`<p><b>${ok?\"Brought it down.\":\"Still too hot.\"}</b> ${ok?\"The customer left calm and taken care of. Badge earned: Temperature Control.\":`Finish at ${GOAL}° or lower to clear it. Watch which replies push the meter up.`}</p>\n        <div class=\"row2\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n      el.querySelector(\"[data-r]\").onclick=coolGame;return;}\n    const t=turns[i];\n    el.innerHTML=head()+`<p>Every reply moves the customer's temperature. Get them from 85° to ${GOAL}° or below in five turns.</p>${meter()}\n      <div class=\"card-flip\" style=\"font-size:1.08rem\">${esc(t.c)}</div>\n      <div class=\"opts\">${t.o.map((o,k)=>`<button type=\"button\" class=\"opt\" data-k=\"${k}\"><span class=\"k\">${\"ABC\"[k]}</span><span>${esc(o.t)}</span></button>`).join(\"\")}</div><div class=\"fbwrap\"></div>`;\n    el.querySelectorAll(\".opt\").forEach(b=>b.onclick=()=>{\n      const o=t.o[+b.dataset.k]; temp=Math.max(0,Math.min(100,temp+o.d));\n      el.querySelectorAll(\".opt\").forEach(x=>x.disabled=true); b.classList.add(o.d<0?\"right\":\"wrong\");\n      el.querySelector(\".thermo\").outerHTML=meter();\n      el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${o.d<0?\"right\":\"wrong\"}\"><b>${o.d<0?`${o.d}°. `:`+${o.d}°. `}</b>${esc(o.r)}</div>\n        <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn\" data-n>${i+1<turns.length?\"Next\":\"See result\"}</button></div>`;\n      el.querySelector(\"[data-n]\").onclick=()=>{i++;turn()};\n    });\n  }\n  turn();\n}\n\n/* ================= SHARED ENGINES (sections 4–6) ================= */\nfunction classifyGame(cfg){\n  const el=document.getElementById(cfg.el); const deck=shuffle(cfg.items); let i=0,score=0;\n  const head=()=>`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>${cfg.title}</h3></div><div class=\"hud\"><span>Card <b>${Math.min(i+1,deck.length)}/${deck.length}</b></span><span>Score <b>${score}</b></span></div></div>`;\n  function round(){\n    if(i>=deck.length){const need=deck.length-1,ok=score>=need; if(ok)clearGame(cfg.key);\n      el.innerHTML=head()+`<div class=\"score\">${score}/${deck.length}</div><p>${ok?`Badge earned: ${cfg.badge}.`:`Get ${need} or more right to clear it.`}</p>\n        <div class=\"row2\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n      el.querySelector(\"[data-r]\").onclick=()=>classifyGame(cfg);return;}\n    const c=deck[i];\n    el.innerHTML=head()+`<p>${cfg.prompt}</p><div class=\"card-flip\" style=\"font-size:1.08rem\">${esc(c.s)}</div>\n      <div class=\"cpbtns\" style=\"grid-template-columns:repeat(${cfg.cats.length},minmax(0,1fr))\">${cfg.cats.map(p=>`<button type=\"button\" class=\"cpbtn\" data-c=\"${p.id}\"><b>${p.label}</b>${p.d?`<small>${p.d}</small>`:\"\"}</button>`).join(\"\")}</div><div class=\"fbwrap\"></div>`;\n    el.querySelectorAll(\".cpbtn\").forEach(b=>b.onclick=()=>{\n      const ok=b.dataset.c===c.a; if(ok)score++;\n      el.querySelectorAll(\".cpbtn\").forEach(x=>{x.disabled=true;if(x.dataset.c===c.a)x.classList.add(\"right\")});\n      if(!ok)b.classList.add(\"wrong\");\n      el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${cfg.cats.find(p=>p.id===c.a).label}. </b>${esc(c.why)}</div>\n        <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn\" data-n>${i+1<deck.length?\"Next\":\"See score\"}</button></div>`;\n      el.querySelector(\"[data-n]\").onclick=()=>{i++;round()};\n    });\n  }\n  round();\n}\n\n/* Lobby watch (section 4) */\nlet lobbyTimer=null;\nconst LOBBY_NAMES=[\"Dana\",\"Marcus\",\"Keisha\",\"Luis\",\"Tanya\",\"Brandon\",\"Ms. Rose\",\"Andre\",\"Jasmine\",\"Carl\",\"Nia\",\"Victor\"];\nfunction lobbyGame(){\n  clearInterval(lobbyTimer);\n  const el=document.getElementById(\"lobbyGame\");\n  el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Lobby watch</h3></div><div class=\"hud\"><span>Best <b>${S.games.lobbyBest??\"—\"}</b></span></div></div>\n    <p>Four customers are waiting and the oven is backed up. For 45 seconds, tap a waiting customer to give them a real update, which cools their meter. When an order turns <b>READY</b>, tap it to hand it off right away, because a ready order left in the warmer heats up fast. If a meter hits the top, that customer walks out. Clear it with one walkout or fewer.</p>\n    <div class=\"row2\"><button type=\"button\" class=\"btn\" data-go>Open the lobby</button></div>`;\n  el.querySelector(\"[data-go]\").onclick=run;\n  function run(){\n    const DUR=45000,t0=Date.now(); let names=shuffle(LOBBY_NAMES),ni=0,order=231,handed=0,walk=0,updates=0;\n    const mk=()=>({name:names[ni++%names.length],num:order++,f:10+Math.random()*25,rate:.9+Math.random()*1.4,ready:false,readyAt:Date.now()+6000+Math.random()*14000,cool:0,gone:0});\n    let cs=[mk(),mk(),mk(),mk()];\n    el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Lobby watch</h3></div><div class=\"hud\"><span>Time <b id=\"lbT\">45</b>s</span><span>Handed <b id=\"lbH\">0</b></span><span>Walkouts <b id=\"lbW\">0</b></span></div></div>\n      <div class=\"lobby\" id=\"lbGrid\"></div><div class=\"fbwrap\"></div>`;\n    const grid=el.querySelector(\"#lbGrid\");\n    grid.innerHTML=cs.map((_,k)=>`<button type=\"button\" class=\"lb\" data-k=\"${k}\"><span class=\"lb-top\"><b></b><span class=\"eyebrow\"></span></span><span class=\"lb-meter\"><i></i></span><span class=\"lb-st\"></span></button>`).join(\"\");\n    const btns=[...grid.querySelectorAll(\".lb\")];\n    const draw=()=>{cs.forEach((c,k)=>{const b=btns[k];\n        b.classList.toggle(\"ready\",c.ready&&!c.gone); b.classList.toggle(\"gone\",!!c.gone); b.disabled=!!c.gone;\n        b.querySelector(\"b\").textContent=c.name; b.querySelector(\".eyebrow\").textContent=\"#\"+c.num;\n        const m=b.querySelector(\".lb-meter i\"); m.style.width=Math.min(100,c.f)+\"%\"; m.style.background=c.f>75?\"var(--bad)\":c.f>45?\"var(--warn)\":\"var(--accent)\";\n        b.querySelector(\".lb-st\").textContent=c.gone===\"left\"?\"Walked out\":c.gone===\"done\"?\"Handed off ✓\":c.ready?\"READY — hand it off\":c.cool>Date.now()?\"Updated\":\"Waiting — tap to update\";});};\n    btns.forEach((b,k)=>b.onclick=()=>{const c=cs[k]; if(c.gone)return;\n        if(c.ready){c.gone=\"done\";handed++;document.getElementById(\"lbH\").textContent=handed;setTimeout(()=>{if(cs[k]===c)cs[k]=mk();},900);}\n        else if(c.cool<Date.now()){c.f=Math.max(0,c.f-40);c.cool=Date.now()+2500;updates++;}\n        draw();});\n    draw();\n    let last=Date.now();\n    lobbyTimer=setInterval(()=>{\n      if(!document.body.contains(grid)){clearInterval(lobbyTimer);return}\n      const now=Date.now(),dt=(now-last)/1000; last=now;\n      cs.forEach((c,k)=>{ if(c.gone)return; if(!c.ready&&now>=c.readyAt)c.ready=true;\n        c.f+=dt*(c.ready?c.rate*6:c.rate*3.2);\n        if(c.f>=100){c.gone=\"left\";walk++;document.getElementById(\"lbW\").textContent=walk;setTimeout(()=>{if(cs[k]===c)cs[k]=mk();},900);} });\n      const left=Math.max(0,DUR-(now-t0)); document.getElementById(\"lbT\").textContent=Math.ceil(left/1000);\n      draw();\n      if(!left){clearInterval(lobbyTimer); const ok=walk<=1; if(ok)clearGame(\"lobby\");\n        const sc=handed*10-walk*25; if(S.games.lobbyBest==null||sc>S.games.lobbyBest){S.games.lobbyBest=sc;save();}\n        el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${handed} handed off, ${walk} walkout${walk===1?\"\":\"s\"}, ${updates} updates. </b>${ok?\"The lobby stayed under control. Badge earned: Lobby Keeper.\":\"Update earlier, and hand off ready orders the moment they turn READY.\"}</div>\n          <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n        btns.forEach(b=>b.disabled=true);\n        el.querySelector(\"[data-r]\").onclick=lobbyGame;}\n    },200);\n  }\n}\n\n/* Quality call (section 5) */\nconst QC=[\n  {pz:\"pep\",ticket:\"Pepperoni\",temp:162,a:\"send\",why:\"Even bake, full toppings, hot. It meets the standard.\"},\n  {pz:\"pep burnt\",ticket:\"Pepperoni\",temp:170,a:\"remake\",why:\"A dark, burnt crust doesn't meet the bake standard. Check oven time and temperature.\"},\n  {pz:\"cheese pale\",ticket:\"Cheese\",temp:141,a:\"remake\",why:\"Pale, underbaked dough. This is the pizza that comes back as “raw in the middle.”\"},\n  {pz:\"pepsparse\",ticket:\"Pepperoni\",temp:158,a:\"remake\",why:\"Toppings are short and uneven. The customer paid for full coverage.\"},\n  {pz:\"cheese\",ticket:\"Pepperoni\",temp:160,a:\"remake\",why:\"A good pizza, but it's the wrong one.\"},\n  {pz:\"saus\",ticket:\"Sausage\",temp:128,a:\"remake\",why:\"128°F is below the 135°F hot-holding minimum. It can't go out.\"},\n  {pz:\"veg\",ticket:\"Veggie\",temp:146,a:\"send\",why:\"Right pizza, good bake, above 135°F.\"},\n  {pz:\"saus\",ticket:\"Sausage\",temp:155,a:\"send\",why:\"Meets every standard. Send it.\"}\n];\nfunction qualityGame(){\n  const el=document.getElementById(\"qualityGame\"); const deck=shuffle(QC); let i=0,score=0;\n  const head=()=>`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Quality call</h3></div><div class=\"hud\"><span>Pizza <b>${Math.min(i+1,deck.length)}/${deck.length}</b></span><span>Score <b>${score}</b></span></div></div>`;\n  function round(){\n    if(i>=deck.length){const ok=score>=deck.length-1; if(ok)clearGame(\"qc\");\n      el.innerHTML=head()+`<div class=\"score\">${score}/${deck.length}</div><p>${ok?\"Badge earned: Quality Gate.\":`Get ${deck.length-1} or more right to clear it.`}</p><div class=\"row2\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n      el.querySelector(\"[data-r]\").onclick=qualityGame;return;}\n    const c=deck[i];\n    el.innerHTML=head()+`<p>You're the last check before the counter. Look at the pizza, the ticket, and the holding temperature. Send it or remake it?</p>\n      <div class=\"qc\"><span class=\"pz ${c.pz}\" role=\"img\" aria-label=\"pizza\"></span><div class=\"qc-info\"><span class=\"eyebrow\">Ticket</span><b>${c.ticket}</b><span class=\"eyebrow\">Holding temp</span><b class=\"${c.temp<135?\"cold\":\"\"}\">${c.temp}°F</b></div></div>\n      <div class=\"duo\"><button type=\"button\" class=\"btn\" data-a=\"send\">Send it</button><button type=\"button\" class=\"btn scrap\" data-a=\"remake\">Remake it</button></div><div class=\"fbwrap\"></div>`;\n    el.querySelectorAll(\"[data-a]\").forEach(b=>b.onclick=()=>{\n      const ok=b.dataset.a===c.a; if(ok)score++; el.querySelectorAll(\"[data-a]\").forEach(x=>x.disabled=true);\n      el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${c.a===\"send\"?\"Send it. \":\"Remake it. \"}</b>${esc(c.why)}</div>\n        <div class=\"row2\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn\" data-n>${i+1<deck.length?\"Next pizza\":\"See score\"}</button></div>`;\n      el.querySelector(\"[data-n]\").onclick=()=>{i++;round()};\n    });\n  }\n  round();\n}\n\n/* Count it back (section 6) */\nconst DENOMS=[2000,1000,500,100,25,10,5,1];\nconst money=c=>\"$\"+(c/100).toFixed(2);\nfunction countGame(r=0,wins=0){\n  const el=document.getElementById(\"countGame\"); const ROUNDS=4;\n  if(r>=ROUNDS){const ok=wins===ROUNDS; if(ok)clearGame(\"count\");\n    el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Count it back</h3></div></div><div class=\"score\">${wins}/${ROUNDS}</div>\n      <p>${ok?\"Every customer got exact change, counted back. Badge earned: Exact Change.\":\"Get all four exact to clear it.\"}</p><div class=\"row2\"><button type=\"button\" class=\"btn ghost\" data-r>Play again</button></div>`;\n    el.querySelector(\"[data-r]\").onclick=()=>countGame();return;}\n  const total=500+Math.floor(Math.random()*1800), paid=[1000,2000,2000,5000].find(p=>p>total+50)||5000, due=paid-total; let tray=[];\n  const sum=()=>tray.reduce((a,b)=>a+b,0);\n  el.innerHTML=`<div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Count it back</h3></div><div class=\"hud\"><span>Customer <b>${r+1}/${ROUNDS}</b></span><span>Exact <b>${wins}</b></span></div></div>\n    <p>The bill stays on the drawer ledge until the change is in the customer's hand. Build the exact change, then count it back.</p>\n    <div class=\"till\"><div><span class=\"eyebrow\">Order total</span><b>${money(total)}</b></div><div><span class=\"eyebrow\">Customer handed you</span><b>${money(paid)}</b><small>“Out of ${paid/100}.”</small></div><div><span class=\"eyebrow\">In your hand</span><b id=\"ctSum\">$0.00</b></div></div>\n    <div class=\"tray\" id=\"ctTray\" aria-label=\"Change in your hand\"></div>\n    <div class=\"denoms\">${DENOMS.map(d=>`<button type=\"button\" class=\"dn ${d>=100?\"bill\":\"coin\"}\" data-d=\"${d}\">${d>=100?\"$\"+d/100:d+\"¢\"}</button>`).join(\"\")}</div>\n    <div class=\"fbwrap\"></div><div class=\"row2\"><button type=\"button\" class=\"btn\" id=\"ctGo\">Count it back</button><button type=\"button\" class=\"btn ghost\" id=\"ctClr\">Clear</button></div>`;\n  const draw=()=>{document.getElementById(\"ctTray\").innerHTML=tray.map((d,k)=>`<button type=\"button\" class=\"dn ${d>=100?\"bill\":\"coin\"}\" data-k=\"${k}\">${d>=100?\"$\"+d/100:d+\"¢\"}</button>`).join(\"\");\n    document.getElementById(\"ctSum\").textContent=money(sum());\n    el.querySelectorAll(\"#ctTray .dn\").forEach(b=>b.onclick=()=>{tray.splice(+b.dataset.k,1);draw()});};\n  el.querySelectorAll(\".denoms .dn\").forEach(b=>b.onclick=()=>{tray.push(+b.dataset.d);tray.sort((a,b)=>a-b);draw()});\n  document.getElementById(\"ctClr\").onclick=()=>{tray=[];draw()};\n  document.getElementById(\"ctGo\").onclick=()=>{\n    const ok=sum()===due; let run=total;\n    const steps=tray.map(d=>{run+=d;return money(run)}).join(\" → \");\n    el.querySelector(\".fbwrap\").innerHTML=`<div class=\"fb ${ok?\"right\":\"wrong\"}\"><b>${ok?\"Exact. \":sum()>due?`Over by ${money(sum()-due)}. `:`Short by ${money(due-sum())}. `}</b>${ok?`Counted back: ${money(total)} → ${steps}.`:`Change due was ${money(due)}.`}</div>`;\n    el.querySelector(\".row2\").innerHTML=`<button type=\"button\" class=\"btn\" id=\"ctNext\">${r+1<ROUNDS?\"Next customer\":\"See result\"}</button>`;\n    el.querySelectorAll(\".dn\").forEach(x=>x.disabled=true);\n    document.getElementById(\"ctNext\").onclick=()=>countGame(r+1,wins+(ok?1:0));\n  };\n  draw();\n}\n/* ================= STANDARD SECTION BUILDER (sections 4–6) ================= */\nconst AUTH_CALLOUT=`<div class=\"callout\"><b>You have full authority to make it right</b>A remake, a refund, a free item, or anything else that fits is yours to give without asking permission. Pick the remedy that matches what the customer went through, and never make them negotiate for it.</div>`;\nconst RETRAIN_CALLOUT=`<div class=\"callout\"><b>Manager responsibility after a complaint</b>Managers are expected to retrain team members after a customer complaint so the same failure doesn't happen again.</div>`;\nconst PROMISE=`<div class=\"promise\"><span class=\"eyebrow\">The Customer Promise</span><p>Friendly, professional service — because the customer is the most important person in the business.</p></div>`;\nconst steps=list=>`<ol class=\"proc\">${list.map(x=>`<li><div><h3>${x.h}</h3><p>${x.p}</p>${x.say?`<div class=\"say\"><div class=\"line\">${x.say}</div></div>`:\"\"}</div></li>`).join(\"\")}</ol>`;\nconst sayTable=rows=>`<div style=\"display:grid;gap:12px\"><h3>Say this, not that</h3><div class=\"tbl\"><table><thead><tr><th>Don't say</th><th>Why it fails</th><th>Say instead</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join(\"\")}</tbody></table></div></div>`;\nfunction buildSection(c){\n  return function(id){\n    switch(id){\n    case \"welcome\": return `\n      <div class=\"stage-head\"><span class=\"eyebrow\">Section ${c.num} · ${c.cat}</span><h2>${c.title}</h2></div>\n      <div class=\"prose\">${c.welcome.map(p=>`<p>${p}</p>`).join(\"\")}<p>By the end of this section you will be able to:</p></div>\n      <ul class=\"checks\">${c.objectives.map(o=>`<li>${o}</li>`).join(\"\")}</ul>\n      <div class=\"facts\"><div class=\"fact\"><div class=\"v\">${c.fact[0]}</div><div class=\"k\">${c.fact[1]}</div></div><div class=\"fact\"><div class=\"v\">~20</div><div class=\"k\">minutes online</div></div><div class=\"fact\"><div class=\"v\">5</div><div class=\"k\">mini games along the way</div></div><div class=\"fact\"><div class=\"v\">2</div><div class=\"k\">live role-plays with your manager</div></div></div>\n      <div class=\"qq\" data-qq=\"warmup\"></div>`;\n    case \"reason\": return `\n      <div class=\"stage-head\"><span class=\"eyebrow\">Why this matters</span><h2>${c.reasonTitle}</h2></div>\n      <div class=\"prose\">${c.reason.map(p=>`<p>${p}</p>`).join(\"\")}</div>\n      <div class=\"callout\"><b>The AGM standard</b>${c.standard}</div>\n      <div class=\"qq\" data-qq=\"reason\"></div>`;\n    case \"issue\": return `\n      <div class=\"stage-head\"><span class=\"eyebrow\">A typical case</span><h2>${c.issueTitle}</h2><p class=\"muted\" style=\"max-width:66ch\">${c.issueSub}</p></div>\n      ${c.issueBefore||\"\"}\n      <div class=\"game\" style=\"max-width:none\">\n        <div class=\"game-top\"><div style=\"display:grid;gap:4px\"><span class=\"tag\">Mini game</span><h3>Spot the breakdown</h3></div><div class=\"hud\"><span>Picked <b id=\"spotN\">0</b></span><span>Breakdowns <b id=\"spotTotal\">0</b></span></div></div>\n        <p>Read the interaction top to bottom. Tap every line where the store made it worse, then check your picks.</p>\n        <div class=\"issue\"><ol class=\"log\" id=\"spotLog\"></ol>\n          <div class=\"tape\" aria-label=\"Incident tally\"><h5>${c.tallyTitle||\"INCIDENT TALLY\"}</h5><div class=\"rule\"></div>\n            ${c.tally.map(t=>`<div class=\"row\"><span>${t[0]}</span><span>${t[1]}</span></div>`).join(\"\")}\n            <div class=\"rule\"></div><div class=\"row\"><strong>${c.tallyResult[0]}</strong><strong>${c.tallyResult[1]}</strong></div><div class=\"rule\"></div>\n            <p style=\"font-size:.78rem\">${c.tallyNote}</p></div></div>\n        <div class=\"legend\" id=\"spotLegend\" hidden><span><i style=\"background:var(--accent)\"></i>Found</span><span><i style=\"background:var(--warn)\"></i>Missed</span><span><i style=\"border:2px solid var(--bad)\"></i>Not a breakdown</span></div>\n        <div class=\"fbwrap\" id=\"spotFb\"></div><div class=\"row2\" id=\"spotCtl\"></div>\n      </div>\n      <div class=\"game\" id=\"classGame\"></div>\n      <div class=\"callout warn\"><b>The pattern</b>${c.pattern}</div>`;\n    case \"policy\": return `\n      <div class=\"stage-head\"><span class=\"eyebrow\">Standards that apply</span><h2>Policy & Guidelines</h2></div>\n      ${PROMISE}\n      <div style=\"display:grid;gap:12px\"><h3>The Remedy Process, applied</h3>\n        <div class=\"tbl\"><table class=\"plain\"><thead><tr><th>Step</th><th>${c.remedyHead}</th></tr></thead><tbody>\n        ${[\"Listen\",\"Apologize sincerely\",\"Determine a remedy\",\"Take action\",\"Follow up\"].map((s,k)=>`<tr><td>${k+1} · ${s}</td><td>${c.remedy[k]}</td></tr>`).join(\"\")}</tbody></table></div></div>\n      <div style=\"display:grid;gap:12px;max-width:760px\"><h3>The standard for this section</h3>\n        <div class=\"motto\">${c.motto.map(m=>`<span>${m}</span>`).join(\"\")}</div><p class=\"muted\">${c.mottoNote}</p></div>\n      ${c.policyExtra||\"\"}\n      ${AUTH_CALLOUT}\n      ${RETRAIN_CALLOUT}\n      <div class=\"qq\" data-qq=\"policy\"></div>`;\n    case \"procedure\": return `\n      <div class=\"stage-head\"><span class=\"eyebrow\">Procedure & Implementation</span><h2>${c.procTitle}</h2><p class=\"muted\" style=\"max-width:66ch\">${c.procSub}</p></div>\n      ${steps(c.procA)}\n      ${c.procMid||\"\"}\n      ${c.procB?`<div class=\"stage-head\" style=\"margin-top:12px\"><h2>${c.procBTitle}</h2></div>${steps(c.procB)}`:\"\"}\n      ${c.procAfter||\"\"}\n      ${sayTable(c.say)}\n      <div class=\"game\" id=\"sortGame\"></div>\n      <div class=\"qq\" data-qq=\"procedure\"></div>`;\n    }\n  };\n}\n/* ================= SECTION 4 · ORDER NOT READY ON TIME ================= */\nconst SEC4={\n  num:4,cat:\"Wait & Readiness\",title:\"Order Not Ready on Time\",fact:[\"5\",\"places a delay starts\"],\n  welcome:[\"Carryout customers are buying two things: the food and the time. When the promised time passes, the wait itself is rarely what turns into a serious complaint. The silence is. A customer who knows what's happening will wait. A customer left guessing starts counting.\",\n    \"This section covers the avoidable parts of a late order: a time that was guessed instead of checked, updates that never came, a finished order sitting in the warmer while its customer waits, and a hand-off with no recovery.\"],\n  objectives:[\"Quote a real ready time at the register, not a guess.\",\"Update waiting customers before they have to ask.\",\"Catch a finished order that hasn't been called.\",\"Recover with an apology and a remedy that fits the wait.\",\"Find and fix the cause of the delay.\"],\n  reasonTitle:\"A promised time is a promise.\",\n  reason:[\"When the register says “ten minutes,” the customer plans around it: a car running, kids waiting, a lunch break ending. Every minute past that time comes out of their day, not the store's.\",\n    \"Unexplained waits feel longer than explained ones. Five minutes of silence feels like fifteen, and it's why a real update is worth more than an apology at the end.\",\n    \"The most avoidable version is the worst one: an order that's already done, sitting in the warmer, while the customer who paid for it stands ten feet away.\"],\n  standard:\"You know every waiting customer's promised time. If an order is going to run late, the customer hears it from you before the time passes, not after they ask.\",\n  issueTitle:\"Quoted ten minutes, waited twenty-four\",issueSub:\"A typical case drawn from everyday store experience. The oven was busy, but the delay became a complaint because of what the store did around it.\",\n  log:[\n    {who:\"5:48 PM\",t:\"The cashier quotes “about ten minutes” without checking the oven screen.\",flag:\"Guessed the time\",note:\"Six orders were already ahead. Checking the screen first would have produced an honest quote, and an honest quote is a promise the store can keep.\"},\n    {who:\"Kitchen\",t:\"The oven is backed up with six orders ahead.\",no:\"A busy oven is normal on a rush. It isn't the breakdown.\"},\n    {who:\"6:03 PM\",t:\"The customer asks. A crew member says, \",q:\"It's almost ready.\",flag:\"Vague update\",note:\"“Almost” means nothing. A real update names a time and a reason: “It's in the oven now, about six more minutes.”\"},\n    {who:\"6:07 PM\",t:\"The order comes out of the oven and sits in the warmer. Nobody calls it.\",flag:\"Ready but unannounced\",note:\"The most avoidable minutes of the whole wait. The order was done, and the customer kept waiting anyway.\"},\n    {who:\"6:11 PM\",t:\"The customer asks again, louder.\",no:\"This is the customer reacting to twenty minutes of guessing.\"},\n    {who:\"AGM\",q:\"We're short-staffed tonight.\",flag:\"Excuse, not apology\",note:\"The reason is real, but the customer didn't ask for a staffing report. Apologize for the wait first.\"},\n    {who:\"AGM\",t:\"Hands over the order: \",q:\"Here you go.\",flag:\"No recovery\",note:\"Twenty-four minutes against a ten-minute quote, and no apology or remedy. The AGM had full authority to make it right.\"},\n    {who:\"6:12 PM\",t:\"The customer leaves and posts a one-star review about the wait.\",no:\"This is the result, not the breakdown.\"}\n  ],\n  tally:[[\"Quoted\",\"10 min\"],[\"Actual\",\"24 min\"],[\"Real updates\",\"0\"],[\"Ready, not called\",\"4 min\"],[\"Remedy\",\"NONE\"]],tallyResult:[\"REVIEW\",\"1 STAR\"],\n  tallyNote:\"The oven cost fourteen minutes. The store's choices turned those minutes into a lost customer.\",\n  pattern:\"A busy oven made the order late. The store made it a complaint: it guessed the time, gave vague updates, left a finished order sitting, made excuses, and skipped the recovery.\",\n  remedyHead:\"What it looks like for a late order\",\n  remedy:[\"Let them tell you how long they've waited and what it cost them.\",\"Name the wait: “You were told ten minutes, and it's been twenty. I'm sorry.”\",\"Fit it to the wait. A few minutes may need a real time and a thank-you. A long wait deserves something back.\",\"Get the order out now, and give a time you're sure of.\",\"Thank them as you hand it over and check it's right. Afterward, find what caused the delay.\"],\n  motto:[\"Real time\",\"Real updates\",\"Real recovery\"],mottoNote:\"Quote a time you checked. Update before they ask. Recover in a way that fits the wait.\",\n  policyExtra:`<div class=\"callout\"><b>The update rule</b>If an order is going to run past its quoted time, tell the customer before the quoted time passes. Give a new time and a reason, and check back before that one passes too.</div>`,\n  procTitle:\"Keeping the promise\",procSub:\"Run these on every order, and treat them as non-negotiable on a rush.\",\n  procA:[\n    {h:\"Quote it real\",p:\"Check the oven or order screen before giving a time. When in doubt, round up. Beating your quote feels great, and missing it feels like a broken promise.\"},\n    {h:\"Know the clock\",p:\"Know every waiting customer's quoted time. On a rush, one person on the counter watches the lobby.\"},\n    {h:\"Update before it's late\",p:\"If it's going to run over, go to the customer first and give a new time and a reason.\",say:\"“Your order's running about five minutes behind. It's in the oven now and will be out at 6:12.”\"},\n    {h:\"Call it the moment it's ready\",p:\"No finished order sits in the warmer while its customer waits. Call the name and hand it off right away.\"},\n    {h:\"Recover\",p:\"Apologize for the wait by name, and use your full authority to fit the remedy to how long it was.\",say:\"“Thank you for waiting. You were told ten minutes, and I'm sorry it took twenty. Tonight's order is on us.”\"},\n    {h:\"Fix the cause\",p:\"After the rush, find out where the time went: quoting, prep, oven load, or staffing. Fix it and retrain.\"}\n  ],\n  procMid:`<div class=\"game\" id=\"lobbyGame\"></div>`,\n  say:[[\"“It'll be a minute.”\",\"No real time, so it feels endless.\",\"“It's in the oven now, about six more minutes.”\"],[\"“It's almost ready.”\",\"“Almost” isn't an update.\",\"“It'll be out at 6:12. I'll bring it right to you.”\"],[\"“We're short-staffed tonight.”\",\"An excuse instead of an apology.\",\"“I'm sorry you've waited this long.”\"],[\"“Everyone's waiting.”\",\"Makes their wait sound unimportant.\",\"“You've waited longer than you should have.”\"],[\"“Here you go.”\",\"Hands off the order with no recovery.\",\"“Thank you for your patience. Tonight's on us.”\"]]\n};\nconst QQ4={\n  warmup:{q:\"Warm-up · What usually turns a late order into a serious complaint?\",o:[\"The number of minutes late\",\"Not knowing what's happening or when it'll be ready\",\"The price\",\"The size of the order\"],a:1,why:\"Customers wait more patiently when they know what's happening. Silence is what turns a wait into a complaint.\"},\n  reason:{q:\"Which minutes of a late order are the most avoidable?\",o:[\"The minutes in the oven\",\"The minutes in line to order\",\"The minutes a finished order sits in the warmer uncalled\",\"The minutes spent paying\"],a:2,why:\"A ready order that nobody calls is pure store error. The food is done, and the customer is still waiting.\"},\n  policy:{q:\"The update rule says to tell the customer about a delay…\",o:[\"When they ask\",\"After the order is ready\",\"Before the quoted time passes\",\"Only if the wait is over 30 minutes\"],a:2,why:\"Get there first, with a new time and a reason.\"},\n  procedure:{q:\"Before you quote a ready time, you should…\",o:[\"Say ten minutes, since that's standard\",\"Check the oven or order screen\",\"Ask the customer how long they can wait\",\"Quote low so they don't leave\"],a:1,why:\"A quote you checked is a promise you can keep.\"}\n};\nconst QUIZ4=[\n  {q:\"Where does a real ready time come from?\",o:[\"Habit — “about ten minutes”\",\"The oven or order screen, checked before you quote\",\"Whatever keeps the customer from leaving\",\"The last time you were busy\"],a:1,why:\"Quote it real. Check before you promise.\"},\n  {q:\"An order will run five minutes past its quote. When do you tell the customer?\",o:[\"When they ask\",\"Before the quoted time passes\",\"When it's ready\",\"You don't need to for five minutes\"],a:1,why:\"The update rule: get there before the quote passes.\"},\n  {q:\"Which is a real update?\",o:[\"“It's almost ready.”\",\"“It'll be a minute.”\",\"“It's in the oven now. It'll be out at 6:12.”\",\"“We're working on it.”\"],a:2,why:\"A real update gives a time and a reason.\"},\n  {q:\"An order has been sitting in the warmer while its customer waits. This is…\",o:[\"Normal on a rush\",\"The most avoidable part of the delay\",\"The kitchen's problem\",\"Fine if it's still hot\"],a:1,why:\"The order is done. Call it the moment it's ready.\"},\n  {q:\"The customer waited 25 minutes on a 10-minute quote. The best recovery is…\",o:[\"“Here you go.”\",\"“We're short-staffed tonight.”\",\"An apology that names the wait, plus a remedy that fits it\",\"A coupon for next time\"],a:2,why:\"You have full authority. Fit the remedy to the wait, tonight.\"}\n];\nconst SCENES4=[\n  {title:\"Role-play 1 · The rush-hour promise\",note:\"Prepares you for the live role-play: quoting a real time and updating before it passes.\",steps:[\n    {setup:\"It's 5:45 on a Friday. A customer orders two large pizzas and asks, “How long?” The oven screen shows eight orders ahead.\",\n     o:[{t:\"“About ten minutes.”\",ok:false,f:\"That's a guess. With eight orders ahead, it's a promise you'll break.\"},\n        {t:\"“We're really backed up. It's going to be a while.”\",ok:false,f:\"Honest, but vague. Give them a number they can plan around.\"},\n        {t:\"Check the screen: “With the rush, it'll be about 20 minutes, around 6:05. I'll keep you posted.”\",ok:true,f:\"A checked time, a clock time, and a promise to update.\"}]},\n    {setup:\"It's 6:01. The order will be about five minutes late.\",\n     o:[{t:\"Go to the customer now: “It's running about five minutes behind. It's in the oven and will be out at 6:10.”\",ok:true,f:\"Update before the quoted time passes, with a new time and a reason.\"},\n        {t:\"Wait. Maybe it'll catch up.\",ok:false,f:\"Hoping isn't a plan. The customer will be watching the clock at 6:05.\"},\n        {t:\"Wait until they ask, then explain.\",ok:false,f:\"By the time they ask, they've already started counting.\"}]},\n    {setup:\"6:10. The order is ready.\",\n     o:[{t:\"Call the name and hand it over.\",ok:false,f:\"It's on time against the new quote, but they still waited past the first promise. Recover.\"},\n        {t:\"Hand it over: “Thanks for your patience. I'm sorry it ran late. I added breadsticks for the wait.”\",ok:true,f:\"Real recovery: thank them, name the wait, and give something back.\"},\n        {t:\"“See? Not too bad.”\",ok:false,f:\"Don't grade your own recovery. Thank them and own the delay.\"}]}\n  ]},\n  {title:\"Role-play 2 · The forgotten order\",note:\"Prepares you for the live role-play: a ready order that went uncalled.\",steps:[\n    {setup:\"A customer approaches: “I've been waiting 20 minutes.” You spot their order in the warmer, and it looks like it's been there a while.\",\n     o:[{t:\"Hand it over quickly and hope they don't notice.\",ok:false,f:\"They'll notice. Customers can see the warmer.\"},\n        {t:\"“I'm so sorry. Your order was ready and we didn't call it. That's on us.” Hand it over and check it's hot.\",ok:true,f:\"Own the most avoidable mistake plainly, and check the product before it goes.\"},\n        {t:\"“Oh, it's been ready. Didn't you hear us call it?”\",ok:false,f:\"That blames the customer for the store's missed hand-off.\"}]},\n    {setup:\"The pizza has been sitting long enough that it's lukewarm.\",\n     o:[{t:\"Send it anyway. They've waited long enough.\",ok:false,f:\"Now they've waited and gotten a lukewarm pizza. Two failures.\"},\n        {t:\"Let them decide: remake it fresh right away, or take it now with a refund. Either way, apologize.\",ok:true,f:\"Use your full authority and let the customer choose what fixes their night.\"},\n        {t:\"Put it back in the oven for a minute.\",ok:false,f:\"A quick re-bake won't make a pizza that's been sitting fresh again. Give them the choice of a fresh one.\"}]},\n    {setup:\"The customer leaves happy.\",\n     o:[{t:\"Assign one person on the counter to watch the warmer and call orders the moment they're ready, then retrain the team privately.\",ok:true,f:\"Fix the cause so no order sits uncalled again.\"},\n        {t:\"Tell the crew to be faster.\",ok:false,f:\"Speed wasn't the problem. Nobody was watching the warmer.\"},\n        {t:\"Nothing. The customer left happy.\",ok:false,f:\"Managers retrain after a complaint. The same miss will happen on the next rush.\"}]}\n  ]}\n];\nconst SORT4=[\n  {t:\"It's in the oven now. It'll be out at 6:12.\",say:true,why:\"A real update: a time and a reason.\"},\n  {t:\"It'll be a minute.\",say:false,why:\"No real time.\"},\n  {t:\"With the rush, it'll be about 20 minutes. I'll keep you posted.\",say:true,why:\"An honest quote and a promise to update.\"},\n  {t:\"It's almost ready.\",say:false,why:\"“Almost” isn't an update.\"},\n  {t:\"We're short-staffed tonight.\",say:false,why:\"An excuse instead of an apology.\"},\n  {t:\"You were told ten minutes, and it's been twenty. I'm sorry.\",say:true,why:\"Names the wait and owns it.\"},\n  {t:\"Everyone's waiting.\",say:false,why:\"Makes their wait sound unimportant.\"},\n  {t:\"Your order's running about five minutes behind.\",say:true,why:\"An update before they have to ask.\"},\n  {t:\"Didn't you hear us call it?\",say:false,why:\"Blames the customer for a missed hand-off.\"},\n  {t:\"Thank you for your patience. Tonight's order is on us.\",say:true,why:\"A recovery that fits the wait.\"}\n];\nconst RUSH4=[\n  {s:\"A customer asks how long. The oven screen shows eight orders ahead.\",o:[\"Check the screen and give a real clock time\",\"“About ten minutes.”\",\"“A while.”\"],why:\"Quote it real.\"},\n  {s:\"An order will miss its quoted time by five minutes.\",o:[\"Tell the customer before the time passes\",\"Wait until they ask\",\"Hope it catches up\"],why:\"The update rule.\"},\n  {s:\"You spot a finished order in the warmer. Its customer is in the lobby.\",o:[\"Call it and hand it off now\",\"Finish your current task first\",\"Wait for them to ask\"],why:\"No ready order sits uncalled.\"},\n  {s:\"A customer asks for an update.\",o:[\"“It's in the oven. It'll be out at 6:12.”\",\"“It's almost ready.”\",\"“It'll be a minute.”\"],why:\"A time and a reason.\"},\n  {s:\"The customer waited 25 minutes on a 10-minute quote.\",o:[\"Apologize, name the wait, and give something back\",\"“Here you go.”\",\"“We're short-staffed.”\"],why:\"Real recovery.\"},\n  {s:\"A held pizza is lukewarm by the time you catch it.\",o:[\"Offer a fresh remake or a refund\",\"Send it anyway\",\"Re-bake it\"],why:\"Don't add a second failure.\"},\n  {s:\"The lobby is full on a Friday rush.\",o:[\"Put one person on the counter in charge of watching the lobby and warmer\",\"Everyone works the make line\",\"Close the lobby\"],why:\"Someone has to own the clock.\"},\n  {s:\"The rush is over.\",o:[\"Find where the time went and fix it\",\"Move on. Rushes happen.\",\"Blame the oven\"],why:\"Fix the cause.\"}\n];\nconst CLASS4={el:\"classGame\",key:\"class\",title:\"Where did the time go?\",badge:\"Delay Detective\",prompt:\"Each wait ran long. Tap where the delay started.\",\n  cats:[{id:\"quote\",label:\"Quote\",d:\"Time guessed at the register\"},{id:\"prep\",label:\"Prep\",d:\"Make line fell behind\"},{id:\"oven\",label:\"Oven\",d:\"Oven backed up\"},{id:\"warmer\",label:\"Warmer\",d:\"Ready, not called\"}],\n  items:[\n    {s:\"The cashier said ten minutes without looking at the screen, and eight orders were ahead.\",a:\"quote\",why:\"The promise was wrong the moment it was made.\"},\n    {s:\"Dough wasn't prepped before the rush, so orders sat waiting to be made.\",a:\"prep\",why:\"The make line fell behind before the oven was involved.\"},\n    {s:\"Every order was made on time, but the oven was full for fifteen minutes.\",a:\"oven\",why:\"Oven capacity was the bottleneck.\"},\n    {s:\"The pizza came out at 6:05. The customer got it at 6:14.\",a:\"warmer\",why:\"Nine minutes in the warmer, uncalled.\"},\n    {s:\"A 20-pizza order was quoted the same time as a single pizza.\",a:\"quote\",why:\"The quote ignored the size of the order.\"},\n    {s:\"Toppings ran out mid-rush and someone had to restock.\",a:\"prep\",why:\"A prep miss stalled the line.\"},\n    {s:\"The finished order was bagged, but the name was never called.\",a:\"warmer\",why:\"Ready, then lost at the hand-off.\"},\n    {s:\"Pizzas were waiting in line to go into the oven while the make line stood idle.\",a:\"oven\",why:\"The oven was the choke point.\"}\n  ]};\n/* ================= SECTION 5 · PRODUCT QUALITY COMPLAINT ================= */\nconst SEC5={\n  num:5,cat:\"Product Quality\",title:\"Product Quality Complaint\",fact:[\"2\",\"kinds of complaint: quality and safety\"],\n  welcome:[\"When a customer says the pizza isn't right, they're almost always describing something real: a pale center, a burnt crust, toppings that stop halfway, a pizza that's gone cold. The serious, avoidable failure is rarely the pizza itself. It's the store defending the kitchen instead of looking at the product.\",\n    \"This section covers how to handle a quality complaint so the customer leaves with a pizza that meets the standard. It also covers what changes when the complaint is really about food safety.\"],\n  objectives:[\"Listen to a quality complaint without defending the kitchen.\",\"Check the product, not the customer.\",\"Apply the basic product standards: bake, toppings, right order, and hot holding at 135°F or above.\",\"Tell a quality issue from a food-safety issue and handle each correctly.\",\"Fix the cause on the make line or at the oven.\"],\n  reasonTitle:\"The product is the promise.\",\n  reason:[\"The customer isn't asking you to agree the kitchen is bad. They're asking for the pizza they paid for. The moment you defend the product, you're telling them their experience doesn't count.\",\n    \"A quality complaint is also free information. A pale center points to the oven. Thin toppings point to portioning. A lukewarm pizza points to holding time. Every complaint ignored is the next complaint already on its way.\",\n    \"Some complaints aren't about quality at all. Something in the food, a reaction, or undercooked meat is a food-safety issue, and those follow a different path.\"],\n  standard:\"You look at the product with the customer, never at the customer. Then you replace it and find out why it happened.\",\n  issueTitle:\"Raw in the middle\",issueSub:\"A typical case drawn from everyday store experience. One underbaked pizza became four, because nobody checked the product or the oven.\",\n  log:[\n    {who:\"Customer\",t:\"Returns with a half-eaten pizza: \",q:\"The middle is raw.\",no:\"The customer is reporting a real problem. Eating some of it first is normal. People don't always notice right away.\"},\n    {who:\"Crew\",q:\"That's how it's supposed to be.\",flag:\"Defending the kitchen\",note:\"A pale, doughy center doesn't meet the bake standard. Defending it tells the customer they're wrong about their own food.\"},\n    {who:\"AGM\",q:\"Well, you ate half of it.\",flag:\"Judging the customer\",note:\"How much they ate doesn't change whether it met the standard. It suggests they're trying to get something free.\"},\n    {who:\"AGM\",t:\"Offers a remake without looking at the pizza.\",flag:\"Didn't check the product\",note:\"One look would have shown an underbaked center, and that points straight at the oven.\"},\n    {who:\"Kitchen\",t:\"The remake goes into the same oven. Nobody checks the oven's time or temperature.\",flag:\"No root cause\",note:\"The same oven makes the same pizza. The cause was never found.\"},\n    {who:\"Later\",t:\"The next three pizzas out of that oven also come out underdone.\",no:\"This is the result. Three more customers are affected.\"}\n  ],\n  tally:[[\"Complaint\",\"Raw center\"],[\"Product checked\",\"NO\"],[\"Oven checked\",\"NO\"],[\"Pizzas affected\",\"4\"]],tallyResult:[\"CAUSE FOUND\",\"NO\"],\n  tallyNote:\"One look at the pizza and one check of the oven would have stopped three more bad pizzas.\",\n  pattern:\"The crew defended the product, the AGM judged the customer, nobody looked at the pizza, and nobody checked the oven. Each choice kept the real cause hidden.\",\n  remedyHead:\"What it looks like for a quality complaint\",\n  remedy:[\"Let them describe what's wrong without explaining how it's “supposed” to be.\",\"“I'm sorry. That's not the pizza you should have gotten.”\",\"Replace it, refund it, or both. How much they ate doesn't matter.\",\"Remake it first in line and check the new one before it goes.\",\"Check the new pizza with them, then check the oven, holding, or portioning and fix the cause.\"],\n  motto:[\"Hear it\",\"See it\",\"Replace it\"],mottoNote:\"Hear the complaint. Look at the product with them. Replace it without a debate.\",\n  policyExtra:`<div class=\"callout\"><b>Product standards to check against</b>Right pizza for the ticket. Even bake with no pale or burnt areas. Toppings portioned to standard, edge to edge. Hot-held food at <b>135°F (57°C) or above</b>. If it misses any of these, it doesn't go out.</div>\n    <div class=\"callout warn\"><b>When it's a food-safety issue</b>Something in the food, a customer reporting illness or an allergic reaction, or undercooked meat or chicken is a food-safety complaint, not a quality complaint. Pull the product and don't argue. Ask whether anyone is hurt or feeling sick, and call 911 for a serious reaction. Keep the product if you can, notify your store manager, follow your food-safety procedures, and write down what happened.</div>`,\n  procTitle:\"Hear it, see it, replace it\",procSub:\"Follow these steps any time a customer says the product isn't right.\",\n  procA:[\n    {h:\"Hear it\",p:\"Let them describe the problem. Don't explain the recipe or the bake time.\"},\n    {h:\"See it, with them\",p:\"Ask to look at the product. The point is to learn what went wrong, not to decide whether they're right.\",say:\"“Can I take a look so I can see what happened?”\"},\n    {h:\"Decide: quality or safety?\",p:\"Something in the food, a reaction, illness, or undercooked meat? Switch to the food-safety steps right away.\"},\n    {h:\"Replace it\",p:\"Remake it first in line, refund it, or both, using your full authority. Never mention how much they ate.\",say:\"“I'm sorry. That's not the pizza you should have gotten. A fresh one is going in right now, and this one's on us.”\"},\n    {h:\"Check the remake\",p:\"Look at the new pizza before it leaves: ticket, bake, toppings, and temperature.\"},\n    {h:\"Fix the source\",p:\"Check the oven's time and temperature, holding times, and portioning. Retrain the station privately and check the next few pizzas.\"}\n  ],\n  procMid:`<div class=\"game\" id=\"qualityGame\"></div>`,\n  say:[[\"“That's how it's supposed to be.”\",\"Defends the product against the customer.\",\"“That's not the pizza you should have gotten.”\"],[\"“You ate half of it.”\",\"Judges the customer.\",\"“I'm sorry. Let's get you a fresh one.”\"],[\"“Nobody else complained.”\",\"Makes them the problem.\",\"“Thank you for telling us. I'm checking the oven now.”\"],[\"“The kitchen made it, not me.”\",\"Blames the team.\",\"“We missed it, and I'm fixing it.”\"],[\"“It's probably fine.”\",\"Dismisses a possible safety issue.\",\"“I'm pulling this now. Are you feeling okay?”\"]]\n};\nconst QQ5={\n  warmup:{q:\"Warm-up · A customer says their pizza is undercooked. What are they usually describing?\",o:[\"An excuse to get free food\",\"A real problem with the product\",\"A misunderstanding of how pizza is made\",\"Nothing that matters\"],a:1,why:\"Most quality complaints describe something real. Look at the product.\"},\n  reason:{q:\"Why is a quality complaint useful to the store?\",o:[\"It isn't\",\"It points to a cause: oven, portioning, or holding\",\"It shows who to write up\",\"It helps you hit sales\"],a:1,why:\"Every complaint is information about the line.\"},\n  policy:{q:\"What's the hot-holding minimum for hot food?\",o:[\"100°F\",\"120°F\",\"135°F\",\"165°F\"],a:2,why:\"Hot-held food stays at 135°F (57°C) or above.\"},\n  procedure:{q:\"A customer says there's something in their pizza. You…\",o:[\"Offer a remake\",\"Say it probably came from the box\",\"Pull the product, ask if they're okay, notify your manager, and follow food-safety procedures\",\"Ask them to prove it\"],a:2,why:\"That's a food-safety complaint. It follows the safety path, not the quality path.\"}\n};\nconst QUIZ5=[\n  {q:\"The first thing to do with a quality complaint is…\",o:[\"Explain how the pizza is made\",\"Hear it fully without defending the kitchen\",\"Check how much they ate\",\"Offer a coupon\"],a:1,why:\"Hear it.\"},\n  {q:\"Why look at the product with the customer?\",o:[\"To check whether they're telling the truth\",\"To learn what went wrong so you can fix it\",\"Because policy says so\",\"To stall\"],a:1,why:\"Check the product, not the customer.\"},\n  {q:\"A customer ate half the pizza before complaining. That means…\",o:[\"No refund\",\"A smaller remedy\",\"Nothing. Replace it anyway.\",\"You should ask why they kept eating\"],a:2,why:\"How much they ate doesn't change the standard.\"},\n  {q:\"A pizza is holding at 128°F. It…\",o:[\"Can go out\",\"Needs a minute in the oven\",\"Doesn't meet the 135°F standard and doesn't go out\",\"Is fine for a carryout order\"],a:2,why:\"Below 135°F, it doesn't go out.\"},\n  {q:\"After replacing an underbaked pizza, what's left?\",o:[\"Nothing\",\"Check the oven's time and temperature and the next few pizzas\",\"Tell the crew to be careful\",\"Write up the customer's complaint only\"],a:1,why:\"Fix the source, or the next pizza has the same problem.\"}\n];\nconst SCENES5=[\n  {title:\"Role-play 1 · The pale center\",note:\"Prepares you for the live role-play: a quality complaint at the counter.\",steps:[\n    {setup:\"A customer comes back with a half-eaten pizza: “The middle is doughy. It's not cooked.”\",\n     o:[{t:\"“That's how our pizza comes out.”\",ok:false,f:\"Defending the product tells them they're wrong about their own food.\"},\n        {t:\"“I'm sorry about that. Can I take a look so I can see what happened?”\",ok:true,f:\"Hear it, then see it, framed as learning, not judging.\"},\n        {t:\"“You ate half of it, though.”\",ok:false,f:\"Judging the customer. How much they ate doesn't matter.\"}]},\n    {setup:\"You look. The center is clearly pale and underbaked.\",\n     o:[{t:\"“You're right, that's underbaked. A fresh one is going in right now, and this one's on us.”\",ok:true,f:\"Replace it, no debate, using your full authority.\"},\n        {t:\"“I can take a couple of dollars off.”\",ok:false,f:\"A partial discount on a pizza that failed the standard isn't a fix.\"},\n        {t:\"Put the same pizza back in the oven.\",ok:false,f:\"A re-baked half-eaten pizza isn't a replacement. Make a fresh one.\"}]},\n    {setup:\"The fresh pizza is going in.\",\n     o:[{t:\"Check the new pizza before it goes out, then check the oven's time and temperature and the next few pizzas.\",ok:true,f:\"See the remake, then fix the source.\"},\n        {t:\"Trust the oven. It was probably a one-off.\",ok:false,f:\"The remake goes into the same oven. Check it.\"},\n        {t:\"Tell the make line to leave pizzas in longer.\",ok:false,f:\"Guessing at a fix without checking the cause can create burnt pizzas instead.\"}]}\n  ]},\n  {title:\"Role-play 2 · Something in the food\",note:\"Prepares you for the live role-play: a complaint that turns out to be food safety.\",steps:[\n    {setup:\"A customer says: “There was a piece of plastic in my pizza. My son almost bit into it.”\",\n     o:[{t:\"“That's impossible. We don't use plastic.”\",ok:false,f:\"Arguing a safety complaint is never the move.\"},\n        {t:\"“I'm so sorry. Is your son okay? Is anyone hurt?”\",ok:true,f:\"Safety first: check on the people before the product.\"},\n        {t:\"“I'll get you a new pizza.”\",ok:false,f:\"A remake treats a safety issue like a quality issue.\"}]},\n    {setup:\"Nobody is hurt. The customer has the pizza and the piece of plastic with them.\",\n     o:[{t:\"Throw them away so no one else sees.\",ok:false,f:\"Keep the product and the object if you can. They're needed to find the cause.\"},\n        {t:\"Keep the product and the object, refund the order, notify your store manager, and follow your food-safety procedures.\",ok:true,f:\"Pull it, keep it, report it, and make it right.\"},\n        {t:\"Give them a coupon and move on.\",ok:false,f:\"A safety complaint needs reporting and documenting, not just a remedy.\"}]},\n    {setup:\"The customer has left.\",\n     o:[{t:\"Write down what happened while it's fresh, then check the make line and packaging for where the plastic came from.\",ok:true,f:\"Document it and find the source.\"},\n        {t:\"Nothing more. It's handled.\",ok:false,f:\"It isn't handled until you know where the plastic came from.\"},\n        {t:\"Tell the crew to be more careful.\",ok:false,f:\"Find the actual source first. “Be careful” doesn't fix packaging or equipment.\"}]}\n  ]}\n];\nconst SORT5=[\n  {t:\"That's not the pizza you should have gotten.\",say:true,why:\"Owns it without defending the kitchen.\"},\n  {t:\"That's how it's supposed to be.\",say:false,why:\"Defends the product against the customer.\"},\n  {t:\"Can I take a look so I can see what happened?\",say:true,why:\"Checks the product, not the customer.\"},\n  {t:\"You ate half of it.\",say:false,why:\"Judges the customer.\"},\n  {t:\"A fresh one is going in right now, and this one's on us.\",say:true,why:\"Replaces it with no debate.\"},\n  {t:\"Nobody else complained.\",say:false,why:\"Makes the customer the problem.\"},\n  {t:\"Is anyone hurt or feeling sick?\",say:true,why:\"Safety first on a food-safety complaint.\"},\n  {t:\"It's probably fine.\",say:false,why:\"Dismisses a possible safety issue.\"},\n  {t:\"Thank you for telling us. I'm checking the oven now.\",say:true,why:\"Treats the complaint as useful information.\"},\n  {t:\"The kitchen made it, not me.\",say:false,why:\"Blames the team.\"}\n];\nconst RUSH5=[\n  {s:\"A customer says their pizza is undercooked.\",o:[\"Ask to look at it with them\",\"Explain the bake time\",\"Offer $2 off\"],why:\"See it.\"},\n  {s:\"You see a pale, doughy center.\",o:[\"Replace it: fresh one first in line, on us\",\"Re-bake the same pizza\",\"Ask how much they ate\"],why:\"Replace it.\"},\n  {s:\"The customer ate half before noticing.\",o:[\"It doesn't matter. Replace it.\",\"Smaller remedy\",\"No remedy\"],why:\"How much they ate doesn't change the standard.\"},\n  {s:\"A pizza in the warmer reads 128°F.\",o:[\"It doesn't go out\",\"Send it. It's close.\",\"Put it in the oven for 30 seconds\"],why:\"Hot-held food stays at 135°F or above.\"},\n  {s:\"A customer found a hair in their food.\",o:[\"Pull it, apologize, refund, notify your manager, and document it\",\"Remake and move on\",\"Say it's probably theirs\"],why:\"Something in the food is a food-safety issue.\"},\n  {s:\"A customer says they're having an allergic reaction.\",o:[\"Check on them and call 911 if it's serious\",\"Offer a refund\",\"Ask what they ordered\"],why:\"People first.\"},\n  {s:\"The remake is ready.\",o:[\"Check it before it goes\",\"Hand it off fast\",\"Let them check it at home\"],why:\"Check the remake.\"},\n  {s:\"Two underbaked complaints in one hour.\",o:[\"Check the oven's time and temperature now\",\"Wait for a third\",\"Blame the dough\"],why:\"Fix the source.\"}\n];\nconst CLASS5={el:\"classGame\",key:\"class\",title:\"Quality or safety?\",badge:\"Safety Sorter\",prompt:\"Is this a quality complaint or a food-safety complaint?\",\n  cats:[{id:\"q\",label:\"Quality\",d:\"Replace it, fix the cause\"},{id:\"s\",label:\"Food safety\",d:\"Pull it, check on people, report it\"}],\n  items:[\n    {s:\"The pizza was lukewarm when they opened the box.\",a:\"q\",why:\"Replace it and check holding times.\"},\n    {s:\"There was a piece of plastic in a slice.\",a:\"s\",why:\"A foreign object is a food-safety issue.\"},\n    {s:\"The crust is burnt around the edges.\",a:\"q\",why:\"It misses the bake standard. Replace it and check the oven.\"},\n    {s:\"The chicken wings are pink inside.\",a:\"s\",why:\"Undercooked meat or chicken is a food-safety issue.\"},\n    {s:\"The pepperoni only covers half the pizza.\",a:\"q\",why:\"A portioning miss. Replace it and retrain.\"},\n    {s:\"The customer says their child is breaking out in hives after eating.\",a:\"s\",why:\"A possible allergic reaction. Check on the child first and call 911 if it's serious.\"},\n    {s:\"There was a hair baked into the cheese.\",a:\"s\",why:\"Something in the food is a food-safety issue.\"},\n    {s:\"The sauce is spread too thin.\",a:\"q\",why:\"A quality miss. Replace it and fix portioning.\"}\n  ]};\n/* ================= SECTION 6 · CHARGE OR CHANGE DISPUTES ================= */\nconst SEC6={\n  num:6,cat:\"Payment & Transactions\",title:\"Charge or Change Disputes\",fact:[\"4\",\"kinds of money dispute\"],\n  welcome:[\"Money disputes feel personal on both sides. The customer feels cheated. The cashier feels accused of stealing. And if the manager takes a side before checking the facts, one of them walks away humiliated in front of the line.\",\n    \"This section covers short change, overcharges, double card charges, and deals that didn't get applied. It builds on Section 1's rule: verify first, and never accuse, whether it's the customer or your crew.\"],\n  objectives:[\"Prevent change disputes with a count-back routine.\",\"Verify card charges and prices on the POS before responding.\",\"Handle a dispute without accusing the customer or the cashier.\",\"Use your company's cash-handling procedure when the drawer has to be counted.\",\"Settle it with your full authority, today whenever possible.\"],\n  reasonTitle:\"Nobody is a liar until the facts say so.\",\n  reason:[\"When a customer says “I gave you a twenty,” they believe it. When the cashier says “it was a ten,” they believe it too. Arguing over who's right in front of the line makes one of them the liar before anyone has checked.\",\n    \"Most change disputes are prevented before they start. When the bill stays on the drawer ledge and the change is counted back out loud, there's nothing left to argue about.\",\n    \"The most costly version is when the store turns out to be wrong. The drawer counts over at close, and the customer who was right is gone for good.\"],\n  standard:\"You step in as the neutral party. You protect the customer's dignity and your cashier's dignity equally, check the facts, and settle it.\",\n  issueTitle:\"The drawer that was $10 over\",issueSub:\"A typical case drawn from everyday store experience. The customer was right, and the store found out after they'd left.\",\n  log:[\n    {who:\"Register\",t:\"A customer pays for a $9.63 order.\",no:\"A routine cash sale.\"},\n    {who:\"Cashier\",t:\"Drops the bill straight into the drawer and hands back change without counting it back.\",flag:\"No count-back\",note:\"With the bill already in the drawer, there's no way to show what was handed over. The dispute started here.\"},\n    {who:\"Customer\",q:\"I gave you a twenty.\",no:\"The customer is reporting what they believe happened.\"},\n    {who:\"Cashier\",q:\"No, you gave me a ten.\",flag:\"Cashier vs. customer\",note:\"The cashier argued with the customer in front of the line instead of calling a manager.\"},\n    {who:\"AGM\",q:\"Our drawers are never wrong.\",flag:\"Defending the drawer\",note:\"A defense with no verification. It tells the customer they're lying.\"},\n    {who:\"AGM\",q:\"Come back tomorrow after we count.\",flag:\"No path to settle it\",note:\"The fix was pushed onto the customer, with no count now, no contact information, and no follow-up.\"},\n    {who:\"Close\",t:\"The drawer counts $10.00 over.\",no:\"The customer was right. Now they're gone, and the store has no way to reach them.\"}\n  ],\n  tallyTitle:\"DRAWER REPORT\",\n  tally:[[\"Order total\",\"$9.63\"],[\"Change given\",\"$0.37\"],[\"Customer said\",\"$20\"],[\"Count-back\",\"NO\"],[\"Drawer at close\",\"+$10.00\"]],tallyResult:[\"CUSTOMER\",\"LOST\"],\n  tallyNote:\"A count-back at the register would have prevented this. A neutral manager and an on-the-spot count would have saved the customer.\",\n  pattern:\"The cashier skipped the count-back, argued with the customer, and the AGM defended the drawer without checking it, then sent the customer away with no way to follow up.\",\n  remedyHead:\"What it looks like for a money dispute\",\n  remedy:[\"Hear the customer's version fully, then hear the cashier's version privately.\",\"“I'm sorry for the confusion. Let's get this right.” Apologize without blaming anyone.\",\"Check first. When the facts support the customer, fix it right away. When they can't be confirmed on the spot, decide with your full authority.\",\"Refund the difference, apply the deal, or count the drawer under your cash procedure, right away.\",\"If you're waiting on a count, take their contact information and call them the same day. Then coach the count-back.\"],\n  motto:[\"Count it\",\"Show it\",\"Settle it\"],mottoNote:\"Count change back out loud. Show the record. Settle it without anyone being called a liar.\",\n  policyExtra:`<div class=\"callout\"><b>Cash procedures come first</b>Drawer counts, voids, and refunds follow your company's cash-handling procedures, for example a manager count of the drawer. This course trains how to handle the customer and the cashier during that process. It doesn't replace the procedure.</div>\n    <div class=\"callout\"><b>Same rule as Section 1</b>Verify first. Clarify second. Never accuse. It applies to the customer and to your crew.</div>`,\n  procTitle:\"Part A · Prevent it at the register\",procSub:\"Every cash sale, every time. These habits stop most change disputes before they start.\",\n  procA:[\n    {h:\"Say what you received\",p:\"Name the amount out loud as you take it.\",say:\"“Out of twenty.”\"},\n    {h:\"Keep the bill on the ledge\",p:\"Leave the customer's bill on top of the drawer, not in it, until their change is in their hand.\"},\n    {h:\"Count it back\",p:\"Count the change into their hand, starting from the total and counting up to the amount they gave you.\",say:\"“$9.63… 64, 65, 75, $10, and ten makes twenty.”\"},\n    {h:\"Then close the drawer\",p:\"Put the bill away and hand over the receipt only after the count is done.\"}\n  ],\n  procMid:`<div class=\"game\" id=\"countGame\"></div>`,\n  procBTitle:\"Part B · When a customer disputes it\",\n  procB:[\n    {h:\"Step in as the neutral party\",p:\"Take it from the cashier so it doesn't turn into cashier against customer.\",say:\"“Let's get this right. I'll take care of it.”\"},\n    {h:\"Check what you can\",p:\"Look at the POS transaction and the receipt. For cash, follow your company's procedure to verify, such as a manager drawer count.\"},\n    {h:\"Card charged twice?\",p:\"If the POS shows two charges, refund one. If it shows one, show them the record and explain kindly that a bank can briefly show a temporary hold.\"},\n    {h:\"Settle it\",p:\"When the facts support the customer, fix it right away and apologize. When they can't be confirmed on the spot, use your full authority to decide. If you're waiting on a count, take their contact information and call them the same day.\"},\n    {h:\"Protect your cashier too\",p:\"Never question your cashier in front of the customer. Talk privately afterward and coach the count-back.\"}\n  ],\n  say:[[\"“Our drawers are never wrong.”\",\"Calls the customer a liar before anyone checks.\",\"“Let's get this right. I'll check it now.”\"],[\"“You gave me a ten.” (cashier)\",\"Turns it into cashier against customer.\",\"“Let me get my manager so we can sort it out.”\"],[\"“Come back tomorrow.”\",\"Pushes the fix onto the customer.\",\"“I'm counting it now,” or “I'll call you today.”\"],[\"“That's what the machine charged.”\",\"Hides behind the register.\",\"“Let me pull up the transaction with you.”\"],[\"“The deal doesn't apply.” (without checking)\",\"Guesses instead of checking.\",\"“Let me check the deal. If it should apply, I'll fix it.”\"]]\n};\nconst QQ6={\n  warmup:{q:\"Warm-up · A customer says they gave a $20 and the cashier says $10. Who's lying?\",o:[\"The customer\",\"The cashier\",\"Maybe nobody. Both may believe it. Check the facts.\",\"Whoever sounds less sure\"],a:2,why:\"Nobody is a liar until the facts say so.\"},\n  reason:{q:\"What prevents most change disputes?\",o:[\"A sign at the register\",\"Keeping the bill on the drawer ledge and counting change back\",\"Card-only payments\",\"Faster cashiers\"],a:1,why:\"Count it and show it, and there's nothing left to argue about.\"},\n  policy:{q:\"Drawer counts and refunds follow…\",o:[\"Whatever's fastest\",\"Your company's cash-handling procedures\",\"The customer's request\",\"The cashier's memory\"],a:1,why:\"The course trains the people side. Cash procedures stay in charge of the count.\"},\n  procedure:{q:\"The POS shows one card charge, but the customer's banking app shows two. You…\",o:[\"Refund one anyway\",\"Show them the record and explain kindly that the bank may be showing a temporary hold\",\"Tell them it's their bank's problem\",\"Ask them to come back tomorrow\"],a:1,why:\"Show the record, explain kindly, and offer to help if it doesn't clear.\"}\n};\nconst QUIZ6=[\n  {q:\"Where should the customer's bill be while you count their change?\",o:[\"In the drawer\",\"On top of the drawer until the change is in their hand\",\"In your pocket\",\"On the counter\"],a:1,why:\"It proves what was handed over.\"},\n  {q:\"A cashier and a customer are arguing over change. You…\",o:[\"Back your cashier\",\"Back the customer\",\"Step in as the neutral party and check the facts\",\"Split the difference\"],a:2,why:\"Protect both people's dignity, and verify first.\"},\n  {q:\"Which line meets the standard?\",o:[\"“Our drawers are never wrong.”\",\"“Let's get this right. I'll check it now.”\",\"“Come back tomorrow.”\",\"“You must be mistaken.”\"],a:1,why:\"Neutral, and it moves straight to checking.\"},\n  {q:\"The dispute can't be confirmed until the drawer is counted under your cash procedure. You…\",o:[\"Tell them to come back tomorrow\",\"Decide using your authority, or take their contact information and call them the same day after the count\",\"Refuse\",\"Ask the cashier to cover it\"],a:1,why:\"Never leave the customer with no way to get it settled.\"},\n  {q:\"After the dispute is settled, what's left?\",o:[\"Nothing\",\"Coach the cashier privately on the count-back\",\"Write up the customer\",\"Post a “count your change” sign\"],a:1,why:\"Fix the cause and protect your cashier's dignity.\"}\n];\nconst SCENES6=[\n  {title:\"Role-play 1 · “I gave you a twenty”\",note:\"Prepares you for the live role-play: a short-change dispute at the counter.\",steps:[\n    {setup:\"A customer and your cashier are going back and forth: “I gave you a twenty!” “No, it was a ten.” The line is watching.\",\n     o:[{t:\"“Our cashiers don't make mistakes like that.”\",ok:false,f:\"That defends the drawer without checking and calls the customer a liar.\"},\n        {t:\"Step in: “Let's get this right. I'll take care of it.” Move the cashier to help the line.\",ok:true,f:\"Neutral, calm, and it ends the cashier-vs-customer argument.\"},\n        {t:\"Give them $10 to make it go away.\",ok:false,f:\"Settling without checking skips verification and doesn't protect your cashier either.\"}]},\n    {setup:\"The cashier says the bill went straight into the drawer. There was no count-back.\",\n     o:[{t:\"Follow your cash procedure for a drawer count now, and tell the customer what you're doing and how long it'll take.\",ok:true,f:\"Verify first, and keep the customer informed.\"},\n        {t:\"“Come back tomorrow after we close out.”\",ok:false,f:\"That pushes the fix onto the customer with no follow-up.\"},\n        {t:\"Question the cashier in front of the customer.\",ok:false,f:\"Never question your crew in public. Protect both people's dignity.\"}]},\n    {setup:\"The drawer count shows it's $10 over.\",\n     o:[{t:\"Hand over the $10: “You were right, and I'm sorry for the trouble.” Later, coach the cashier privately on the count-back.\",ok:true,f:\"Settle it, own it, and fix the cause privately.\"},\n        {t:\"Hand them the $10 without saying anything.\",ok:false,f:\"They were questioned in front of the line. They deserve an apology.\"},\n        {t:\"Tell the line the customer was right.\",ok:false,f:\"The apology is for the customer. Don't make a show of it.\"}]}\n  ]},\n  {title:\"Role-play 2 · The double charge\",note:\"Prepares you for the live role-play: a card charge dispute.\",steps:[\n    {setup:\"A customer shows you their banking app: “You charged me twice!”\",\n     o:[{t:\"“That's what the machine did. Not our problem.”\",ok:false,f:\"Hides behind the register without checking.\"},\n        {t:\"“Let me pull up the transaction with you so we can see exactly what happened.”\",ok:true,f:\"Check the record, together.\"},\n        {t:\"Refund one charge right away without checking.\",ok:false,f:\"Check first. It may be a temporary hold, not a second charge.\"}]},\n    {setup:\"The POS shows only one completed charge.\",\n     o:[{t:\"“Our system only shows one, so you're fine.”\",ok:false,f:\"True, but dismissive. They're still worried about their money.\"},\n        {t:\"Show them the one charge and explain kindly that banks sometimes show a temporary hold that drops off. Offer to follow up if it doesn't.\",ok:true,f:\"Show the record, explain kindly, and give them a path if it doesn't clear.\"},\n        {t:\"Tell them to call their bank.\",ok:false,f:\"That sends them away without explaining what they're seeing.\"}]},\n    {setup:\"A second customer says their deal wasn't applied. The POS shows full price.\",\n     o:[{t:\"Check whether the deal should apply. If it should, refund the difference and apologize.\",ok:true,f:\"Verify, then fix it.\"},\n        {t:\"“The deal doesn't apply to that.” (without checking)\",ok:false,f:\"That's a guess. Check first.\"},\n        {t:\"“It's too late now. You already paid.”\",ok:false,f:\"It's never too late to fix an overcharge.\"}]}\n  ]}\n];\nconst SORT6=[\n  {t:\"Out of twenty.\",say:true,why:\"Names the amount received out loud.\"},\n  {t:\"Our drawers are never wrong.\",say:false,why:\"Calls the customer a liar before checking.\"},\n  {t:\"Let's get this right. I'll check it now.\",say:true,why:\"Neutral, and moves straight to verifying.\"},\n  {t:\"Come back tomorrow after we count.\",say:false,why:\"Pushes the fix onto the customer.\"},\n  {t:\"Let me pull up the transaction with you.\",say:true,why:\"Shows the record together.\"},\n  {t:\"That's what the machine charged.\",say:false,why:\"Hides behind the register.\"},\n  {t:\"You were right, and I'm sorry for the trouble.\",say:true,why:\"Owns it once the facts are in.\"},\n  {t:\"You must be mistaken.\",say:false,why:\"Accuses before verifying.\"},\n  {t:\"I'll count it now, and if we can't confirm it today, I'll call you.\",say:true,why:\"Gives them a clear path to getting it settled.\"},\n  {t:\"The deal doesn't apply to that.\",say:false,why:\"A guess unless you've checked.\"}\n];\nconst RUSH6=[\n  {s:\"A customer hands you a $20 for a $9.63 order.\",o:[\"“Out of twenty.” Keep the bill on the ledge and count back.\",\"Drop the bill in the drawer\",\"Hand back change without counting\"],why:\"Count it and show it.\"},\n  {s:\"The cashier and customer are arguing over change.\",o:[\"Step in as the neutral party\",\"Back your cashier\",\"Back the customer\"],why:\"Protect both.\"},\n  {s:\"The change dispute needs a drawer count.\",o:[\"Follow your cash procedure now and keep the customer informed\",\"“Come back tomorrow.”\",\"Count it in front of the line and argue each bill\"],why:\"Verify first, calmly.\"},\n  {s:\"The count shows the drawer is $10 over.\",o:[\"Give it back and apologize\",\"Give it back without a word\",\"Ask them to prove it\"],why:\"Settle it and own it.\"},\n  {s:\"A customer says they were charged twice. The POS shows two charges.\",o:[\"Refund one and apologize\",\"“Call your bank.”\",\"“The machine did it.”\"],why:\"Fix it.\"},\n  {s:\"The POS shows one charge. The customer's app shows two.\",o:[\"Show the record and explain a temporary hold kindly\",\"Refund anyway\",\"“Not our problem.”\"],why:\"Show it and explain.\"},\n  {s:\"A deal wasn't applied.\",o:[\"Check it, and if it should apply, refund the difference\",\"“Too late, you paid.”\",\"“Deals don't stack.” (a guess)\"],why:\"Verify, then fix.\"},\n  {s:\"The dispute is settled.\",o:[\"Coach the cashier privately on the count-back\",\"Correct them in front of the line\",\"Nothing\"],why:\"Fix the cause, privately.\"}\n];\nconst CLASS6={el:\"classGame\",key:\"class\",title:\"Which fix?\",badge:\"Fair Settler\",prompt:\"Pick the right way to settle each dispute.\",\n  cats:[{id:\"refund\",label:\"Refund it\",d:\"Records show we overcharged\"},{id:\"count\",label:\"Count it\",d:\"Cash needs a drawer count\"},{id:\"show\",label:\"Show it\",d:\"Records show it was right\"},{id:\"deal\",label:\"Apply it\",d:\"A deal was missed\"}],\n  items:[\n    {s:\"The POS shows the same card charge twice.\",a:\"refund\",why:\"Two charges for one order. Refund one.\"},\n    {s:\"The customer says they gave a $20. The bill went straight into the drawer.\",a:\"count\",why:\"Cash can't be confirmed without a drawer count under your procedure.\"},\n    {s:\"The customer's app shows two charges. The POS shows one.\",a:\"show\",why:\"Show the record and explain the temporary hold kindly.\"},\n    {s:\"The customer ordered the lunch combo, and the POS rang each item separately.\",a:\"deal\",why:\"Apply the deal and refund the difference.\"},\n    {s:\"A large was rung up as an extra-large.\",a:\"refund\",why:\"Overcharged. Refund the difference.\"},\n    {s:\"The customer thinks the price went up, but the receipt matches the menu board.\",a:\"show\",why:\"Show them the menu price kindly. Nothing was overcharged.\"},\n    {s:\"The cashier and customer disagree about a $5 bill during a rush.\",a:\"count\",why:\"Follow your cash procedure to verify.\"},\n    {s:\"An advertised coupon wasn't scanned.\",a:\"deal\",why:\"Apply it and refund the difference.\"}\n  ]};\n\n/* ---------- sections ---------- */\nconst SECTIONS={\n  \"unpaid-item\":{id:\"unpaid-item\",num:1,next:\"wrong-order\",html:sec1HTML,quiz:QUIZ1,scenes:SCENES1,games:GAMES1,qq:QQ1,sort:SORT1,rush:RUSH1,\n    sign:[[\"online\",\"Completed the online section and knowledge check\"],[\"rp1\",\"Demonstrated role-play 1 live: suspected unpaid beverage or merchandise item\"],[\"rp2\",\"Demonstrated role-play 2 live: customer upset after being questioned\"],[\"lang\",\"Used verify-first language, a complete apology, and correct escalation\"],[\"mgr\",\"Manager observed and confirmed the demonstrations\"]],\n    mount:id=>{ if(id===\"issue\")spotGame(); if(id===\"policy\")remedyGame(); if(id===\"procedure\"){sortGame();apologyGame();} }},\n  \"wrong-order\":{id:\"wrong-order\",num:2,next:\"upset\",html:sec2HTML,quiz:QUIZ2,scenes:SCENES2,qq:QQ2,sort:SORT2,rush:RUSH2,\n    games:[{id:\"trace\",badge:\"Checkpoint Tracer\"},{id:\"lid\",badge:\"Label Checker\"},{id:\"bag\",badge:\"Bag Checker\"},{id:\"sort\",badge:\"Right Words\"},{id:\"rush\",badge:\"Counter Ready\"}],\n    sign:[[\"online\",\"Completed the online section and knowledge check\"],[\"rp1\",\"Demonstrated live: customer returns with the wrong order\"],[\"rp2\",\"Demonstrated live: hand-off mix-up affecting two customers\"],[\"walk\",\"Walked all five checkpoints on a live shift with the manager watching\"],[\"mgr\",\"Manager observed and confirmed the demonstrations\"]],\n    mount:id=>{ if(id===\"issue\")traceGame(); if(id===\"procedure\"){lidGame();bagGame();sortGame();} }},\n  \"upset\":{id:\"upset\",num:3,next:\"long-wait\",html:sec3HTML,quiz:QUIZ3,scenes:SCENES3,qq:QQ3,sort:SORT3,rush:RUSH3,log:LOG3,\n    games:[{id:\"spot\",badge:\"Breakdown Spotter\"},{id:\"gauge\",badge:\"Room Reader\"},{id:\"cool\",badge:\"Temperature Control\"},{id:\"sort\",badge:\"Right Words\"},{id:\"rush\",badge:\"Counter Ready\"}],\n    sign:[[\"online\",\"Completed the online section and knowledge check\"],[\"rp1\",\"Demonstrated live: upset customer at the counter after a long wait\"],[\"rp2\",\"Demonstrated live: customer whose behavior moves from upset to unsafe\"],[\"safety\",\"Can explain where service ends and safety begins, and the steps to take\"],[\"mgr\",\"Manager observed and confirmed the demonstrations\"]],\n    mount:id=>{ if(id===\"issue\")spotGame(); if(id===\"procedure\"){gaugeGame();coolGame();sortGame();} }},\n  \"long-wait\":{id:\"long-wait\",num:4,next:\"quality\",html:buildSection(SEC4),quiz:QUIZ4,scenes:SCENES4,qq:QQ4,sort:SORT4,rush:RUSH4,log:SEC4.log,\n    games:[{id:\"spot\",badge:\"Breakdown Spotter\"},{id:\"class\",badge:\"Delay Detective\"},{id:\"lobby\",badge:\"Lobby Keeper\"},{id:\"sort\",badge:\"Right Words\"},{id:\"rush\",badge:\"Counter Ready\"}],\n    sign:[[\"online\",\"Completed the online section and knowledge check\"],[\"rp1\",\"Demonstrated live: quoting a real time and updating before it passes\"],[\"rp2\",\"Demonstrated live: owning and recovering a ready order that went uncalled\"],[\"walk\",\"Ran the lobby on a live rush with the manager watching: quotes, updates, hand-offs\"],[\"mgr\",\"Manager observed and confirmed the demonstrations\"]],\n    mount:id=>{ if(id===\"issue\"){spotGame();classifyGame(CLASS4);} if(id===\"procedure\"){lobbyGame();sortGame();} }},\n  \"quality\":{id:\"quality\",num:5,next:\"change-dispute\",html:buildSection(SEC5),quiz:QUIZ5,scenes:SCENES5,qq:QQ5,sort:SORT5,rush:RUSH5,log:SEC5.log,\n    games:[{id:\"spot\",badge:\"Breakdown Spotter\"},{id:\"class\",badge:\"Safety Sorter\"},{id:\"qc\",badge:\"Quality Gate\"},{id:\"sort\",badge:\"Right Words\"},{id:\"rush\",badge:\"Counter Ready\"}],\n    sign:[[\"online\",\"Completed the online section and knowledge check\"],[\"rp1\",\"Demonstrated live: handling a quality complaint at the counter\"],[\"rp2\",\"Demonstrated live: a complaint that turns out to be food safety\"],[\"walk\",\"Ran a quality check at the cut table with the manager watching: ticket, bake, toppings, temperature\"],[\"mgr\",\"Manager observed and confirmed the demonstrations\"]],\n    mount:id=>{ if(id===\"issue\"){spotGame();classifyGame(CLASS5);} if(id===\"procedure\"){qualityGame();sortGame();} }},\n  \"change-dispute\":{id:\"change-dispute\",num:6,next:null,html:buildSection(SEC6),quiz:QUIZ6,scenes:SCENES6,qq:QQ6,sort:SORT6,rush:RUSH6,log:SEC6.log,\n    games:[{id:\"spot\",badge:\"Breakdown Spotter\"},{id:\"class\",badge:\"Fair Settler\"},{id:\"count\",badge:\"Exact Change\"},{id:\"sort\",badge:\"Right Words\"},{id:\"rush\",badge:\"Counter Ready\"}],\n    sign:[[\"online\",\"Completed the online section and knowledge check\"],[\"rp1\",\"Demonstrated live: a short-change dispute, handled as the neutral party\"],[\"rp2\",\"Demonstrated live: a card-charge dispute and a missed deal\"],[\"walk\",\"Demonstrated the count-back routine at the register with the manager watching\"],[\"mgr\",\"Manager observed and confirmed the demonstrations\"]],\n    mount:id=>{ if(id===\"issue\"){spotGame();classifyGame(CLASS6);} if(id===\"procedure\"){countGame();sortGame();} }}\n};\n/* ---------- router ---------- */\nfunction route(){\n  clearInterval(rushTimer); clearInterval(lobbyTimer);\n  const m=location.hash.match(/^#\\/m\\/([a-z-]+)\\/([a-z]+)/);\n  if(m&&SECTIONS[m[1]]){ SEC=SECTIONS[m[1]]; S=st(SEC.id); module(m[2]); } else { SEC=null; home(); window.scrollTo({top:0}); }\n}\nwindow.addEventListener(\"hashchange\",route);\nroute();\n</script>\n\n</body>\n</html>\n","PLAYBOOK":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<style>html{color-scheme:light dark}[hidden]{display:none!important}img{max-width:100%}</style>\n<title>Avoidable Moments Playbook</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,400..800&family=Source+Sans+3:ital,wght@0,400;0,600;0,700;1,400&family=JetBrains+Mono:wght@400;600&display=swap\">\n<style>\n:root{\n  --ground:#F3F5F2;--surface:#FFFFFF;--surface-2:#E9EDE8;--ink:#1B2530;--muted:#58656E;--line:#D3DAD4;\n  --accent:#0D7458;--accent-ink:#FFFFFF;--accent-soft:#DDEFE7;--warn:#A8521A;--warn-soft:#F7E6D8;--bad:#AE3328;--bad-soft:#F6DEDA;\n  --paper:#FFFEFA;--paper-ink:#23282C;\n  --display:\"Archivo\",\"Arial Narrow\",system-ui,sans-serif;--body:\"Source Sans 3\",\"Segoe UI\",system-ui,sans-serif;--mono:\"JetBrains Mono\",ui-monospace,Menlo,Consolas,monospace;\n}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]){\n  --ground:#11161B;--surface:#192027;--surface-2:#222B33;--ink:#E4EAED;--muted:#9AA7AF;--line:#2E3942;\n  --accent:#3DBB90;--accent-ink:#0B1A14;--accent-soft:#16342A;--warn:#E39A62;--warn-soft:#3A2618;--bad:#EE7F72;--bad-soft:#3B1D1A;--paper:#EDEBE3;--paper-ink:#1E2226;}}\n:root[data-theme=\"dark\"]{\n  --ground:#11161B;--surface:#192027;--surface-2:#222B33;--ink:#E4EAED;--muted:#9AA7AF;--line:#2E3942;\n  --accent:#3DBB90;--accent-ink:#0B1A14;--accent-soft:#16342A;--warn:#E39A62;--warn-soft:#3A2618;--bad:#EE7F72;--bad-soft:#3B1D1A;--paper:#EDEBE3;--paper-ink:#1E2226;}\n*{box-sizing:border-box}\nbody{background:var(--ground);color:var(--ink);font-family:var(--body);font-size:16.5px;line-height:1.5;margin:0;padding-inline:clamp(16px,4vw,40px);padding-block:0 64px}\nbutton{font:inherit;color:inherit;cursor:pointer}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px;border-radius:4px}\nh1,h2,h3,h4{font-family:var(--display);text-wrap:balance;margin:0;line-height:1.1}\nh1{font-size:clamp(2rem,5vw,3rem);font-variation-settings:\"wdth\" 80;font-weight:800}\nh2{font-size:clamp(1.4rem,3vw,1.9rem);font-variation-settings:\"wdth\" 84;font-weight:750}\nh3{font-size:1.1rem;font-variation-settings:\"wdth\" 95;font-weight:700}\np{margin:0}\n.wrap{max-width:1080px;margin-inline:auto}\n.eyebrow{font-family:var(--mono);font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.muted{color:var(--muted)}\n.bar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding-block:18px;border-bottom:1px solid var(--line);margin-bottom:30px}\n.brand b{font-family:var(--display);font-variation-settings:\"wdth\" 75;font-weight:800;font-size:1.25rem;text-transform:uppercase}\n.brand span{font-family:var(--mono);font-size:.72rem;color:var(--muted);letter-spacing:.08em;text-transform:uppercase;margin-left:8px}\n.btn{display:inline-flex;align-items:center;gap:8px;border:0;border-radius:8px;padding:9px 16px;background:var(--accent);color:var(--accent-ink);font-weight:700}\n.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--line)}\n.intro{display:grid;grid-template-columns:1.2fr 1fr;gap:36px;align-items:start;margin-bottom:34px}\n.intro .lede{font-size:1.15rem;max-width:58ch}\n.stack{display:grid;gap:14px}\n.guide{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px;margin-bottom:34px}\n.gcard{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:18px;display:grid;gap:8px;align-content:start}\n.gcard ul,.gcard ol{margin:0;padding-left:18px;display:grid;gap:5px;font-size:.95rem}\n.gcard.warn{border-color:var(--warn);background:var(--warn-soft)}\n.heat{display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin-top:4px}\n.heat span{font-family:var(--mono);font-size:.64rem;text-transform:uppercase;letter-spacing:.04em;text-align:center;padding:6px 2px;border-radius:4px;color:#fff}\n.filter{position:sticky;top:0;z-index:2;background:var(--ground);padding-block:10px;display:flex;gap:6px;flex-wrap:wrap;border-bottom:1px solid var(--line);margin-bottom:22px;align-items:center}\n.chip{border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:6px 13px;font-size:.88rem}\n.chip[aria-pressed=\"true\"]{background:var(--ink);color:var(--ground);border-color:var(--ink)}\n.filter .sp{flex:1}\n.secblock{display:grid;gap:18px;margin-bottom:40px}\n.sechead{display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap;border-bottom:2px solid var(--ink);padding-bottom:8px}\n.sechead h2{font-variation-settings:\"wdth\" 76;text-transform:uppercase;letter-spacing:.01em}\n.motto{font-family:var(--display);font-variation-settings:\"wdth\" 72;font-weight:800;text-transform:uppercase;font-size:.95rem;letter-spacing:.03em}\n.rp{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:22px;display:grid;gap:18px}\n.rp-top{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:flex-start}\n.code{font-family:var(--display);font-variation-settings:\"wdth\" 70;font-weight:800;font-size:2.2rem;line-height:1;color:var(--accent)}\n.rp-title{display:grid;gap:4px}\n.meta{display:flex;gap:6px;flex-wrap:wrap}\n.pill{font-family:var(--mono);font-size:.68rem;letter-spacing:.06em;text-transform:uppercase;padding:4px 9px;border-radius:999px;background:var(--surface-2);color:var(--muted);white-space:nowrap}\n.pill.heatpill{color:#fff}\n.cols{display:grid;grid-template-columns:1.15fr 1fr;gap:22px}\n.block{display:grid;gap:8px;align-content:start}\n.block h4{font-family:var(--mono);font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);font-weight:600}\n.brief{background:var(--surface-2);border-radius:8px;padding:12px 14px;font-size:.95rem}\n.opening{background:var(--paper);color:var(--paper-ink);border-radius:8px;padding:14px 16px;font-family:var(--display);font-variation-settings:\"wdth\" 90;font-weight:700;font-size:1.15rem;line-height:1.3}\n.opening small{display:block;font-family:var(--mono);font-weight:400;font-size:.68rem;letter-spacing:.1em;text-transform:uppercase;color:#6B737A;margin-bottom:4px}\ntable{border-collapse:collapse;width:100%;font-size:.92rem}\nth,td{text-align:left;vertical-align:top;padding:8px 10px;border-bottom:1px solid var(--line)}\nth{font-family:var(--mono);font-size:.68rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:600}\ntd.say{font-weight:600}\n.tbl{overflow-x:auto}\n.score li{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:start;padding:8px 0;border-bottom:1px solid var(--line);font-size:.94rem}\n.score{list-style:none;margin:0;padding:0}\n.boxes{display:flex;gap:10px;font-family:var(--mono);font-size:.7rem;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);white-space:nowrap}\n.boxes label{display:flex;gap:4px;align-items:center;cursor:pointer}\n.boxes input{width:16px;height:16px;accent-color:var(--accent);margin:0}\n.red{background:var(--bad-soft);border-radius:8px;padding:12px 14px;display:grid;gap:4px}\n.red h4{color:var(--bad)}\n.red ul{margin:0;padding-left:18px;font-size:.92rem;display:grid;gap:3px}\n.debrief{border-left:4px solid var(--accent);background:var(--accent-soft);padding:12px 14px;border-radius:0 8px 8px 0;display:grid;gap:4px}\n.debrief ul{margin:0;padding-left:18px;font-size:.93rem;display:grid;gap:3px}\n.variant{font-size:.92rem;border:1px dashed var(--line);border-radius:8px;padding:10px 12px}\n.variant b{font-family:var(--display);font-variation-settings:\"wdth\" 90}\n.signoff{background:var(--surface);border:1.5px solid var(--ink);border-radius:10px;padding:18px;display:grid;gap:14px}\n.sgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:18px 22px}\n.field{display:grid;gap:4px}\n.field span{font-family:var(--mono);font-size:.68rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}\n.field i{display:block;border-bottom:1.5px solid var(--ink);height:26px}\n.result{display:flex;gap:16px;flex-wrap:wrap;font-size:.92rem}\n.result label{display:flex;gap:6px;align-items:center}\n.result input{width:16px;height:16px;accent-color:var(--accent)}\n@media (max-width:820px){.intro,.cols{grid-template-columns:1fr}.heat span{font-size:.56rem}}\n@media print{\n  body{background:#fff;color:#000;font-size:11.5pt;padding:0}\n  :root{--ground:#fff;--surface:#fff;--surface-2:#F1F3F1;--ink:#111;--muted:#555;--line:#ccc;--accent:#0D7458;--accent-soft:#E8F3EE;--bad:#9E2A20;--bad-soft:#F8E8E6;--warn-soft:#FBF0E6;--paper:#F7F6F1;--paper-ink:#111}\n  .bar .btn,.filter{display:none}\n  .rp{break-inside:avoid-page;page-break-inside:avoid;border-color:#bbb}\n  .secblock{break-before:page}\n  .secblock[hidden]{display:none!important}\n  .intro,.guide{break-after:auto}\n}\n</style>\n\n</head>\n<body>\n<div class=\"wrap\">\n  <header class=\"bar\">\n    <div class=\"brand\"><b>Avoidable Moments</b><span>Manager role-play playbook</span></div>\n    <div style=\"display:flex;gap:8px;flex-wrap:wrap\"><a class=\"btn ghost\" href=\"/nibblenation\" style=\"text-decoration:none\">&larr; Hub</a><a class=\"btn ghost\" id=\"courseLink\" href=\"#\" target=\"_blank\" rel=\"noopener\" style=\"text-decoration:none\">Open the AGM course ↗</a><button class=\"btn\" type=\"button\" id=\"printAll\">Print what's shown</button></div>\n  </header>\n\n  <section class=\"intro\">\n    <div class=\"stack\">\n      <span class=\"eyebrow\">For the manager running the session</span>\n      <h1>Running the live role-plays</h1>\n      <p class=\"lede\">Every section of the AGM course ends with two live role-plays. You play the customer, the AGM handles it, and you score what you see. This playbook gives you the script, the curveball lines, the scorecard, and the debrief for all twelve.</p>\n      <p class=\"muted\">The AGM should finish the online section before the live session, so they walk in knowing the standard. The role-play is where they prove they can do it under pressure.</p>\n    </div>\n    <div class=\"gcard\">\n      <span class=\"eyebrow\">Heat levels</span>\n      <p style=\"font-size:.95rem\">Each role-play lists a starting heat. Turn it <b>up one level</b> when the AGM slips (defends, argues, dismisses) and <b>down one level</b> each time they get it right. A strong run ends calm.</p>\n      <div class=\"heat\"><span style=\"background:#B8942F\">Frustrated</span><span style=\"background:#C47826\">Upset</span><span style=\"background:#B5522A\">Angry</span><span style=\"background:#A0302A\">Hostile</span><span style=\"background:#6E1C2A\">Unsafe</span></div>\n    </div>\n  </section>\n\n  <section class=\"guide\" aria-label=\"How to run a session\">\n    <div class=\"gcard\"><h3>Before the session</h3><ul>\n      <li>Confirm the AGM finished that section's online part and knowledge check.</li>\n      <li>Book 20–30 minutes per section in a slow period, off the floor. Never run a role-play in front of real customers.</li>\n      <li>Print that section's page and gather the props listed.</li>\n      <li>For role-plays marked <b>Crew</b>, bring in a crew member to play the cashier. Brief them privately first.</li></ul></div>\n    <div class=\"gcard\"><h3>Running it</h3><ol>\n      <li>Read the AGM only the <b>AGM brief</b>. Don't show them the scorecard.</li>\n      <li>Stay in character. Use the opening line, then the curveballs when the AGM triggers them.</li>\n      <li>Adjust the heat as you go.</li>\n      <li>End when the customer would leave, usually 3–5 minutes.</li>\n      <li>Mark the scorecard right away, before the debrief.</li></ol></div>\n    <div class=\"gcard\"><h3>Scoring</h3><ul>\n      <li>Each <b>must-do</b> gets Meets or Not yet. There's no partial credit.</li>\n      <li><b>Pass:</b> every must-do marked Meets and no red flags.</li>\n      <li><b>Not yet:</b> debrief, then run it again right away. Allow up to three runs in one session.</li>\n      <li>Still not passing? Schedule another session within a week, and have them redo that section's practice stage first.</li></ul></div>\n    <div class=\"gcard\"><h3>The debrief</h3><ol>\n      <li><b>Ask first:</b> \"How did that feel? What would you change?\"</li>\n      <li><b>One strength:</b> quote the exact line or move that met the standard.</li>\n      <li><b>One change:</b> quote the exact line that missed, and give the line from the course.</li>\n      <li><b>Run it again</b> if anything was marked Not yet.</li></ol>\n      <p class=\"muted\" style=\"font-size:.9rem\">Keep it private, specific, and short. Coach the behavior, not the person.</p></div>\n    <div class=\"gcard warn\"><h3>Safety rules for role-play 3B</h3><ul>\n      <li>No physical contact, ever. Stay on opposite sides of the counter.</li>\n      <li>Agree on a stop word (\"Pause\") before you start. Either person can use it.</li>\n      <li>Never use real slurs or real profanity. Say \"[insult]\" instead.</li>\n      <li>Check in with the AGM and the crew member afterward.</li></ul></div>\n    <div class=\"gcard\"><h3>Recording the result</h3><ul>\n      <li>Check off the matching items on the course's Sign-off stage with the AGM.</li>\n      <li>Complete the sign-off block at the end of each section here and file it with the AGM's training record.</li>\n      <li><b>If the role-plays are part of a corrective action,</b> record the date, the scenarios run, and the result, and attach it to the corrective action file.</li></ul></div>\n  </section>\n\n  <nav class=\"filter\" aria-label=\"Show section\">\n    <span class=\"eyebrow\" style=\"margin-right:4px\">Show</span>\n    <button type=\"button\" class=\"chip\" data-f=\"all\" aria-pressed=\"true\">All</button>\n  </nav>\n\n  <main id=\"book\"></main>\n</div>\n\n<script>\nconst COURSE_URL = \"/nibblenation/avoidable-moments\";\nconst HEAT={Frustrated:\"#B8942F\",Upset:\"#C47826\",Angry:\"#B5522A\",Hostile:\"#A0302A\",Unsafe:\"#6E1C2A\"};\nconst BOOK=[\n {n:1,title:\"The Unpaid-Item Assumption\",motto:\"Verify first · Clarify second · Never accuse\",rps:[\n  {code:\"1A\",title:\"The drink on the counter\",time:\"5 min\",heat:\"Frustrated\",crew:false,\n   props:\"A bottled drink, a printed receipt or order ticket that includes the drink, and 1–2 people standing in as the line (optional).\",\n   agm:\"You're working the counter during a rush. A customer who picked up an order a few minutes ago sets a drink from the cooler on the counter. You don't remember ringing it up.\",\n   you:\"You paid for the drink with your order. You grabbed it from the cooler on your way out. You're calm and friendly until someone suggests you didn't pay.\",\n   open:\"(Set the drink on the counter and reach for your bag.) “Okay, I think that's everything.”\",\n   curve:[[\"States the price or asks “Did you pay for that?”\",\"“Excuse me? Are you saying I didn't pay for this?” (heat up)\"],[\"Asks for your receipt before checking the POS\",\"“Why do I have to prove anything? Check your own register.”\"],[\"Checks quietly with a neutral line\",\"Stay pleasant: “Sure, no problem.”\"],[\"Gives a vague apology (“Oh, you're good”)\",\"“That's it? You basically called me a thief in front of everybody.”\"]],\n   must:[\"Checks the POS transaction before saying anything about payment\",\"Uses a neutral, store-focused line (“Let me make sure we included that drink with your order.”)\",\"Keeps voice low and the moment private. No announcing to the line.\",\"Gives a full apology: the facts plus ownership (“I should have checked the transaction before questioning you.”)\"],\n   red:[\"States the price first\",\"Asks “Did you pay for that?”\",\"Explains why they were suspicious\"],\n   variant:\"Run it a second time where the drink is <b>not</b> on the order. The AGM should treat it as the store's miss: “It looks like the drink didn't get added. I can ring that up for you now.”\",\n   debrief:[\"What did the customer know about your intent in the first five seconds?\",\"What would the people in line have seen?\"]},\n  {code:\"1B\",title:\"The customer who's already upset\",time:\"5 min\",heat:\"Upset\",crew:true,\n   props:\"A crew member who has just asked the customer about payment without checking first.\",\n   agm:\"A crew member asked a customer about payment before checking the register. The customer is now upset. You step in.\",\n   you:\"You were embarrassed in front of other customers. You did pay. You want an apology that means something.\",\n   open:\"“You really think I'd steal a drink? In front of everybody?”\",\n   curve:[[\"Interrupts you\",\"Talk over them and get louder. (heat up)\"],[\"Says “Calm down”\",\"“Don't tell me to calm down!” (heat up)\"],[\"Gives a general apology (“Sorry for any confusion”)\",\"“Sorry for what, exactly?”\"],[\"Blames or corrects the crew member in front of you\",\"“So it's his fault? That doesn't help me.”\"],[\"Listens fully, then names what happened\",\"Lower your voice. (heat down)\"]],\n   must:[\"Lets the customer finish without interrupting\",\"Apologizes sincerely and names what happened (“You did pay, and we should have checked first.”)\",\"Offers a remedy that fits the embarrassment\",\"Doesn't correct the crew member in front of the customer, and says they'll retrain privately afterward\"],\n   red:[\"“Calm down”\",\"Defends the crew member's question\",\"Corrects the crew member publicly\"],\n   debrief:[\"At what point did the customer's volume start to drop?\",\"What will you say to the crew member privately?\"]}\n ]},\n {n:2,title:\"The Wrong Order\",motto:\"Own it · Fix it · Find it\",rps:[\n  {code:\"2A\",title:\"The pizza at home\",time:\"5 min\",heat:\"Upset\",crew:false,\n   props:\"A pizza box, and an order ticket showing the order was rung up as pepperoni.\",\n   agm:\"A customer walks in holding a pizza box. Two people are in line. When you pull up the order, hand them the ticket.\",\n   you:\"You ordered a large sausage, got pepperoni, and drove back. You're sure you said sausage.\",\n   open:\"“I ordered a large sausage. This is pepperoni. I drove all the way back.”\",\n   curve:[[\"Asks for your receipt before anything else\",\"“Seriously? I'm holding the box.”\"],[\"Says “The ticket says pepperoni”\",\"“So you're saying I'm lying?” (heat up)\"],[\"Blames the cashier\",\"“I don't care whose fault it is. I want my dinner.”\"],[\"Apologizes first and pulls up the order to fix it\",\"“...Okay. Thank you.” (heat down)\"],[\"Doesn't give a ready time\",\"“How long is this going to take?”\"]],\n   must:[\"Apologizes before investigating\",\"Pulls up the order to fix it, not to judge the customer\",\"Owns the read-back miss even though the ticket shows pepperoni\",\"Remakes it first in line, gives a real ready time, and offers a remedy for the trip (such as keeping the pepperoni)\",\"Confirms the corrected order with the customer before they leave, and names the checkpoint to retrain (Ring)\"],\n   red:[\"“That's what's on the ticket”\",\"Blames the crew in front of the customer\",\"“You must have ordered it wrong”\"],\n   debrief:[\"Which checkpoint failed, and how would you retrain it?\",\"Why did you apologize before checking the ticket?\"]},\n  {code:\"2B\",title:\"Two orders, one mix-up\",time:\"6 min\",heat:\"Upset\",crew:false,\n   props:\"Two order names that sound alike. You play both customers: first at the counter, then on the phone.\",\n   agm:\"A customer is waiting for an order that was handed to another customer a few minutes ago. Later, the other customer calls.\",\n   you:\"Customer 1: you've paid and your order is gone. Customer 2 (phone): you got home and the order isn't yours.\",\n   open:\"Customer 1: “My order should be ready. I paid twenty minutes ago.”\",\n   curve:[[\"Tells Customer 1 “Someone else took it”\",\"“So that's my problem?” (heat up)\"],[\"Asks Customer 2 “Didn't you check before you left?”\",\"“It's not my job to check your work.” (heat up)\"],[\"Owns it and starts Customer 1's order right away with a real time\",\"Settle down and wait. (heat down)\"]],\n   must:[\"Owns the hand-off miss with Customer 1 and starts their order right away with a real ready time\",\"On the call, listens, apologizes, and offers a fix without making Customer 2 feel at fault\",\"Makes it right for both customers, not just the one in front of them\",\"Plans private retraining on confirming name and items at hand-off\"],\n   red:[\"Blames the other customer\",\"“You should have checked”\",\"A sign asking customers to check orders offered as the fix\"],\n   debrief:[\"What would have stopped this at the counter?\",\"Did both customers get a full recovery?\"]}\n ]},\n {n:3,title:\"The Upset Customer\",motto:\"Lower it · Hear it · Fix it\",rps:[\n  {code:\"3A\",title:\"The long wait\",time:\"5 min\",heat:\"Angry\",crew:true,\n   props:\"A crew member playing a rattled cashier. Optional: 2–3 people as the line.\",\n   agm:\"A customer is shouting at your cashier about a long wait. Five people are in line.\",\n   you:\"You've waited 30 minutes. Your kids are waiting at home. Nobody has told you anything.\",\n   open:\"(Directed at the cashier) “Thirty minutes! This is the worst store in town!”\",\n   curve:[[\"Explains the delay before you're done\",\"“I don't want excuses!” (heat up)\"],[\"Says “Calm down” or “Don't talk to my employee like that”\",\"Get louder. (heat up)\"],[\"Lets you finish, then summarizes it back\",\"Your shoulders drop, and you answer more quietly. (heat down)\"],[\"Invites you aside respectfully\",\"Follow them.\"],[\"Offers a coupon for next time\",\"“What about tonight?”\"]],\n   must:[\"Steps in and relieves the cashier (“I'm the manager. I'll take care of you.”)\",\"Speaks lower and slower than the customer, with open posture\",\"Lets the customer finish, then summarizes it back\",\"Moves the conversation out of the line, offered as respect\",\"Owns it and fixes it tonight using full remedy authority\",\"Checks on the cashier afterward\"],\n   red:[\"“Calm down”\",\"“There's nothing I can do”\",\"Matching the customer's volume\"],\n   debrief:[\"What exact moment brought the heat down?\",\"What did your cashier need from you afterward?\"]},\n  {code:\"3B\",title:\"When it crosses the line\",time:\"5 min\",heat:\"Hostile\",crew:true,\n   props:\"A crew member. Agree on the stop word (“Pause”) before you begin. No physical contact.\",\n   agm:\"An upset customer is at the counter and starts directing insults at a crew member.\",\n   you:\"You're hostile toward the crew member. Partway through, you make a threat. Say “[insult]” instead of real profanity.\",\n   open:\"(At the crew member) “You're a [insult]. You can't even get a pizza right.”\",\n   curve:[[\"Curses back or threatens you\",\"Stop and debrief. This is an automatic red flag.\"],[\"Sets a respectful boundary and moves the crew member away\",\"Pause, then make the threat: “I'll be waiting outside when she gets off.”\"],[\"After the threat, keeps trying to fix the order\",\"Keep repeating the threat.\"],[\"Stops service, keeps distance, and says they're calling 911\",\"Leave. End of scene.\"]],\n   must:[\"Sets a respectful boundary (“I want to help you, and I need us to keep this respectful.”)\",\"Moves the crew member away from the customer\",\"After the threat, stops the service conversation, keeps the counter between them, keeps the crew member inside, and says they would call 911\",\"Afterward, makes sure the crew member gets to their car safely, notifies their supervisor, and documents what happened\"],\n   red:[\"Threatening back or any physical move\",\"Laughing off the threat\",\"Continuing to serve after the threat\"],\n   debrief:[\"At what exact line did service stop and safety take over?\",\"Who needs to know, and what do you write down?\"]}\n ]},\n {n:4,title:\"Order Not Ready on Time\",motto:\"Real time · Real updates · Real recovery\",rps:[\n  {code:\"4A\",title:\"The rush-hour promise\",time:\"6 min\",heat:\"Frustrated\",crew:false,\n   props:\"A note or screen showing “8 orders ahead,” and a phone timer. You'll call out a clock time partway through.\",\n   agm:\"It's a Friday rush. A customer orders two large pizzas and asks how long it will take.\",\n   you:\"You're in a hurry and plan around whatever time you're given.\",\n   open:\"“How long for two larges?”\",\n   curve:[[\"Quotes “about ten minutes” without checking\",\"Accept it, then at your cue: “It's been ten minutes. Where is it?” (heat up)\"],[\"Checks the screen and gives a clock time\",\"“Okay, thanks.”\"],[\"Updates you before the quoted time passes\",\"“I appreciate you telling me.” (heat down)\"],[\"Waits for you to ask\",\"“Were you going to tell me?”\"]],\n   must:[\"Checks the oven or order screen before quoting\",\"Gives a clock time, not a vague range\",\"Gives an update before the quoted time passes, with a new time and a reason\",\"Recovers at the hand-off with thanks, an apology for the delay, and a fitting remedy\"],\n   red:[\"A guessed quote\",\"Waiting for the customer to ask\",\"“It'll be a minute” or “It's almost ready”\"],\n   debrief:[\"Where did your quote come from?\",\"When exactly did you give the update, and why then?\"]},\n  {code:\"4B\",title:\"The forgotten order\",time:\"5 min\",heat:\"Upset\",crew:false,\n   props:\"A pizza box placed where the AGM can see it, standing in for the warmer.\",\n   agm:\"A customer approaches the counter. You notice their order has been sitting in the warmer.\",\n   you:\"You've waited 20 minutes. When you get the pizza, it's lukewarm.\",\n   open:\"“I've been waiting twenty minutes. Is my order ready?”\",\n   curve:[[\"Asks “Didn't you hear us call it?”\",\"“Nobody called anything.” (heat up)\"],[\"Hands it over without checking it\",\"Open the box: “This is barely warm.”\"],[\"Owns it and offers a fresh remake or a refund\",\"“A fresh one, please. Thank you.” (heat down)\"]],\n   must:[\"Owns the uncalled order plainly (“Your order was ready and we didn't call it. That's on us.”)\",\"Checks the product before handing it over\",\"Offers a choice: a fresh remake right away, or a refund\",\"Plans a fix: someone on the counter watches the warmer, plus private retraining\"],\n   red:[\"Blames the customer for not hearing\",\"Sends a lukewarm pizza\",\"Re-bakes the held pizza as the fix\"],\n   debrief:[\"Which minutes of this wait were most avoidable?\",\"Who watches the warmer on your next rush?\"]}\n ]},\n {n:5,title:\"Product Quality Complaint\",motto:\"Hear it · See it · Replace it\",rps:[\n  {code:\"5A\",title:\"The pale center\",time:\"5 min\",heat:\"Upset\",crew:false,\n   props:\"A pizza box. Optional: a photo of an underbaked center.\",\n   agm:\"A customer comes back with a half-eaten pizza and a complaint.\",\n   you:\"The middle was doughy. You ate some before you noticed. You want a proper pizza.\",\n   open:\"“The middle of this is doughy. It's not cooked.”\",\n   curve:[[\"Mentions how much you ate\",\"“So I should have thrown it away?” (heat up)\"],[\"Says “That's how it comes out”\",\"“Then your pizza's bad.” (heat up)\"],[\"Asks to look at it with you\",\"“Sure, look.” (heat down)\"],[\"Offers only a small discount\",\"“I don't want two dollars. I want a pizza.”\"]],\n   must:[\"Hears the complaint without defending the kitchen\",\"Asks to look at the product, framed as learning what happened\",\"Replaces it with no debate (fresh, first in line) and uses remedy authority\",\"Checks the remake before it goes out\",\"Plans to check the oven's time and temperature and the next few pizzas\"],\n   red:[\"“You ate half of it”\",\"“That's how it's supposed to be”\",\"Re-baking the half-eaten pizza\"],\n   debrief:[\"What did the pizza tell you about the oven?\",\"How will you check the next few pizzas?\"]},\n  {code:\"5B\",title:\"Something in the food\",time:\"5 min\",heat:\"Angry\",crew:false,\n   props:\"A pizza box and a small piece of plastic, or a stand-in object.\",\n   agm:\"A customer returns with a pizza and a complaint about something they found in it.\",\n   you:\"There was a piece of plastic in a slice. Your son almost bit into it. Nobody was hurt, but you're shaken.\",\n   open:\"“There was a piece of plastic in my pizza. My son almost bit into it.”\",\n   curve:[[\"Says “That's impossible”\",\"“Are you calling me a liar?” (heat up)\"],[\"Offers only a new pizza\",\"“I don't want another pizza from here.”\"],[\"Asks whether anyone is hurt first\",\"“He's okay. Thank you for asking.” (heat down)\"],[\"Moves to throw away the item\",\"“Shouldn't somebody keep that?”\"]],\n   must:[\"Asks whether anyone is hurt or feeling sick before anything else\",\"Doesn't argue or minimize\",\"Keeps the product and the object\",\"Refunds the order, notifies the store manager, and follows food-safety procedures\",\"Documents it and plans to find the source (make line and packaging)\"],\n   red:[\"Treats it as a quality complaint with a remake as the fix\",\"Throws the evidence away\",\"“It probably came from the box”\"],\n   debrief:[\"What made this a food-safety complaint instead of a quality one?\",\"Who did you notify, and what did you write down?\"]}\n ]},\n {n:6,title:\"Charge or Change Disputes\",motto:\"Count it · Show it · Settle it\",rps:[\n  {code:\"6A\",title:\"“I gave you a twenty”\",time:\"6 min\",heat:\"Upset\",crew:true,\n   props:\"Play money, a crew member playing the cashier, and a result card you draw after the count: <b>OVER $10</b> or <b>EVEN</b>.\",\n   agm:\"Your cashier and a customer are arguing over change. The line is watching.\",\n   you:\"You're sure you handed over a $20 and got change for a $10.\",\n   open:\"“I gave you a twenty! You gave me change for a ten!”\",\n   curve:[[\"Backs the cashier (“Our drawers are never wrong”)\",\"“So I'm a liar now?” (heat up)\"],[\"Says “Come back tomorrow”\",\"“I'm not driving back here for my own money.”\"],[\"Steps in as the neutral party and explains the count and how long it will take\",\"“Okay. I'll wait.” (heat down)\"],[\"Result card EVEN: explains it respectfully\",\"“I still think I gave you a twenty.” (Watch how they use their authority.)\"]],\n   must:[\"Steps in as the neutral party and moves the cashier to help the line\",\"Verifies under the company's cash procedure (such as a manager drawer count) and tells the customer what's happening and how long it will take\",\"If OVER: returns the money right away with a sincere apology\",\"If EVEN: explains respectfully without accusing, decides using full authority, and offers a same-day follow-up if needed\",\"Coaches the cashier privately on the count-back\"],\n   red:[\"Takes a side before checking\",\"Questions the cashier in front of the customer\",\"“Come back tomorrow” with no follow-up\"],\n   debrief:[\"How did you protect both the customer and your cashier?\",\"What would the count-back have prevented?\"]},\n  {code:\"6B\",title:\"The double charge\",time:\"5 min\",heat:\"Frustrated\",crew:false,\n   props:\"A phone showing two charges (a mock screenshot works), and a POS record or note showing one completed charge. Then a receipt with a deal that wasn't applied.\",\n   agm:\"A customer shows you their banking app. After that, a second customer has a question about a deal.\",\n   you:\"Customer 1: you're worried you were charged twice. Customer 2: your lunch deal wasn't applied.\",\n   open:\"Customer 1: “You charged me twice. Look.”\",\n   curve:[[\"Says “That's what the machine did” or “Call your bank”\",\"“So you're not going to help me?” (heat up)\"],[\"Pulls up the transaction with you and explains the temporary hold kindly\",\"“Oh, okay. That makes sense.” (heat down)\"],[\"Customer 2: says “The deal doesn't apply” without checking\",\"“It's on the sign right there.”\"]],\n   must:[\"Pulls up the transaction with the customer before responding\",\"Shows the single charge, explains a temporary bank hold kindly, and offers a way to follow up if it doesn't clear\",\"For the deal: checks whether it applies, and if it does, refunds the difference with an apology\",\"Never hides behind the register or sends the customer away without an answer\"],\n   red:[\"“The machine did it”\",\"“Call your bank” with no explanation\",\"“Too late, you already paid”\"],\n   debrief:[\"What did you show the customer, and why did it help?\",\"How did you check the deal before answering?\"]}\n ]}\n];\n\nconst book=document.getElementById(\"book\"), filter=document.querySelector(\".filter\");\nconst hp=h=>`<span class=\"pill heatpill\" style=\"background:${HEAT[h]}\">Start: ${h}</span>`;\nbook.innerHTML=BOOK.map(s=>`\n <section class=\"secblock\" data-s=\"${s.n}\">\n  <div class=\"sechead\"><h2>Section ${s.n} · ${s.title}</h2><span class=\"motto\">${s.motto}</span></div>\n  ${s.rps.map(r=>`\n  <article class=\"rp\" id=\"rp-${r.code}\">\n    <div class=\"rp-top\">\n      <div style=\"display:flex;gap:14px;align-items:flex-start\"><span class=\"code\">${r.code}</span>\n        <div class=\"rp-title\"><h3 style=\"font-size:1.3rem\">${r.title}</h3>\n          <div class=\"meta\"><span class=\"pill\">${r.time}</span>${hp(r.heat)}${r.crew?'<span class=\"pill\">Crew needed</span>':\"\"}</div></div></div>\n    </div>\n    <div class=\"cols\">\n      <div class=\"block\">\n        <h4>Props & setup</h4><p style=\"font-size:.94rem\">${r.props}</p>\n        <h4>Read to the AGM</h4><div class=\"brief\">${r.agm}</div>\n        <h4>Your character</h4><p style=\"font-size:.94rem\">${r.you}</p>\n        <div class=\"opening\"><small>Opening line</small>${r.open}</div>\n        <h4>Curveballs</h4>\n        <div class=\"tbl\"><table><thead><tr><th>If the AGM…</th><th>You…</th></tr></thead><tbody>${r.curve.map(c=>`<tr><td>${c[0]}</td><td class=\"say\">${c[1]}</td></tr>`).join(\"\")}</tbody></table></div>\n        ${r.variant?`<div class=\"variant\"><b>Second run: </b>${r.variant}</div>`:\"\"}\n      </div>\n      <div class=\"block\">\n        <h4>Scorecard · must-dos</h4>\n        <ul class=\"score\">${r.must.map((m,k)=>`<li><span>${m}</span><span class=\"boxes\"><label for=\"${r.code}-${k}-y\"><input type=\"checkbox\" id=\"${r.code}-${k}-y\">Meets</label><label for=\"${r.code}-${k}-n\"><input type=\"checkbox\" id=\"${r.code}-${k}-n\">Not yet</label></span></li>`).join(\"\")}</ul>\n        <div class=\"red\"><h4>Red flags · automatic “not yet”</h4><ul>${r.red.map(x=>`<li>${x}</li>`).join(\"\")}</ul></div>\n        <div class=\"debrief\"><h4 style=\"color:var(--accent)\">Debrief questions</h4><ul>${r.debrief.map(x=>`<li>${x}</li>`).join(\"\")}</ul></div>\n        <div class=\"result\"><span class=\"eyebrow\">Result</span>${[1,2,3].map(n=>`<label for=\"${r.code}-run${n}\"><input type=\"checkbox\" id=\"${r.code}-run${n}\">Run ${n} passed</label>`).join(\"\")}</div>\n      </div>\n    </div>\n  </article>`).join(\"\")}\n  <div class=\"signoff\">\n    <div style=\"display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap\"><h3>Section ${s.n} sign-off</h3><span class=\"eyebrow\">Role-plays ${s.rps.map(r=>r.code).join(\" & \")}</span></div>\n    <div class=\"sgrid\">\n      <div class=\"field\"><span>AGM name</span><i></i></div><div class=\"field\"><span>Manager name</span><i></i></div><div class=\"field\"><span>Store #</span><i></i></div><div class=\"field\"><span>Date</span><i></i></div>\n      <div class=\"field\"><span>${s.rps[0].code} result (pass / not yet)</span><i></i></div><div class=\"field\"><span>${s.rps[1].code} result (pass / not yet)</span><i></i></div>\n      <div class=\"field\"><span>AGM signature</span><i></i></div><div class=\"field\"><span>Manager signature</span><i></i></div>\n    </div>\n    <div class=\"field\"><span>Notes: strengths, what to keep working on, follow-up date</span><i></i><i></i></div>\n  </div>\n </section>`).join(\"\");\nBOOK.forEach(s=>{const b=document.createElement(\"button\");b.type=\"button\";b.className=\"chip\";b.dataset.f=s.n;b.setAttribute(\"aria-pressed\",\"false\");b.textContent=`${s.n} · ${s.title}`;filter.appendChild(b);});\nfilter.querySelectorAll(\".chip\").forEach(c=>c.onclick=()=>{\n  const f=c.dataset.f; filter.querySelectorAll(\".chip\").forEach(x=>x.setAttribute(\"aria-pressed\",x===c?\"true\":\"false\"));\n  document.querySelectorAll(\".secblock\").forEach(sb=>sb.hidden=!(f===\"all\"||sb.dataset.s===f));\n});\ndocument.getElementById(\"printAll\").onclick=()=>window.print();\ndocument.getElementById(\"courseLink\").href=COURSE_URL;\nfunction applyHash(){const m=location.hash.match(/^#s([1-6])$/); const c=filter.querySelector(`.chip[data-f=\"${m?m[1]:\"all\"}\"]`); if(c){c.click(); if(m) document.querySelector(`.secblock[data-s=\"${m[1]}\"]`).scrollIntoView();}}\nwindow.addEventListener(\"hashchange\",applyHash); applyHash();\n</script>\n\n</body>\n</html>\n"};
